import React from "react";
import {AccountModel} from "../../../../../../models/Account";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {planStyle} from "./styles/plan.style";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const Plan = (props: IProps) => {
  const {account} = props;
  const plan = account.Plan;
  const css = Styles.Hooks.useClassName(planStyle);

  if (plan == null) {
    return (
      <div className={css}>
        <span>{formatMessage("No plan")} → </span>
        <span>$0</span>
      </div>
    );
  }

  if (account.Status.isTrial) {
    return (
      <div className={css}>
        <span>{formatMessage("Trial plan")} → </span>
        <span>{formatMessage("Trial end in ")}{account.Status.dayLeftInTrial}</span>
      </div>
    );
  } else if (account.Status.isActive) {
    const price = formatMessage(`
        { type, select,
          1 {Monthly at {price}}
          12 {Yearly at {price}}
          other {Monthly at {price}}
        }
      `, {
      type: account.isYearlyBilling ? 12 : 1,
      price: account.isYearlyBilling ? plan.yearlyPlanPrice() : plan.Price()
    });

    return (
      <div className={css}>
        <span>{plan.name} → </span>
        <span>{price}</span>
      </div>
    );
  } else {
    return (
      <div className={css}>
        <span>{formatMessage("No plan")} → </span>
        <span>$0</span>
      </div>
    );
  }
};


export default Plan;
