import React, {MouseEvent} from "react";
import {Styles, VirtualizedList} from "@dashthis/ui";
import {accountDashboardWidgetsListSearchFieldStyle, accountDashboardWidgetsListStyle} from "./styles/accountDashboardWidgets.style";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {useWidgetTreeView, WidgetTreeItem} from "../hooks/useWidgetTreeView";
import AccountDashboardWidgetsWidgetItem from "./AccountDashboardWidgetsWidgetItem";
import {WidgetModel} from "../../../../../../../models/Widget";
import AccountDashboardWidgetsSourceItem from "./AccountDashboardWidgetsSourceItem";
import {SourceModel} from "../../../../../../../models/Source";
import {MultipleSelectIsItemAreSelected, MultipleSelectSelectItem} from "../hooks/useMultipleSelectItems";
import NoResultMessage from "../../../../SearchBar/components/NoResultMessage";
import formatMessage from "format-message";
import {AuthorizationModel} from "../../../../../../../models/Authorization";
import AccountDashboardWidgetsAuthorizationItemItem from "./AccountDashboardWidgetsAuthorizationItem";
import {SearchField} from "../../../../../../../components";

interface IProps {
  /**
   * The dashboard model
   */
  dashboard: DashboardModel,
  /**
   * Callback to select item in list
   */
  selectItem: MultipleSelectSelectItem;
  /**
   * Callback to check if item are selected.
   */
  isItemAreSelected: MultipleSelectIsItemAreSelected;
}

export const AccountDashboardWidgetsList = (props: IProps) => {
  const {dashboard, selectItem, isItemAreSelected} = props;
  const css = Styles.Hooks.useClassName(accountDashboardWidgetsListStyle);
  const searchFieldCss = Styles.Hooks.useClassName(accountDashboardWidgetsListSearchFieldStyle);
  const {
    widgets,
    toggleWidgetOpen,
    isWidgetAreOpen,
    searchFor
  } = useWidgetTreeView(dashboard);
  const renderItem = (item: WidgetTreeItem) => {
    const handlerItemClick = (i: WidgetModel | AuthorizationModel) => (e: MouseEvent<HTMLDivElement>) => {
      switch (i.__typename) {
        case "Widget":
          if (!i.isStatic) {
            selectItem({
              type: "widget",
              id: i.id!,
              widget: i
            }, e.shiftKey || e.altKey || e.metaKey);
          }
          break;
        case "Authorization":
          selectItem({
            type: "authorization",
            id: i.uiId,
            authorization: i
          }, e.shiftKey || e.altKey || e.metaKey);
          break;
      }

    };
    const handlerSourceClick = (source: SourceModel) => (e: MouseEvent<HTMLDivElement>) => {

      selectItem({
        type: "source",
        id: source.uiId,
        source
      }, e.shiftKey || e.altKey || e.metaKey);
    };
    const handlerArrowClick = (i: WidgetModel | AuthorizationModel) => {
      switch (i.__typename) {
        case "Authorization":
          toggleWidgetOpen(i.uiId);
          break;
        case "Widget":
          toggleWidgetOpen(i.id!);
          break;
      }
    };

    switch (item.type) {
      case "authorization":
        return (<AccountDashboardWidgetsAuthorizationItemItem
          authorization={item.authorization}
          selected={isItemAreSelected(item.authorization.uiId)}
          expended={isWidgetAreOpen(item.authorization.uiId)}
          onClick={handlerItemClick(item.authorization)}
          onArrowClick={handlerArrowClick}
        />);
      case "widget":
        return (
          <AccountDashboardWidgetsWidgetItem
            expended={isWidgetAreOpen(item.widget.id!)}
            onArrowClick={handlerArrowClick}
            selectable={!item.widget.isStatic!}
            selected={isItemAreSelected(item.widget.id!)}
            onClick={handlerItemClick(item.widget)}
            widget={item.widget}
          />
        );
      case "source":
        return (
          <AccountDashboardWidgetsSourceItem
            selected={isItemAreSelected(item.source.uiId)}
            onClick={handlerSourceClick(item.source)}
            source={item.source}
          />);
    }
  };
  const noResultCss = Styles.Hooks.useClassName({
    textAlign: "left"
  });
  const handleNoRowsRenderer = () => {
    return (<NoResultMessage className={noResultCss} message={formatMessage("This dashboard has no widgets")}/>);
  };

  return (
    <div className={css}>
      <SearchField.SearchField clearOnClick={() => {
        searchFor("");
      }} delayOnChange={100} onDelayChange={searchFor} placeholder={formatMessage("Search for widget")} className={searchFieldCss}/>
      <VirtualizedList.VirtualizedList noRowsRenderer={handleNoRowsRenderer} items={widgets} estimateSize={50} keyExtractor={(w) => w.id} renderItem={renderItem}/>
    </div>
  );
};


export default AccountDashboardWidgetsList;
