import React from "react";
import ItemPlaceHolder from "./ItemPlaceHolder";

interface IProps {

}

export const ListLoading = (props: IProps) => {
  const items: number[] = new Array(50).fill(1);

  return (
    <div>
      {items.map((i, k) => <ItemPlaceHolder key={k}/>)}
    </div>
  );
};

export default ListLoading;
