import React from "react";
import {Select, Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowInputStyle} from "./styles/fileTemplatesViewEditWindowInput.style";
import formatMessage from "format-message";

interface IProps extends Omit<Select.Types.ISelectProps<string>, "children"> {
}


export const ViewEditFileTemplateWindowSelectDataType = (props: IProps) => {
  const {...rest} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesViewEditWindowInputStyle);
  const getLabelFromValue = (value: string): string => {
    switch (value) {
      case "I":
        return formatMessage("Integer");
      case "D":
        return formatMessage("Decimal");
      case "P":
        return formatMessage("Percentage ( 0,176 => 17,6 % or 28 % => 28 %)");
      case "H":
        return formatMessage("Percentage (35 => 35 %)");
      case "R":
        return formatMessage("Rank");
      default:
        return formatMessage("Integer");
    }
  };

  return (
    <div className={css}>
      <Select.Select {...rest} label={getLabelFromValue(props.value as string)} value={props.value as string}>
        <Select.Body>
          <Select.Item value="I">{formatMessage("Integer")}</Select.Item>
          <Select.Item value="D">{formatMessage("Decimal")}</Select.Item>
          <Select.Item value="M">{formatMessage("Money")}</Select.Item>
          <Select.Item value="P">{formatMessage("Percentage ( 0,176 => 17,6 % or 28 % => 28 %)")}</Select.Item>
          <Select.Item value="H">{formatMessage("Percentage (35 => 35 %)")}</Select.Item>
          <Select.Item value="R">{formatMessage("Rank")}</Select.Item>
        </Select.Body>
      </Select.Select>
    </div>
  );
};


export default ViewEditFileTemplateWindowSelectDataType;
