import Monitor from "ping-monitor";
import {useEffect, useRef} from "react";
import {Hooks} from "@dashthis/common";

export const usePingUrl = (url: string) => {
  const myMonitor = useRef<any>(null);
  const [isUp, setIsUp] = Hooks.useStateIfMounted<boolean>(false);

  useEffect(() => {
    myMonitor.current = new Monitor({
      website: url,
      title: "Raging Flame",
      interval: 1 // minutes
    });

    myMonitor.current.on("up", () => {
      setIsUp(true);
    });

    myMonitor.current.on("error", () => {
      setIsUp(false);
    });

    myMonitor.current.on("down", () => {
      setIsUp(false);
    });

    return () => {
      myMonitor.current.stop();
    };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [url]);

  return isUp;
};