import {Client, DTGraphTypes} from "@dashthis/common";
import {widgetResetMutation} from "../queries/widget/resetDate.mutation";
import {Widget, WidgetModel} from "../models/Widget";
import {useCallback, useState} from "react";

export const useResetWidgetDate = (): [(widgets: WidgetModel[], date: Date) => Promise<WidgetModel[]>, boolean] => {
  const [mutation] = Client.Hooks.useMutation<DTGraphTypes.Widget, DTGraphTypes.MutationWidgetResetArgs>(widgetResetMutation);
  const [processing, setProcessing] = useState<boolean>(false);
  const resetWidgetDate = useCallback((widgets: WidgetModel[], date: Date): Promise<WidgetModel[]> => {
    const allUpdate: Promise<WidgetModel>[] = [];

    setProcessing(true);

    widgets.forEach((w) => {
      allUpdate.push(mutation({
        variables: {
          widgetId: w.id!,
          widget: {
            resetDate: date
          }
        }
      }).then((response) => {
        return Promise.resolve(Widget(response.data!));
      }));
    });

    return Promise.all(allUpdate).then((response) => {
      setProcessing(false);

      return Promise.resolve(response);
    }).finally(() => {
      setProcessing(false);
    });

  }, [mutation, setProcessing]);

  return [resetWidgetDate, processing];
};