import React from "react";
import {Form, Stack, Styles} from "@dashthis/ui";
import {Geography, Input, Label} from "../../../../../../components";
import formatMessage from "format-message";
import {Field, useFormikContext} from "formik";
import {IAccountInput} from "./AccountProperties";
import {accountInformationContainerStyle} from "./styles/accountInformation.style";

interface IProps {
}

export const AccountPropertiesForm = (props: IProps) => {
  const {values, setFieldValue, handleChange} = useFormikContext<IAccountInput>();
  const handleCountryChange = (e: React.ChangeEvent) => {
    setFieldValue("region", "");
    handleChange(e);
  };
  const css = Styles.Hooks.useClassName(accountInformationContainerStyle);

  return (
    <div className={css}>
      <Form.FormContainer>
        <Form.Item>
          <Label.Label>{formatMessage("Company name")}</Label.Label>
          <Field name="companyName" as={Input.Input}/>
        </Form.Item>
        <Form.Item>
          <Label.Label>{formatMessage("Address")}</Label.Label>
          <Form.StackItems>
            <Field name="address1" as={Input.Input}/>
            <Field name="address2" as={Input.Input}/>
          </Form.StackItems>
        </Form.Item>
        <Form.Item>
          <Label.Label>{formatMessage("Postal code")}</Label.Label>
          <Field name="postalCode" as={Input.Input}/>
        </Form.Item>
        <Form.Item>
          <Label.Label>{formatMessage("City")}</Label.Label>
          <Field name="city" as={Input.Input}/>
        </Form.Item>
        <Stack.HStack gap="1rem">
          <Form.Item>
            <Label.Label>{formatMessage("Country")}</Label.Label>
            <Geography.CountryPicker value={values.countryCode as any} onChange={handleCountryChange} name="countryCode"/>
          </Form.Item>
          <Form.Item>
            <Label.Label>{formatMessage("Region / State / Province")}</Label.Label>
            <Field name="region" forCountry={values.countryCode} as={Geography.StatePicker}/>
          </Form.Item>
        </Stack.HStack>
      </Form.FormContainer>
    </div>
  );
};

export default AccountPropertiesForm;
