import React, {HTMLAttributes} from "react";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {Conditional, Models} from "@dashthis/common";
import {accountPlanListItemNameStyle, accountPlanListItemOtherTextStyle, accountPlanListItemPriceStyle, accountPlanListItemRightStyle, accountPlanListItemSelectedStyle, accountPlanListItemStyle} from "./styles/accountPlanListItem.style";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  plan: Models.Plan.PlanModel;
  /**
   * Indicate if the plan are selected
   */
  selected: boolean;
}


export const AccountPlanListItem = (props: IProps) => {
  const {plan, selected, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountPlanListItemStyle,
    Conditional.is(selected, accountPlanListItemSelectedStyle)
  );
  const nameCss = Styles.Hooks.useClassName(accountPlanListItemNameStyle);
  const countCss = Styles.Hooks.useClassName(accountPlanListItemOtherTextStyle);
  const priceCss = Styles.Hooks.useClassName(accountPlanListItemPriceStyle, accountPlanListItemRightStyle);
  const yearlyPriceCss = Styles.Hooks.useClassName(accountPlanListItemOtherTextStyle, accountPlanListItemRightStyle);

  return (
    <div {...rest} className={css}>
      <p className={nameCss}>{plan.name}</p>
      <p className={priceCss}>{plan.Price()}</p>
      <p className={countCss}>{plan.nbDashboards} {formatMessage("Dashboards")}</p>
      <p className={yearlyPriceCss}>{formatMessage("Yearly price per month: ")} <strong>{plan.yearlyPlanPricePerMonth()}</strong></p>
    </div>
  );
};


export default AccountPlanListItem;
