import {FilterAccountsTaskbarCategory} from "./FilterAccounts/FilterAccountsTaskbarCategory";
import {OpenedAccountsTaskbarCategory} from "./OpenedAccounts/OpenedAccountsTaskbarCategory";
import {SearchHistoryTaskbarCategory} from "./Search/SearchHistoryTaskbarCategory";
import {SearchTaskbarItem} from "./Search/SearchTaskbarItem";
import {Styles, Taskbar} from "@dashthis/ui";
import formatMessage from "format-message";
import React from "react";
import {AccountFilter} from "../../../../../services/accountFilter/types";
import {TaskBarSelectedItem, TaskBarSelectedItemSearch} from "../../../../../states/types";
import {taskbarStyle} from "../styles/taskbar.style";
import {taskbarItemStyle} from "../styles/taskbarItem.style";
import {useGetCountForAllAndNewSignupsAccount} from "../../../../../hooks/useGetCountForAllAndNewSignupsAccount";
import {TaskBarItemTypeEnum} from "../../../../../enums/TaskBarItemTypeEnum";

export type TaskbarProps = {
  /**
   * Indicate which item are select in taskbar.
   */
  taskBarSelected: TaskBarSelectedItem,
  /**
   * Callback to select a item in taskbar.
   */
  setTaskBarSelected: (item: TaskBarSelectedItem) => void,
  /**
   * The list of custom filters.
   */
  accountFilters: AccountFilter[],
  /**
   * The list of all open accounts.
   */
  openedAccounts: Set<string>,
  /**
   * Callback to close a opened account.
   */
  closeAccounts: (accounts: Set<string>) => void,
  /**
   * Callback to perform a search.
   */
  setSearchQuery: (searchQuery: string) => void,
  /**
   * Callback to remove a item in reach history
   */
  deleteSearchHistory: (searchQuery: string) => void,
  /**
   * The list of all search made by the user.
   */
  searchHistories: string[],
  /**
   * Callback to clear all items in search history.
   */
  clearSearchHistory: () => void,
  /**
   * The current search  query
   */
  searchQuery: string
};

export const TaskBarComponent = (props: TaskbarProps) => {
  const {searchQuery, taskBarSelected, setTaskBarSelected, accountFilters, closeAccounts, openedAccounts, clearSearchHistory, deleteSearchHistory, searchHistories, setSearchQuery} = props;
  const [result, loading] = useGetCountForAllAndNewSignupsAccount();
  const handleListClick = (item: TaskBarItemTypeEnum) => () => {
    setTaskBarSelected({
      type: item
    });
  };
  const css = Styles.Hooks.useClassName(taskbarStyle);
  const taskbarItemCss = Styles.Hooks.useClassName(taskbarItemStyle);

  return (
    <Taskbar.Taskbar className={css} loading={loading}>
      <Taskbar.TaskbarCategory title={formatMessage("Lists")}>
        <Taskbar.TaskbarItem
          className={taskbarItemCss}
          text={formatMessage("All Accounts")}
          onClick={handleListClick(TaskBarItemTypeEnum.All)}
          count={result.allCount}
          selected={taskBarSelected.type === TaskBarItemTypeEnum.All}
        />
        {result.signupsCount > 0
          ? <Taskbar.TaskbarItem
            className={taskbarItemCss}
            text={formatMessage("New SignUp")}
            count={result.signupsCount}
            onClick={handleListClick(TaskBarItemTypeEnum.NewSingup)}
            selected={taskBarSelected.type === TaskBarItemTypeEnum.NewSingup}
          />
          : null}
        {searchQuery !== ""
          ? <SearchTaskbarItem searchQuery={searchQuery} selected={taskBarSelected as TaskBarSelectedItemSearch} onItemClick={setTaskBarSelected}/>
          : null
        }
      </Taskbar.TaskbarCategory>
      <FilterAccountsTaskbarCategory filters={accountFilters} selected={taskBarSelected} setTaskBarSelected={setTaskBarSelected}/>
      <SearchHistoryTaskbarCategory clearSearchHistory={clearSearchHistory} deleteSearchHistory={deleteSearchHistory} searchHistory={searchHistories} setSearchQuery={setSearchQuery}/>
      <OpenedAccountsTaskbarCategory closeAccounts={closeAccounts} selected={taskBarSelected} onItemClick={setTaskBarSelected} openedAccounts={openedAccounts}/>
    </Taskbar.Taskbar>
  );
};


export default TaskBarComponent;
