import {DTGraphTypes, Models, Search} from "@dashthis/common";
import {Integration, IntegrationModel} from "./Integration";
import {AuthorizationError, AuthorizationErrorModel} from "./AuthorizationError";
import formatMessage from "format-message";
import dayjs from "dayjs";
import {v4 as uuid} from "uuid";

export interface IAuthorization extends DTGraphTypes.Authorization, Search.Interfaces.IMatchableQuery {
  Integration: IntegrationModel | undefined,
  SourceError: AuthorizationErrorModel | undefined,
  hasError: boolean,
  dateFormatted: (col: "creationDate") => string,
  uiId: string
  clone: () => AuthorizationModel
}

export type AuthorizationModel = Models.Types.Model<Omit<IAuthorization, "integration" | "error">>;

export const Authorization: Models.Types.ModelCtr<DTGraphTypes.Authorization, IAuthorization> = (data) => ({
  ...data,
  uiId: uuid(),
  clone() {
    return Authorization({
      ...data
    });
  },
  get Integration() {
    return Models.createModel<DTGraphTypes.Integration, IntegrationModel>(data.integration, Integration);
  },
  get SourceError() {
    return Models.createModel<DTGraphTypes.AuthorizationError, AuthorizationErrorModel>(data.error, AuthorizationError);
  },
  get hasError() {
    return data.error != null;
  },
  dateFormatted(col) {
    if (data[col] == null) {
      return formatMessage("N/A");
    }

    const dateStr = dayjs(data[col]);

    return dateStr.calendar(undefined, {
      sameDay: "[Today at] H:mm a",
      nextDay: "[Tomorrow]",
      nextWeek: "dddd",
      lastDay: "[Yesterday]",
      lastWeek: "[Last] dddd",
      sameElse: "MMMM D, YYYY"
    });
  },
  matchQuery(query: string) {
    const searchableStrings = new Search.SearchableStrings(query);

    searchableStrings.add(data.name);
    searchableStrings.add(data.providerKey);
    searchableStrings.add(data.id);

    return searchableStrings.matchQuery();
  }
});