import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const SaveFileTemplateParts: DocumentNode = gql`
    fragment AccountPartsLastUpdatedItems on Account {
        id
        lastUpdatedItems {
            ... on CsvTemplate {
                id
                dateRangeSeparator
                encoding
                fields{
                    id
                    dataFormat
                    columnIndex
                    name
                    dataType
                    decimals
                    fieldType
                    lineIndex
                    sequence
                }
                footerLines
                headerLines
                name
                separator
            }
        }
    }
`;