import {StudioCSS} from "../../../../../../styles/types";

export const searchBarSearchHistoryStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-search-history",
  padding: utilities.space("n"),
  flex: "1 1 auto"
});

export const searchBarSearchHistoryTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-search-history-title",
  ...utilities.fontStyle({
    size: "small"
  }),
  opacity: .8
});

export const searchBarSearchHistoryNoItemsStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-search-history-no-items",
  ...utilities.fontStyle({
    size: "tiny"
  }),
  opacity: .6
});

export const searchBarSearchHistoryItemStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-search-history-item",
  display: "grid",
  gridTemplateColumns: "25px 1fr 25px",
  padding: utilities.space("t"),
  margin: utilities.space("t"),
  alignItems: "center",
  "&:hover": {
    background: utilities.colors("primary").string(),
    cursor: "pointer",
    color: utilities.colors("white").string(),
    svg: {
      fill: utilities.colors("white").string()
    }
  }
});

export const searchBarSearchHistoryItemIconStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-search-history-item-icon",
  width: "20px",
  height: "20px"
});

export const searchBarSearchHistoryItemClearIconStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-search-history-item-clear-icon",
  width: "16px",
  height: "16px"
});