import React from "react";
import {Account} from "@dashthis/common";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseSyncAccountWithThirdParties = [() => Promise<void>, boolean];

export const useSyncAccountWithThirdParties = (account: AccountModel): UseSyncAccountWithThirdParties => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);
  const syncAccountWithThirdParties = async () => {
    const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Syncing account...")}</Notification.LoadingNotification>);

    try {
      await updateAccount({
        syncWithThirdParties: true
      });
      Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The account has been successfully sync.")}</Notification.SuccessNotification>);
    } catch (e) {
      Services.clientService.Error.displayError(e, formatMessage("Syncing account error!"));
    } finally {
      hideLoadingNotification();
    }
  };

  return [syncAccountWithThirdParties, loading];
};