import {DTGraphTypes, Enums, Models} from "@dashthis/common";
import {EmptyUser, User, UserModel} from "./User";
import {CustomSettings, CustomSettingsModel} from "./CustomSettings";
import {DashboardSettings, DashboardSettingsModel} from "./DashboardSettings";
import {get, isEmpty, isNil} from "lodash";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import calendar from "dayjs/plugin/calendar";
import {Dashboard, DashboardModel} from "./Dashboard";
import emailParser from "email-addresses";
import {AccountHealth, AccountHealthModel} from "./AccountHealth";
import formatMessage from "format-message";
import {Invoice, InvoiceModel} from "./Invoice";
import {AccountStatusHistory, AccountStatusHistoryModel} from "./AccountStatusHistory";
import {sort} from "fast-sort";
import {CsvTemplate, CsvTemplateModel} from "./CsvTemplate";
import {Features, FeaturesModel} from "./Features";

dayjs.extend(relativeTime);
dayjs.extend(calendar);

type BillingInfo = {
  isYearlyBilling: boolean;
  paymentFrequency: DTGraphTypes.PaymentFrequenciesEnum;
  nextPaymentDate: string | null;
  lastPaymentDate: string | null;
  canBeProcessedAutomatically: boolean;
  hasPendingPaymentConfirmation: boolean;
  hasSkippedPayment: boolean;
  isPendingFrequencyDowngrade: boolean;
};

export interface IAccount extends DTGraphTypes.Account, Models.Bases.BaseAccount.IBaseAccount, Models.Interface.IComparable {
  CompanyName: string;
  Creator: UserModel | undefined;
  CsvTemplates: Models.Types.Models<CsvTemplateModel>;
  CustomSettings: CustomSettingsModel | undefined;
  StatusHistory: Models.Types.Models<AccountStatusHistoryModel>
  DashboardSettings: DashboardSettingsModel | undefined;
  Dashboards: Models.Types.Models<DashboardModel>;
  Healths: AccountHealthModel | undefined;
  Invoices: Models.Types.Models<InvoiceModel>;
  billingInfo: BillingInfo | undefined;
  nextBillingFrequency: () => Enums.Account.PaymentFrequenciesNumeralEnum,
  currentBillingFrequency: () => Enums.Account.PaymentFrequenciesNumeralEnum,
  Status: Models.AccountStatus.AccountStatusModel;
  Users: Models.Types.Models<UserModel>;
  Features: Models.Types.Models<FeaturesModel>;
  creation: string;
  domain: string;
  hasBillingInfo: boolean,
  isYearlyBilling: boolean;
  lastActivity: string;
  paymentFrequency: number;
  availableCreditsAmount: number;
}

export type AccountModel = Models.Types.Model<Omit<IAccount,
  "creator"
  | "customSettings"
  | "dashboardSettings"
  | "dashboards"
  | "statusHistory"
  | "healths"
  | "invoices"
  | "pricingPlanDetail"
  | "creditCard"
  | "users"
  | "features"
  | "csvTemplates">>;

export const Account: Models.Types.ModelCtr<DTGraphTypes.Account, IAccount> = (data) => ({
  ...data,
  // @ts-ignore
  Status: {
    isTrial: false,
    isActive: false,
    hasBeenTrial: false,
    hasBeenInactive: false,
    isPendingPayment: false,
    isArchived: false,
    isCanceled: false,
    isEndedTrial: false,
    isSuspended: false,
    isInactive: false,
    dayLeftInTrial: "100",
    dateFormatted: (col: "expireDate" | "startDate") => "",
    toString:()=> ""
  },
  nextBillingFrequency() {
    const nextPaymentFrequency = data.nextPaymentFrequency;

    if (nextPaymentFrequency === undefined || nextPaymentFrequency === -1) {
      return this.paymentFrequency;
    } else {
      return nextPaymentFrequency;
    }
  },
  currentBillingFrequency() {
    return this.paymentFrequency;
  },
  get Healths() {
    return Models.createModel<DTGraphTypes.AccountHealth, AccountHealthModel>(data.healths, AccountHealth);
  },
  get StatusHistory() {
    const history = Models.createModels<DTGraphTypes.AccountStatusHistory, AccountStatusHistoryModel>(data.statusHistory, AccountStatusHistory);

    return sort(history).desc((h) => h.appliedDateTime);
  },
  get Dashboards() {
    return Models.createModels<DTGraphTypes.Dashboard, DashboardModel>(data.dashboards, Dashboard);
  },
  get Features() {
    return Models.createModels<DTGraphTypes.Feature, FeaturesModel>(data.features, Features);
  },
  get CsvTemplates() {
    return Models.createModels<DTGraphTypes.CsvTemplate, CsvTemplateModel>(data.csvTemplates, CsvTemplate);
  },
  get Users() {
    return Models.createModels<DTGraphTypes.User, UserModel>(data.users, User);
  },
  get Invoices() {
    return Models.createModels<DTGraphTypes.Invoice, InvoiceModel>(data.invoices, Invoice);
  },
  get Creator() {
    if (data.creator == null) {
      return EmptyUser;
    }

    return Models.createModel<DTGraphTypes.User, UserModel>(data.creator, User);
  },
  get billingInfo(): BillingInfo | undefined {
    return (data as any).billingInfo as BillingInfo | undefined;
  },
  get CustomSettings() {
    return Models.createModel<DTGraphTypes.CustomSettings, CustomSettingsModel>(data.customSettings, CustomSettings);
  },
  get DashboardSettings() {
    return Models.createModel<DTGraphTypes.DashboardSettings, DashboardSettingsModel>(data.dashboardSettings, DashboardSettings);
  },
  get paymentFrequency() {
    const billingPaymentFrequency = (data as any).billingInfo?.paymentFrequency as DTGraphTypes.PaymentFrequenciesEnum | undefined;

    if (billingPaymentFrequency !== undefined) {
      return billingPaymentFrequency === DTGraphTypes.PaymentFrequenciesEnum.Annually ? 12 : 1;
    }

    return 1;
  },
  get domain(): string {
    if (data.creator != null) {
      const email = data.creator!.email;
      const emailParts = emailParser({input: email});

      return get(emailParts, "addresses[0].domain", "");
    }

    return "";
  },
  get isYearlyBilling() {
    const nextPaymentFrequency = data.nextPaymentFrequency;

    if (nextPaymentFrequency === undefined || nextPaymentFrequency === -1) {
      return this.paymentFrequency === 12;
    } else {
      return nextPaymentFrequency === 12;
    }
  },
  get hasBillingInfo() {
    return (!isEmpty(data.companyName)
      && !isEmpty(data.address1)
      && !isEmpty(data.city)
      && !isEmpty(data.countryCode)
      && !isEmpty(data.postalCode));
  },
  get lastActivity() {
    const lastActivityDate = dayjs(data.lastActivityDate);

    return lastActivityDate.calendar(undefined, {
      sameDay: "[Today at] H:mm a",
      nextDay: "[Tomorrow]",
      nextWeek: "dddd",
      lastDay: "[Yesterday]",
      lastWeek: "[Last] dddd",
      sameElse: "MMMM D, YYYY"
    });

  },
  get CompanyName() {
    return isNil(data.companyName) || isEmpty(data.companyName) ? formatMessage("No company") : data.companyName!;
  },
  get creation() {
    const creationDate = dayjs(data.creationDate);

    return creationDate.format("MMMM D, YYYY H:mm a");
  },
  get availableCreditsAmount() {
    return 0;
  },
  areSame(account) {
    if (isNil(account)) {
      return false;
    }

    return data.id!.toLowerCase() === account.id!.toLowerCase();
  },
  ...Models.Bases.BaseAccount.baseAccount(data)
});

export const EmptyAccount = Account({
  nextPaymentFrequency: 1
});