import React from "react";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {accountPlanNoActivePlanStyle} from "./styles/accountPlanNoActivePlan.style";

interface IProps {
}

export const AccountPlanNoActivePlan = (props: IProps) => {
  const css = Styles.Hooks.useClassName(accountPlanNoActivePlanStyle);

  return (
    <div className={css}>
      <p>{formatMessage("This account has no active subscription")}</p>
    </div>
  );
};


export default AccountPlanNoActivePlan;
