import React from "react";
import formatMessage from "format-message";
import {AccountManagerCriteria} from "./criteria/AccountManager";
import {LastSeenCriteria} from "./criteria/LastSeen";
import {CreationDateCriteria} from "./criteria/CreationDate";
import {StatusCriteria} from "./criteria/Status";
import {ExceedsDashboardCriteria} from "./criteria/ExceedsDashboard";
import {Styles} from "@dashthis/ui";
import {criteriasListNoItemsStyle, criteriasListStyle} from "../styles/criteriasList.style";
import {AccountFilterCriterias, AccountFilterState, SetCriteriaValue} from "../hooks/useAccountFilter";
import PlansCriteria from "./criteria/Plans";

interface ICriteriasProps {
  /**
   *
   */
  criterias: AccountFilterState
  /**
   * Account Filter model.
   */
  hasCriteria: (criteria: AccountFilterCriterias) => boolean,
  /**
   * Account Filter model.
   */
  deleteCriteria: (criteria: AccountFilterCriterias) => void,
  /**
   *
   */
  setCriteriaValue: SetCriteriaValue
}

export const CriteriasList = (props: ICriteriasProps) => {
  const {criterias, hasCriteria, deleteCriteria, setCriteriaValue} = props;
  const css = Styles.Hooks.useClassName(criteriasListStyle);
  const noItemsCss = Styles.Hooks.useClassName(criteriasListNoItemsStyle);

  return (
    <div className={css}>
      {hasCriteria("accountManager") ? <AccountManagerCriteria name="accountManager" label={formatMessage("account manager")} setCriteriaValue={setCriteriaValue} value={criterias.accountManager} onDeleteClick={deleteCriteria}/> : null}
      {hasCriteria("lowTierManager") ? <AccountManagerCriteria name="lowTierManager" label={formatMessage("low tier manager")} setCriteriaValue={setCriteriaValue} value={criterias.lowTierManager} onDeleteClick={deleteCriteria}/> : null}
      {hasCriteria("saleManager") ? <AccountManagerCriteria name="saleManager" label={formatMessage("sale manager")} setCriteriaValue={setCriteriaValue} value={criterias.saleManager} onDeleteClick={deleteCriteria}/> : null}
      {hasCriteria("lastSeen") ? <LastSeenCriteria setCriteriaValue={setCriteriaValue} value={criterias.lastSeen} onDeleteClick={deleteCriteria}/> : null}
      {hasCriteria("plan") ? <PlansCriteria setCriteriaValue={setCriteriaValue} value={criterias.plan} onDeleteClick={deleteCriteria}/> : null}
      {hasCriteria("status") ? <StatusCriteria setCriteriaValue={setCriteriaValue} value={criterias.status} onDeleteClick={deleteCriteria}/> : null}
      {hasCriteria("creationDate") ? <CreationDateCriteria setCriteriaValue={setCriteriaValue} value={criterias.creationDate} onDeleteClick={deleteCriteria}/> : null}
      {hasCriteria("exceedsDashboard") ? <ExceedsDashboardCriteria setCriteriaValue={setCriteriaValue} value={criterias.exceedsDashboard} onDeleteClick={deleteCriteria}/> : null}
      {criterias.criterias.length === 0 ? <div className={noItemsCss}>{formatMessage("No filters, click on Add filter to create new one.")}</div> : null}
    </div>
  );
};


export default CriteriasList;
