import {Styles} from "@dashthis/ui";
import React, {HTMLAttributes} from "react";
import {Conditional} from "@dashthis/common";
import {accountInvoicesItemDatePaidStyle, accountInvoicesItemDateStyle, accountInvoicesItemDescriptionStyle, accountInvoicesItemDetailsStyle, accountInvoicesItemEvenStyle, accountInvoicesItemIdStyle, accountInvoicesItemInfoStyle, accountInvoicesItemMetadataStyle, accountInvoicesItemOddStyle, accountInvoicesItemPaymentStyle, accountInvoicesItemSelectedStyle, accountInvoicesItemStatusStyle, accountInvoicesItemStyle, accountInvoicesItemTotalStyle} from "./styles/accountInvoicesItemStyle";
import {InvoiceModel} from "../../../../../../models/Invoice";
import numeral from "numeral";
import dayjs from "dayjs";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The invoice model.
   */
  invoice: InvoiceModel,
  /**
   * Indicate if the item are selected.
   */
  selected: boolean,
  /**
   * Indicate if row are odd and if true
   * draw white background
   */
  isOdd: boolean,
}

const AccountInvoicesItem = (props: IProps) => {
  const {selected, invoice, isOdd, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountInvoicesItemStyle,
    Conditional.is(isOdd, accountInvoicesItemOddStyle),
    Conditional.isNot(isOdd, accountInvoicesItemEvenStyle),
    Conditional.is(selected, accountInvoicesItemSelectedStyle)
  );
  const invoiceDetailsCss = Styles.Hooks.useClassName(accountInvoicesItemDetailsStyle);
  const invoiceInfoCss = Styles.Hooks.useClassName(accountInvoicesItemInfoStyle);
  const invoicePaymentCss = Styles.Hooks.useClassName(accountInvoicesItemPaymentStyle);
  const totalCss = Styles.Hooks.useClassName(accountInvoicesItemTotalStyle);
  const metadataCss = Styles.Hooks.useClassName(accountInvoicesItemMetadataStyle);
  const idCss = Styles.Hooks.useClassName(accountInvoicesItemIdStyle);
  const dateCss = Styles.Hooks.useClassName(accountInvoicesItemDateStyle);
  const descriptionCss = Styles.Hooks.useClassName(accountInvoicesItemDescriptionStyle);
  const statusCss = Styles.Hooks.useClassName(accountInvoicesItemStatusStyle);
  const datePaidCss = Styles.Hooks.useClassName(accountInvoicesItemDatePaidStyle);

  return (
    <div {...rest} className={css}>
      <div className={totalCss}>{numeral(invoice.subtotal).format("$0,0.00")}</div>
      <div className={invoiceDetailsCss}>
        <div className={invoiceInfoCss}>
          <div className={metadataCss}>
            <span className={idCss}># {invoice.displayNumber ?? invoice.id}</span>
            <span className={dateCss}>{dayjs(invoice.date).format("MMMM D, YYYY")}</span>
          </div>
          <div className={descriptionCss}>{invoice.description}</div>
        </div>
        <div className={invoicePaymentCss}>
          <div className={statusCss}>{invoice.isPaid ? "Paid" : "Unpaid"}</div>
          {invoice.isPaid
            ? <div className={datePaidCss}>{dayjs(invoice.datePaid).format("MMMM D, YYYY")}</div>
            : null
          }
        </div>
      </div>
    </div>
  );
};


export default AccountInvoicesItem;
