import {StudioCSS} from "../../../../../../../styles/types";

export const accountPlanCurrentNextPlanStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-current-next-plan",
  display: "grid",
  gridTemplateColumns: "1fr auto auto auto 1fr",
  alignItems: "center",
  gap: 30,
  borderBottom: `1px solid ${utilities.colors("aquaHaze").string()}`
});

export const accountPlanCurrentNextPlanCurrentStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-current-next-plan-current",
  justifySelf: "end"
});

export const accountPlanCurrentNextPlanNextStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-current-next-plan-current",
  justifySelf: "start"
});

export const accountPlanCurrentNextPlanProgressStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-current-next-plan-progress",
  textAlign: "center"
});

export const accountPlanCurrentNextPlanProgressDayLeftStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-current-next-plan-progress-day-left",
  ...utilities.fontStyle({
    weight: "m",
    size: "small",
    color: "scorpion"
  })
});

export const accountPlanCurrentNextPlanProgressNextDateStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-current-next-plan-progress-next-date",
  ...utilities.fontStyle({
    weight: "n",
    size: "small",
    color: "scorpion"
  })
});

export const accountPlanCurrentNextPlanNextContent: StudioCSS = (theme, utilities) => ({
  label: "account-plan-current-next-plan-next-content",
  textTransform: "uppercase",
  ...utilities.fontStyle({
    weight: "n",
    size: "regular"
  })
});
