import React, {useEffect} from "react";
import {Stack, Styles, VirtualizedList} from "@dashthis/ui";
import {AccountDashboardErrorReportModel} from "../../../../../../models/AccountDashboardErrorReport";
import DashboardReportItem from "./DashboardReportItem";
import {DashboardsGroupReport, useRegroupByDashboard} from "./hooks/useRegroupByDashboard";
import {DashboardReportNoResultMessage} from "./DashboardReportNoResultMessage";
import {AccountModel} from "../../../../../../models/Account";
import formatMessage from "format-message";
import {SearchField, Button} from "../../../../../../components";
import {dashboardsReportListFooterStyle} from "./styles/dashboardsReportList.style";
import {useExportToCsv} from "./hooks/useExportToCsv";

interface IProps {
  dashboardsReport: AccountDashboardErrorReportModel[];
  account: AccountModel;
}

export const DashboardsReportList = (props: IProps) => {
  const {dashboardsReport, account} = props;
  const renderItem = (item: DashboardsGroupReport) => {
    return <DashboardReportItem authorizations={item.authorizations} sources={item.sources} dashboard={item.dashboard}/>;
  };
  const {dashboards, query, onSearchChange, onClearClick} = useRegroupByDashboard(dashboardsReport);
  const renderNoRows = () => {

    return <DashboardReportNoResultMessage message={query !== "" ? formatMessage("Your search return no result.") : undefined}/>;
  };
  const {listRef, restoreScrollPosition, onScroll} = VirtualizedList.Hooks.useVirtualizedListScroll(`DashboardsReportList${account.id}`);
  const footerCss = Styles.Hooks.useClassName(dashboardsReportListFooterStyle);
  const {exportToCsv} = useExportToCsv();

  useEffect(() => {
    restoreScrollPosition();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <Stack.VStack>
      <Stack.StackItem as={SearchField.SearchField} onDelayChange={onSearchChange} clearOnClick={onClearClick} delayOnChange={50} defaultValue={query} placeholder={formatMessage("Search for dashboards, source or authorization...")}/>
      <Stack.StackItem itemSize="minmax(0,1fr)">
        <VirtualizedList.VirtualizedList onScroll={onScroll} listRef={listRef} noRowsRenderer={renderNoRows} items={dashboards} estimateSize={100} keyExtractor={(d) => d.dashboard.id!} renderItem={renderItem}/>
      </Stack.StackItem>
      <Stack.StackItem className={footerCss} as="div">
        <Button.Button onClick={() => exportToCsv(dashboards)} disabled={dashboards.length === 0}>{formatMessage("Export as CSV")}</Button.Button>
      </Stack.StackItem>
    </Stack.VStack>
  );
};

export default DashboardsReportList;
