import React, {useMemo} from "react";
import {Client, Endpoints, Enums, Token} from "@dashthis/common";
import {MultiProvider} from "@dashthis/ui";
import {RouteComponentProps} from "@reach/router";
import {combineReducers, createStore} from "redux";
import {configWriterReader as tokenConfigWriterReader, configWriterReader} from "../../storages/configWriterReader";
import {Provider} from "react-redux";
import {reducers} from "../../states";
import {accountFilterStorage} from "../../services/accountFilter/accountFilterStorage";
import {searchHistoryStorage} from "../../services/searchHistory/searchHistoryStorage";
import {appSettingStorage} from "../../services/appSettings/appSettingStorage";
import {appSettingService} from "../../services/appSettings/appSettingService";
import {AccountsManager} from "./components/AccountsManager";
import {createClient} from "../../client";
import {EndpointServiceValues, EndpointsServiceContext} from "../../services/context/EndpointsServiceContext";
import {FavoriteServiceContext} from "../../services/context/FavoriteServiceContext";
import {FileSystemServiceContext} from "../../services/context/FileSystemServiceContext";
import {endPointsStorage} from "../../endpoints/endPointsStorage";
import {useActivateMenuItemOnWindowFocus} from "../hooks/useActivateMenuItemOnWindowFocus";
import {AppSectionEnum} from "../enums/AppSectionEnum";
import {useActivateMenuItemSection} from "../hooks/useActivateMenuItemSection";
import {AppSettingsServiceContext} from "../../services/context/AppSettingsServiceContext";
import {TokenServiceContext} from "../../services/context/TokenServiceContext";
import {favoriteService} from "../../services/favoriteService/favoriteService";
import {electronFileSystemService} from "../../services/fileSystemService/electronFileSystemService";
import {tokenService} from "../../services/tokenService/tokenService";
import {favoriteStorage} from "../../services/favoriteService/favoriteStorage";

interface IProps extends RouteComponentProps {
  /**
   * The environment selected.
   */
  env?: Enums.EnvsEnum;
}

export const AccountManager = (props: IProps) => {
  const {env} = props;
  const endpoints = Endpoints.endpointStorage(endPointsStorage(env!));
  const asService = appSettingService(appSettingStorage(configWriterReader(env!)));
  const favService = favoriteService(favoriteStorage(configWriterReader(env!)));
  const tokService = tokenService(Token.tokenStorage(tokenConfigWriterReader(env!)));
  const store = useMemo(() => createStore(
    combineReducers({
      accountManager: reducers.accountManager(
        accountFilterStorage(accountFilterStorage(configWriterReader(env!))),
        searchHistoryStorage(searchHistoryStorage(configWriterReader(env!)))
      )
    })), [env]);
  const client = useMemo(() => createClient(env!), [env]);
  const endPointData: EndpointServiceValues = useMemo(() => ({
    for: env!,
    ...endpoints.get("endpoints")
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [env]);

  useActivateMenuItemOnWindowFocus(AppSectionEnum.AccountManager);
  useActivateMenuItemSection(AppSectionEnum.AccountManager);

  const providers = [
    <FileSystemServiceContext.Provider key={1} value={electronFileSystemService}/>,
    <TokenServiceContext.Provider key={2} value={tokService}/>,
    <AppSettingsServiceContext.Provider key={3} value={asService}/>,
    <FavoriteServiceContext.Provider key={5} value={favService}/>,
    <EndpointsServiceContext.Provider key={6} value={endPointData}/>
  ];

  return (
    <MultiProvider.MultiProviders providers={providers}>
      <Client.Provider client={client}>
        <Provider store={store}>
          <AccountsManager/>
        </Provider>
      </Client.Provider>
    </MultiProvider.MultiProviders>
  );
};


export default AccountsManager;