import React, {ReactNode} from "react";
import {Styles} from "@dashthis/ui";
import {IStudioTheme} from "../../styles/studioTheme";
import styled, {StyledTags} from "@emotion/styled";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
  /**
   *
   */
  fontWeight?: Styles.Types.FontWeight,
  /**
   *
   */
  fontSize?: keyof IStudioTheme["font"]["size"]
  /**
   *
   */
  fontColor?: keyof IStudioTheme["colors"]
  /**
   *
   */
  element?: keyof StyledTags;
}

interface IDefaultProps {
  fontWeight: Styles.Types.FontWeight,
  fontSize: keyof IStudioTheme["font"]["size"]
  fontColor: keyof IStudioTheme["colors"],
  element: "p" | "span"
}

const defaultProps: IDefaultProps = {
  fontColor: "primary",
  fontSize: "regular",
  fontWeight: "n",
  element: "p"
};

export const Typo = (props: IProps) => {
  const {element, fontColor, fontWeight, fontSize, ...rest} = props;
  const theme = Styles.Hooks.useTheme<IStudioTheme>();

  const css = Styles.Hooks.useClassName({
    ...Styles.Utilities.fontStyle({
      size: fontSize,
      color: fontColor,
      weight: fontWeight
    }, theme)
  });

  // @ts-ignore
  const Cmp = styled[element!]();

  return (
    <Cmp {...rest} className={css}/>
  );
};


Typo.defaultProps = defaultProps;

export default Typo;
