import {StudioCSS} from "../../../../../../../../styles/types";

export const fileTemplatesSourceItemStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-source-item",
  display: "grid",
  gridTemplateColumns: "10px 1fr auto",
  ...utilities.fontStyle({
    size: "regular",
    weight: "n"
  }),
  alignItems: "center",
  padding: `0 20px 0 30px`,
  minHeight: 40,
  "&:before": {
    content: `""`,
    borderLeft: `solid 1px ${utilities.colors("athensGray")}`,
    height: "100%"
  },
  span: {
    ...utilities.ellipsis()
  },
  "&:hover": {
    cursor: "pointer"
  }
});
