import {StudioCSS} from "../../../../../../../styles/types";

export const accountStatusHistoryItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-status-history-item",
  display: "grid",
  gridTemplateColumns: "1fr 35px 1fr"
});

export const accountStatusHistoryItemContentStyle: StudioCSS = (theme, utilities) => ({
  label: "account-status-history-item-content",
  alignSelf: "flex-end",
  justifySelf: "flex-end",
  textAlign: "right",
  marginBottom: -10
});

export const accountStatusHistoryItemContentInvertStyle: StudioCSS = (theme, utilities) => ({
  label: "account-status-history-item-content-invert",
  justifySelf: "flex-start",
  textAlign: "left"
});

export const accountStatusHistoryItemStatusInvertStyle: StudioCSS = (theme, utilities) => ({
  label: "account-status-history-item-status-invert",
  justifySelf: "flex-end"
});

export const accountStatusHistoryItemStatusStyle: StudioCSS = (theme, utilities) => ({
  label: "account-status-history-item-status",
  ...utilities.fontStyle({
    size: "regular",
    weight: "n"
  }),
  padding: utilities.space("n"),
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  background: utilities.colors("aquaHaze").string(),
  borderRadius: 2,
  alignSelf: "flex-end",
  justifySelf: "flex-start",
  marginBottom: -10
});

export const accountStatusHistoryItemDayStyle: StudioCSS = (theme, utilities) => ({
  label: "account-status-history-item-day",
  ...utilities.fontStyle({
    size: "small",
    weight: "m"
  })
});

export const accountStatusHistoryItemTimeStyle: StudioCSS = (theme, utilities) => ({
  label: "account-status-history-item-time",
  ...utilities.fontStyle({
    size: "small",
    weight: "n"
  })
});

export const accountStatusHistoryItemPathStyle: StudioCSS = (theme, utilities) => ({
  label: "account-status-history-item-path",
  width: 14,
  justifySelf: "center"
});