import React from "react";
import {Icon} from "../../../../../../components";
import {AccountModel} from "../../../../../../models/Account";
import AccountHeaderToolsButton from "./AccountHeaderToolsButton";
import formatMessage from "format-message";
import {useOpenUrlServiceContext} from "../../../../../../services/hooks/useOpenUrlServiceContext";
import {useEndpointsServiceContext} from "../../../../../../services/hooks/useEndpointsServiceContext";

interface IProps {
  /**
   * The account model
   */
  account: AccountModel;
}

export const AccountHeaderStripeButton = (props: IProps) => {
  const {account} = props;
  const {openUrl} = useOpenUrlServiceContext();
  const endpoints = useEndpointsServiceContext();
  const handleClick = () => {
    openUrl(endpoints.stripeCustomersEndpoint + account.billingCustomerId!);
  };

  if (account.billingCustomerId == null) {
    return null;
  }

  return (
    <AccountHeaderToolsButton onClick={handleClick} icon={Icon.Enums.Icons.Stripe} tooltip={formatMessage("Open in Stripe")}/>
  );
};


export default AccountHeaderStripeButton;
