import {ADD_OR_UPDATE_ACCOUNT_FILTER, ADD_SEARCH_HISTORY, CLEAR_OPEN_DASHBOARD, CLEAR_OPEN_FILE_TEMPLATE, CLEAR_OPEN_USER, CLEAR_SEARCH_HISTORY, CLOSE_ACCOUNTS, DELETE_ACCOUNT_FILTER, DELETE_SEARCH_HISTORY, OPEN_ACCOUNTS, OPEN_DASHBOARD, OPEN_FILE_TEMPLATE, OPEN_USER, SET_ACCOUNTS_SELECTED, SET_SEARCH_QUERY, SET_TASKBAR_SELECTED, SHOW_HIDE_QUICK_LOOK} from "../constants";
import {AccountManagerActionTypes} from "../actions";
import {accountFilterService} from "../../services/accountFilter/accountFilterService";
import {searchHistoryService} from "../../services/searchHistory/searchHistoryService";
import {SearchHistory, SearchHistoryStorage} from "../../services/searchHistory/types";
import {AccountFilter, AccountFilterStorage} from "../../services/accountFilter/types";
import {TaskBarSelectedItem, TaskBarSelectedItemAccount, TaskBarSelectedItemAccountFilter} from "../types";
import {TaskBarItemTypeEnum} from "../../enums/TaskBarItemTypeEnum";
import produce, {enableMapSet, setAutoFreeze} from "immer";

setAutoFreeze(false);
enableMapSet();

export type TaskBarSelected = {
  id?: string,
  filter?: AccountFilter,
  type: TaskBarItemTypeEnum
} | TaskBarItemTypeEnum;

export type OpenedDashboard = {
  account: string,
  dashboard: string
} | null;

export type OpenedUser = {
  account: string,
  user: string
} | null;

export type OpenedFileTemplate = {
  account: string,
  fileTemplate: string
} | null;

export interface IAccountManagerState {
  quickLookOpen: boolean;
  searchHistories: SearchHistory[];
  accountFilters: AccountFilter[];
  taskBarSelected: TaskBarSelectedItem;
  accountsSelected: Set<string>;
  openedAccounts: Set<string>;
  searchQuery: string,
  openedDashboard: OpenedDashboard,
  openedUser: OpenedUser,
  openedFileTemplate: OpenedFileTemplate
}

export const accountManagerReducer = (accountFilterStorage: AccountFilterStorage, searchHistoryStorage: SearchHistoryStorage) => {
  const afService = accountFilterService(accountFilterStorage);
  const shService = searchHistoryService(searchHistoryStorage);

  const createAccountManagerInitialState: IAccountManagerState = {
    /**
     * Indicate the quick look are open or close.
     */
    quickLookOpen: false,
    /**
     * The search history.
     */
    searchHistories: shService.get(),
    /**
     * The list of account filters.
     */
    accountFilters: afService.getAll(),
    /**
     * Indicate which item are selected in taskbar.
     */
    taskBarSelected: {
      type: TaskBarItemTypeEnum.All
    },
    /**
     * Indicate which account are selected in list.
     */
    accountsSelected: new Set(),
    /**
     * Indicate which account are open.
     */
    openedAccounts: new Set(),
    /**
     * The current search query
     */
    searchQuery: "",
    /**
     * Indicate which dashboard need to be open.
     */
    openedDashboard: null,
    /**
     * Indicate which user need to be open.
     */
    openedUser: null,
    /**
     * Indicate which file template need to be open.
     */
    openedFileTemplate: null
  };
  const removeFilterInTaskbarSelectedItem = (taskBarSelected: TaskBarSelectedItem, filter: AccountFilter): TaskBarSelectedItem => {
    const currentSelected = taskBarSelected as TaskBarSelectedItemAccountFilter;

    return currentSelected.id === filter.id
      ? {
        type: TaskBarItemTypeEnum.All
      }
      : taskBarSelected;
  };
  const removeAccountInTaskbarSelectedItem = (taskBarSelected: TaskBarSelectedItem, accounts: Set<string>): TaskBarSelectedItem => {
    const currentSelected = taskBarSelected as TaskBarSelectedItemAccount;

    return accounts.has(currentSelected.id)
      ? {
        type: TaskBarItemTypeEnum.All
      }
      : taskBarSelected;
  };

  return produce((state: IAccountManagerState = createAccountManagerInitialState, action: AccountManagerActionTypes) => {
    switch (action.type) {
      case ADD_SEARCH_HISTORY: {
        const searchQuery = action.searchQuery;

        state.searchHistories = shService.set(searchQuery);

        return state;
      }
      case SHOW_HIDE_QUICK_LOOK: {
        state.quickLookOpen = !state.quickLookOpen;

        return state;
      }

      case DELETE_ACCOUNT_FILTER: {
        const {filter} = action;
        const taskBarSelected = state.taskBarSelected;

        afService.remove(filter.id);

        state.accountFilters = afService.getAll();
        state.taskBarSelected = removeFilterInTaskbarSelectedItem(taskBarSelected, filter);

        return state;
      }

      case ADD_OR_UPDATE_ACCOUNT_FILTER: {
        const {filter} = action;

        afService.addOrUpdate(filter);

        state.accountFilters = afService.getAll();

        return state;
      }

      case SET_SEARCH_QUERY: {
        const searchQuery = action.searchQuery;

        state.taskBarSelected = {
          type: TaskBarItemTypeEnum.Searching
        };
        state.searchQuery = searchQuery;

        return state;
      }

      case DELETE_SEARCH_HISTORY: {
        const searchQuery = action.searchQuery;

        state.searchHistories = shService.remove(searchQuery);

        return state;
      }

      case CLEAR_SEARCH_HISTORY: {
        state.searchHistories = shService.clear();

        return state;
      }

      case SET_TASKBAR_SELECTED: {
        const item = action.item;

        state.taskBarSelected = item;

        return state;
      }

      case SET_ACCOUNTS_SELECTED: {
        const {account, multiple} = action;
        const selectedAccount = state.accountsSelected;

        if (multiple) {
          const accountId = account.id;

          if (selectedAccount.has(accountId!)) {
            selectedAccount.delete(accountId!);
          } else {
            selectedAccount.add(accountId!);
          }

          state.accountsSelected = selectedAccount;
        } else {
          state.accountsSelected = new Set([account.id!]);
        }

        return state;
      }

      case OPEN_ACCOUNTS: {
        const {accounts} = action;
        const currentOpenedAccounts = state.openedAccounts;
        const accountToBeOpen = Array.from(accounts.values()).filter((value) => !currentOpenedAccounts.has(value));
        const openedAccounts = [...accountToBeOpen, ...currentOpenedAccounts];

        state.openedAccounts = new Set(openedAccounts);
        state.taskBarSelected = {
          id: Array.from(accounts.values())[0],
          type: TaskBarItemTypeEnum.Account
        };

        return state;
      }

      case OPEN_USER: {
        const {account, user} = action;

        state.openedAccounts.add(account);
        state.openedUser = {
          account,
          user
        };
        state.taskBarSelected = {
          id: account,
          type: TaskBarItemTypeEnum.Account
        };

        return state;
      }

      case CLEAR_OPEN_USER: {
        state.openedUser = null;

        return state;
      }
      case OPEN_FILE_TEMPLATE: {
        const {account, fileTemplate} = action;

        state.openedAccounts.add(account);
        state.openedFileTemplate = {
          account,
          fileTemplate
        };
        state.taskBarSelected = {
          id: account,
          type: TaskBarItemTypeEnum.Account
        };

        return state;
      }
      case CLEAR_OPEN_FILE_TEMPLATE: {
        state.openedFileTemplate = null;

        return state;
      }
      case OPEN_DASHBOARD: {
        const {account, dashboard} = action;

        state.openedAccounts.add(account);
        state.openedDashboard = {
          account,
          dashboard
        };
        state.taskBarSelected = {
          id: account,
          type: TaskBarItemTypeEnum.Account
        };

        return state;
      }

      case CLEAR_OPEN_DASHBOARD: {
        state.openedDashboard = null;

        return state;
      }

      case CLOSE_ACCOUNTS: {
        const {accounts} = action;
        const openedAccounts = state.openedAccounts;
        const taskBarSelected = state.taskBarSelected;

        state.openedAccounts = new Set(Array.from(openedAccounts.values()).filter((value) => !accounts.has(value)));
        state.taskBarSelected = removeAccountInTaskbarSelectedItem(taskBarSelected, accounts);

        return state;
      }

      default:
        return state;
    }
  });
};

