import {Client, DTGraphTypes} from "@dashthis/common";
import {Account, EmptyAccount} from "../models/Account";
import {accountStatusHistoryQuery} from "../queries/account/accountStatusHistory.query";
import {AccountStatusHistoryModel} from "../models/AccountStatusHistory";
import {useMemo} from "react";

type Response = {
  account: DTGraphTypes.Account
};

type QueryArgs = {
  id: string,
};

export const useGetAccountStatusHistory = (id: string): [AccountStatusHistoryModel[], boolean, Client.Errors.ApplicationServerError] => {
  const variables = {
    id
  };
  const [data, error, loading] = Client.Hooks.useApolloQuery<QueryArgs, Response>(accountStatusHistoryQuery, {
    variables
  });

  return useMemo(() => ([
    loading || error != null ? EmptyAccount.StatusHistory : Account(data.account).StatusHistory,
    loading, error
  ]), [data, error, loading]);
};