import {useContext} from "react";
import {IAppSettingService} from "../appSettings/appSettingService";
import {AppSettingsServiceContext} from "../context/AppSettingsServiceContext";

export const useAppSettingsServiceContext = (): IAppSettingService => {
  const appSettingsService = useContext<IAppSettingService>(AppSettingsServiceContext);

  return appSettingsService;
};