import React, {Fragment} from "react";
import ViewEditFileTemplateWindowSubHeader from "./ViewEditFileTemplateWindowSubHeader";
import formatMessage from "format-message";
import ViewEditFileTemplateWindowText from "./ViewEditFileTemplateWindowText";
import {Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowSettingSectionStyle} from "./styles/fileTemplatesViewEditWindow.style";
import ViewEditFileTemplateWindowHeader from "./ViewEditFileTemplateWindowHeader";
import {CsvTemplateModel} from "../../../../../../../../models/CsvTemplate";
import ViewEditFileTemplateWindowRangeSeparator from "./ViewEditFileTemplateWindowRangeSeparator";
import ViewEditFileTemplateWindowSelectSeparator from "./ViewEditFileTemplateWindowSelectSeparator";
import ViewEditFileTemplateWindowSelectEncoding from "./ViewEditFileTemplateWindowSelectEncoding";
import {Field} from "formik";
import ViewEditFileTemplateWindowInput from "./ViewEditFileTemplateWindowInput";

interface IProps {
  /**
   * The csv template model.
   */
  csvTemplate: CsvTemplateModel;

}

export const ViewEditFileTemplateWindowSettingSection = (props: IProps) => {
  const headerSectionCss = Styles.Hooks.useClassName(fileTemplatesViewEditWindowSettingSectionStyle);

  return (
    <Fragment>
      <ViewEditFileTemplateWindowHeader>{formatMessage("Settings")}</ViewEditFileTemplateWindowHeader>
      <div className={headerSectionCss}>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("Key")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("Value")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowText>{formatMessage("Date Range Separator")}</ViewEditFileTemplateWindowText>
        <Field as={ViewEditFileTemplateWindowRangeSeparator} name="dateRangeSeparator"/>
        <ViewEditFileTemplateWindowText>{formatMessage("Separator")}</ViewEditFileTemplateWindowText>
        <Field as={ViewEditFileTemplateWindowSelectSeparator} name="separator"/>
        <ViewEditFileTemplateWindowText>{formatMessage("Encoding")}</ViewEditFileTemplateWindowText>
        <Field as={ViewEditFileTemplateWindowSelectEncoding} name="encoding"/>
        <ViewEditFileTemplateWindowText>{formatMessage("Lines in header\t")}</ViewEditFileTemplateWindowText>
        <Field name="headerLines" as={ViewEditFileTemplateWindowInput}/>
        <ViewEditFileTemplateWindowText>{formatMessage("Lines in footer\t")}</ViewEditFileTemplateWindowText>
        <Field name="footerLines" as={ViewEditFileTemplateWindowInput}/>
      </div>
    </Fragment>
  );
};


export default ViewEditFileTemplateWindowSettingSection;
