import React from "react";
import {Icon, Input, Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowInputIconStyle, fileTemplatesViewEditWindowInputStyle} from "./styles/fileTemplatesViewEditWindowInput.style";

interface IProps extends Input.Types.IInputProps {
}


export const ViewEditFileTemplateWindowInput = (props: IProps) => {
  const {...rest} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesViewEditWindowInputStyle);
  const iconCss = Styles.Hooks.useClassName(fileTemplatesViewEditWindowInputIconStyle);

  return (
    <div className={css}>
      <Input.Icon className={iconCss} icon={Icon.Enums.Icons.Pencil}>
        <Input.Input {...rest}/>
      </Input.Icon>
    </div>
  );
};


export default ViewEditFileTemplateWindowInput;
