import {Client, DTGraphTypes} from "@dashthis/common";
import {SearchFileTemplateResponse} from "./types";
import {AccountModel} from "../../../../../models/Account";
import {formatAccountSearchResponse} from "./formatResponse";
import {cloneDeep, isNil} from "lodash";
import {useMemo} from "react";
import {searchFileTemplatesQuery} from "../../../../../queries/search/searchFileTemplates";

type UseSearchFileTemplates = {
  accounts: AccountModel[],
  loading: boolean,
  error: Client.Errors.ApplicationServerError
  count: number
}

const groupByAccount = (response: SearchFileTemplateResponse): DTGraphTypes.Account[] => {
  const accounts: Map<string, DTGraphTypes.Account> = new Map();

  if (isNil(response.fileTemplates.items)) {
    return Array.from(accounts.values());
  }

  response.fileTemplates.items.forEach((f) => {
    if (f.account != null) {
      let account = cloneDeep(f.account!);

      if (accounts.has(account.id!)) {
        account = accounts.get(account.id!)!;
      }

      if (isNil(account.csvTemplates)) {
        account.csvTemplates = [];
      }
      account.csvTemplates.push(f);
      accounts.set(account.id!, account);
    }
  });

  return Array.from(accounts.values());
};

export const useSearchFileTemplates = (query: string): UseSearchFileTemplates => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<DTGraphTypes.QuerySearchUsersArgs, SearchFileTemplateResponse>(searchFileTemplatesQuery, {
    variables: {
      query,
      limit: 5
    }
  });

  return useMemo<UseSearchFileTemplates>(() => ({
    accounts: loading || error != null ? [] : formatAccountSearchResponse(groupByAccount(data)),
    count: loading || error != null ? 0 : data.fileTemplates.count,
    error,
    loading
  }), [data, error, loading]);

};

export default useSearchFileTemplates;