import {useAccountManagerStateActions, useAccountManagerStateSelector} from "../../../../../../../states/hooks";
import {useEffect, useState} from "react";
import {CsvTemplateModel} from "../../../../../../../models/CsvTemplate";
import {SelectedItem} from "../list/FileTemplatesList";

export const useOpenFileTemplate = (fileTemplates: CsvTemplateModel[], selectedItem: SelectedItem, setSelectedItem: (item: SelectedItem) => void): number => {
  const openedFileTemplate = useAccountManagerStateSelector("openedFileTemplate");
  const {clearOpenFileTemplate} = useAccountManagerStateActions();
  const [position, setPosition] = useState<number>(0);

  useEffect(() => {
    if (openedFileTemplate != null && (selectedItem == null || selectedItem.id !== openedFileTemplate.fileTemplate)) {
      setSelectedItem(fileTemplates.find((f) => f.id === openedFileTemplate.fileTemplate)!);
      const index = fileTemplates.findIndex((f) => f.id === openedFileTemplate.fileTemplate);

      if (index !== -1) {
        setPosition(index);
      }

      clearOpenFileTemplate();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openedFileTemplate]);

  return position;
};