import {StudioCSS} from "../../../../../../styles/types";

export const accountManagerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  gridTemplateRows: "auto"
});

export const accountManagerGravatarStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-gravatar",
  width: 24,
  height: 24,
  gridColumn: 2,
  gridRow: "1 / 3",
  marginLeft: utilities.space("s"),
  alignSelf: "center"
});

export const accountManagerNameStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-name",
  ...utilities.fontStyle({
    size: "regular"
  }),
  textAlign: "end",
  ...utilities.ellipsis()
});

export const accountManagerNotAssignedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-name-not-assigned",
  float: "right"
});

export const accountManagerStatusStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-status",
  ...utilities.fontStyle({
    size: "small",
    weight: "l",
    color: "scorpion"
  }),
  gridColumn: 1,
  textAlign: "end",
  ...utilities.ellipsis()
});
