import {useAccountManagerStateActions, useAccountManagerStateSelector} from "../../../../../../../states/hooks";
import {useEffect} from "react";
import {UserModel} from "../../../../../../../models/User";

export const useSelectOpenedUser = (users: UserModel[], userSelected: UserModel | null, setUserSelected: (user: UserModel | null) => void) => {
  const openedUser = useAccountManagerStateSelector("openedUser");
  const {clearOpenUser} = useAccountManagerStateActions();

  useEffect(() => {
    if (openedUser != null &&  (userSelected == null || userSelected.id !== openedUser.user)) {
      setUserSelected(users.find((u) => u.id === openedUser.user)!);
      clearOpenUser();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openedUser, userSelected, setUserSelected, users]);

};