import {StudioCSS} from "../../../../../../../../styles/types";

export const fileTemplatesSelectItemStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-select-item",
  display: "flex",
  alignItems: "center",
  flexDirection: "column",
  justifyContent: "center",
  textTransform: "uppercase",
  padding: utilities.space("l"),
  textAlign:"center"
});

export const fileTemplatesSelectItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-select-item-title",
  paddingBottom: utilities.space("m"),
  ...utilities.fontStyle({
    weight: "m",
    size: "large"
  })
});

export const fileTemplatesSelectItemPlaceholderStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-select-item-placeholder",
  width: 146,
  height: 96
});

export const fileTemplatesSelectItemDescriptionStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-select-item-description",
  paddingTop: utilities.space("m"),
  ...utilities.fontStyle({
    weight: "n",
    size: "regular"
  })
});
