import {SearchHistory, SearchHistoryStorage} from "./types";

export const searchHistoryService = (storage: SearchHistoryStorage) => ({

  set(query: string): SearchHistory[] {
    const histories = this.get();

    if (query === "") {
      return histories;
    }

    if (histories.indexOf(query) === -1) {
      histories.unshift(query);
      storage.set("searchHistory", histories);
    }

    return histories;
  },

  remove(query: string): SearchHistory[] {
    const history = this.get();
    const pos = history.indexOf(query);

    if (pos !== -1) {
      history.splice(pos, 1);
      storage.set("searchHistory", history);

      return history;
    }

    return history;
  },

  clear(): SearchHistory[] {
    storage.set("searchHistory", []);

    return [];
  },

  get(): SearchHistory[] {
    return storage.get("searchHistory", []);
  }
});