import {Client, DTGraphTypes} from "@dashthis/common";
import {Account, EmptyAccount} from "../models/Account";
import {InvoiceModel} from "../models/Invoice";
import {accountInvoicesQuery} from "../queries/account/accountInvoices.query";
import {useCallback, useMemo} from "react";

type Response = {
  account: DTGraphTypes.Account
};

type QueryArgs = {
  id: string,
};

export type UseGetAccountInvoices = {
  loading: boolean,
  error: Client.Errors.ApplicationServerError,
  invoices: InvoiceModel[],
  addInvoiceToCache: (invoice: InvoiceModel) => void
};

export const useGetAccountInvoices = (id: string): UseGetAccountInvoices => {
  const variables = {
    id
  };
  const [data, error, loading, addInvoice] = Client.Hooks.useApolloQuery<QueryArgs, Response>(accountInvoicesQuery, {
    variables
  });
  const addInvoiceToCache = useCallback((invoice: InvoiceModel) => {
    addInvoice(invoice.source, "account.invoices");
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return useMemo(() => ({
    invoices: loading || error != null ? EmptyAccount.Invoices : Account(data.account).Invoices,
    loading,
    error,
    addInvoiceToCache
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [data, error, loading]);

};