import React from "react";
import {AccountFilterDialog as Dialog, AccountFilterDialogProps as DialogProps} from "../components/Dialog";
import {useAccountManagerStateActions} from "../../../../../../states/hooks";

type AccountFilterDialogProps = {} & Omit<DialogProps, "deleteAccountFilter" | "addOrUpdateAccountFilter">;

export const AccountFilterDialog = (props: AccountFilterDialogProps) => {
  const {deleteAccountFilter, addOrUpdateAccountFilter} = useAccountManagerStateActions();

  return (
    <Dialog addOrUpdateAccountFilter={addOrUpdateAccountFilter} deleteAccountFilter={deleteAccountFilter} {...props}/>
  );
};


export default AccountFilterDialog;
