import React from "react";
import {Styles} from "@dashthis/ui";
import {healthBoxStyle} from "./styles/healthBox.style";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../../models/Account";
import {Account as AccountCommon} from "@dashthis/common";

const {extractSourcesUsage} = AccountCommon.Utilities;

interface IProps {
  /**
   * Component children.
   */
  account: AccountModel;
}

export const PlanUsage = (props: IProps) => {
  const css = Styles.Hooks.useClassName(healthBoxStyle);
  const {account} = props;
  const plan = account.Plan;
  const sourcesUsage = extractSourcesUsage(account.usageLimits);

  return (
    <div className={css}>
      {plan == null
        ? <span>N/A</span>
        : <span>{account.dashboardsUsed!}/{plan!.nbDashboards}{sourcesUsage ? ` \u30fb ${sourcesUsage.used}/${sourcesUsage.limit}` : ""}</span>
      }
      <span>{sourcesUsage ? formatMessage("Dashboards \u30fb Sources") : formatMessage("Plan usage")}</span>
    </div>
  );
};


export default PlanUsage;
