import {Icon, Select, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import React from "react";
import {AccountFilterCriterias, SetCriteriaValue} from "../../hooks/useAccountFilter";
import {criteriasListItemDeleteIconStyle, criteriasListItemStyle} from "../../styles/criteriasList.style";
import {AccountManagerSelect} from "../../../../../../../components/Selects/AccountManagerSelect";

interface IProps {
  /**
   * The default account manager selected.
   */
  value?: string;
  /**
   * Callback when delete button are clicked.
   */
  onDeleteClick: (criteriaType: AccountFilterCriterias) => void;
  /**
   * Callback to set the value for Criteria.
   */
  setCriteriaValue: SetCriteriaValue;
  label: string;
  name: AccountFilterCriterias;
}

export const AccountManagerCriteria = (props: IProps) => {
  const {onDeleteClick, setCriteriaValue, value, label, name} = props;
  const handleDeleteClick = () => {
    onDeleteClick(name);
  };
  const handleChange = (e: Select.Types.SelectEventTarget<string>) => {
    setCriteriaValue(name, e.target.value as string);
  };
  const css = Styles.Hooks.useClassName(criteriasListItemStyle);
  const deleteIconCss = Styles.Hooks.useClassName(criteriasListItemDeleteIconStyle);

  return (
    <div className={css}>
      <span>{formatMessage("By {label}", {label})}</span>
      <div>
        <AccountManagerSelect placeholder={formatMessage("Select {label}", {label})} name={name} onChange={handleChange} value={value}/>
      </div>
      <Icon.Icon onClick={handleDeleteClick} className={deleteIconCss} icon={Icon.Enums.Icons.Clear}/>
    </div>
  );
};


export default AccountManagerCriteria;