import {useAccountManagerStateActions, useAccountManagerStateSelector} from "../../../../../../../states/hooks";
import {useEffect, useState} from "react";
import {DashboardModel} from "../../../../../../../models/Dashboard";

export const useSelectOpenedDashboard = (dashboards: DashboardModel[], dashboardSelected: DashboardModel | null, setDashboardSelected: (dashboard: DashboardModel | null) => void): number => {
  const openedDashboard = useAccountManagerStateSelector("openedDashboard");
  const {clearOpenDashboard} = useAccountManagerStateActions();
  const [position, setPosition] = useState<number>(0);

  useEffect(() => {
    if (openedDashboard != null && (dashboardSelected == null || dashboardSelected.id !== openedDashboard.dashboard)) {
      setDashboardSelected(dashboards.find((d) => d.id === openedDashboard.dashboard)!);
      const index = dashboards.findIndex((d) => d.id === openedDashboard.dashboard);

      if (index !== -1) {
        setPosition(index);
      }
      clearOpenDashboard();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openedDashboard, dashboardSelected, setDashboardSelected, dashboards]);

  return position;
};