import {StudioCSS} from "../../../../../../../../styles/types";

export const healthGraphStyle: StudioCSS = (theme, utilities) => ({
  label: "health-graph",
  display: "grid",
  gridTemplateRows: "auto auto",
  gridTemplateColumns: "auto",
  gap: utilities.space("t"),
  padding: utilities.space("n")
});

export const healthGraphTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "health-graph-title",
  ...utilities.fontStyle({
    size: "regular",
    weight: "b"
  })
});
