import React from "react";
import {Geography, Styles} from "@dashthis/ui";
import {statePickerStyle} from "./styles/statePicker.style";

interface IProps extends Geography.Types.IStatePickerProps {
}

export const StatePicker = (props: IProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, statePickerStyle);

  return (
    <Geography.StatePicker {...props} className={css}/>
  );
};


export default StatePicker;
