import React, {ReactNode} from "react";
import {RadialProgress, Styles} from "@dashthis/ui";
import AccountPlanItem from "./AccountPlanItem";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../../models/Account";
import {accountPlanCurrentNextPlanCurrentStyle, accountPlanCurrentNextPlanNextContent, accountPlanCurrentNextPlanNextStyle, accountPlanCurrentNextPlanProgressDayLeftStyle, accountPlanCurrentNextPlanProgressNextDateStyle, accountPlanCurrentNextPlanProgressStyle, accountPlanCurrentNextPlanStyle} from "./styles/accountPlanCurrentNextPlan.style";
import {IStudioTheme} from "../../../../../../styles/studioTheme";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import calendar from "dayjs/plugin/calendar";
import PlanLine from "../../../../../../medias/svg/planLine.inline.svg";
import PlanLineEnd from "../../../../../../medias/svg/planLineEnd.inline.svg";

dayjs.extend(relativeTime);
dayjs.extend(calendar);

interface IProps {
  /**
   * The account mode.
   */
  account: AccountModel;
}

const getProgress = (account: AccountModel): number => {
  if (account.Status.isActive || account.Status.isCanceled) {
    const billingInfo = account.billingInfo;

    if (!billingInfo?.nextPaymentDate || !billingInfo?.lastPaymentDate) return 0;
    const nextPaymentDate = dayjs(billingInfo.nextPaymentDate);
    const lastPaymentDate = dayjs(billingInfo.lastPaymentDate);
    const numberOfDays = nextPaymentDate.diff(lastPaymentDate, "d");
    const numberOfDaysFromNow = nextPaymentDate.diff(dayjs(), "d");

    return 100 - Math.floor(((numberOfDays - numberOfDaysFromNow) / numberOfDays) * 100);
  } else if (account.Status.isTrial) {
    const expireDate = dayjs(account.Status.expireDate);
    const appliedDateTime = dayjs(account.StatusHistory[0].appliedDateTime);
    const numberOfDays = expireDate.diff(appliedDateTime, "d");
    const numberOfDaysFromNow = expireDate.diff(dayjs(), "d");

    return 100 - Math.floor(((numberOfDays - numberOfDaysFromNow) / numberOfDays) * 100);
  } else {
    return 100;
  }
};
const getDaysLeft = (account: AccountModel): string => {
  if (account.Status.isActive || account.Status.isCanceled) {
    const nextPaymentDate = dayjs(account.billingInfo?.nextPaymentDate);

    return `${nextPaymentDate.fromNow(true)} left`;
  } else if (account.Status.isTrial) {
    return `${account.Status.dayLeftInTrial} left`;
  } else {
    return formatMessage("∞ days left");
  }
};
const formatPaymentDate = (dateStr: string | null | undefined): string => {
  if (!dateStr) return formatMessage("N/A");

  return dayjs(dateStr).calendar(undefined, {
    sameDay: "[Today]",
    nextDay: "[Tomorrow]",
    nextWeek: "dddd",
    lastDay: "[Yesterday]",
    lastWeek: "[Last] dddd",
    sameElse: "MMMM D, YYYY"
  });
};

const getNextPlanDate = (account: AccountModel): string => {
  if (account.Status.isActive || account.Status.isCanceled) {
    return formatPaymentDate(account.billingInfo?.nextPaymentDate);
  } else if (account.Status.isTrial) {
    return account.Status.dateFormatted("expireDate");
  } else {
    return "";
  }
};
const getNextPlan = (account: AccountModel): ReactNode => {
  const textCss = Styles.Hooks.useClassName(accountPlanCurrentNextPlanNextContent);

  if (account.Status.isActive) {
    return (<AccountPlanItem showFrequency={!account.Status.hasBeenTrial} paymentFrequency={account.nextBillingFrequency()} title={formatMessage("Next Plan")} plan={account.NextPlan!}/>);
  } else if (account.Status.isTrial) {
    return (<p className={textCss}>{formatMessage("End trial period")}</p>);
  } else if (account.Status.isCanceled) {
    return (<p className={textCss}>{formatMessage("End active period")}</p>);
  } else {
    return (<p className={textCss}>{formatMessage("Will never expire")}</p>);
  }
};

export const AccountPlanCurrentNextPlan = (props: IProps) => {
  const {account} = props;
  const theme = Styles.Hooks.useTheme<IStudioTheme>();
  const css = Styles.Hooks.useClassName(accountPlanCurrentNextPlanStyle);
  const currentPlanCss = Styles.Hooks.useClassName(accountPlanCurrentNextPlanCurrentStyle);
  const nextPlanCss = Styles.Hooks.useClassName(accountPlanCurrentNextPlanNextStyle);
  const progressCss = Styles.Hooks.useClassName(accountPlanCurrentNextPlanProgressStyle);
  const progressDayLeftCss = Styles.Hooks.useClassName(accountPlanCurrentNextPlanProgressDayLeftStyle);
  const progressNextDateCss = Styles.Hooks.useClassName(accountPlanCurrentNextPlanProgressNextDateStyle);

  return (
    <div className={css}>
      <AccountPlanItem showFrequency={!account.Status.hasBeenTrial} paymentFrequency={account.currentBillingFrequency()} className={currentPlanCss} title={formatMessage("Current Plan")} plan={account.Plan!}/>
      <PlanLine/>
      <div className={progressCss}>
        <RadialProgress.RadialProgress colors={{
          progress: theme.colors.chambray.string()
        }} radius={40} stroke={9} progress={getProgress(account)}/>
        <p className={progressDayLeftCss}>{getDaysLeft(account)}</p>
        <p className={progressNextDateCss}>{getNextPlanDate(account)}</p>
      </div>
      <PlanLineEnd/>
      <div className={nextPlanCss}>
        {getNextPlan(account)}
      </div>
    </div>
  );
};


export default AccountPlanCurrentNextPlan;
