import React, {useEffect} from "react";
import {FileTemplatesTreeItem, useAccountFileTemplatesTree} from "../hooks/useAccountFileTemplatesTree";
import {Styles, VirtualizedList} from "@dashthis/ui";
import FileTemplatesTemplateItem from "./FileTemplatesTemplateItem";
import {CsvTemplateModel} from "../../../../../../../models/CsvTemplate";
import {Icon} from "../../../../../../../components";
import FileTemplatesGroupItem from "./FileTemplatesGroupItem";
import formatMessage from "format-message";
import {FileTemplatesFileItem} from "./FileTemplatesFileItem";
import {FileTemplatesSourceItem} from "./FileTemplatesSourceItem";
import {useAccountPersistedState} from "../../../hooks/useAccountPersistedState";
import {AccountModel} from "../../../../../../../models/Account";
import {fileTemplatesListContainerStyle, fileTemplatesListStyle} from "../styles/fileTemplates.style";
import FileTemplatesSelectItem from "../detail/FileTemplatesSelectItem";
import {CsvSourceModel} from "../../../../../../../models/CsvSource";
import {CsvFileModel} from "../../../../../../../models/CsvFile";
import FileTemplatesFileDetail from "../detail/FileTemplatesFileDetail";
import FileTemplatesSourceDetail from "../detail/FileTemplatesSourceDetail";
import NoResultMessage from "../../../../SearchBar/components/NoResultMessage";
import {useOpenFileTemplate} from "../hooks/useOpenFileTemplate";
import FileTemplatesDetail from "../detail/FileTemplatesDetail";

interface IProps {
  /**
   * The of file template.
   */
  fileTemplates: CsvTemplateModel[];
  /**
   * The account model.
   */
  account: AccountModel;
  /**
   * The current search query
   */
  query: string;
}

export type SelectedItem = CsvSourceModel | CsvFileModel | CsvTemplateModel | null

const getViewItemDetail = (item: SelectedItem): React.ReactNode => {
  if (item == null) {
    return (<FileTemplatesSelectItem/>);
  } else if (item.__typename === "CsvFile") {
    return (<FileTemplatesFileDetail file={item}/>);
  } else if (item.__typename === "CsvTemplate") {
    return (<FileTemplatesDetail template={item}/>);
  } else if (item.__typename === "CsvSource") {
    return (<FileTemplatesSourceDetail source={item}/>);
  }
};

export const FileTemplatesList = (props: IProps) => {
  const {fileTemplates, account, query} = props;
  const {fileTemplatesTree, isFileTemplatesAreOpen, toggleFileTemplatesOpen} = useAccountFileTemplatesTree(account, fileTemplates, query);
  const listContainerCss = Styles.Hooks.useClassName(fileTemplatesListContainerStyle);
  const listCss = Styles.Hooks.useClassName(fileTemplatesListStyle);
  const renderItem = (item: FileTemplatesTreeItem) => {
    const handlerArrowClick = (t: CsvTemplateModel) => {
      toggleFileTemplatesOpen(t.id!);
    };

    switch (item.type) {
      case "template":
        return (
          <FileTemplatesTemplateItem
            account={account}
            onClick={() => setSelectedItem(item.template)}
            selected={selectedItem != null && selectedItem.__typename === "CsvTemplate" && selectedItem.id === item.template.id}
            fileTemplate={item.template}
            expended={isFileTemplatesAreOpen(item.template.id!)}
            key={item.template.id!}
            onArrowClick={handlerArrowClick}
          />
        );
      case "files":
        return (
          <FileTemplatesGroupItem
            expended={isFileTemplatesAreOpen(item.id)}
            onArrowClick={() => toggleFileTemplatesOpen(item.id)}
            Icon={Icon.Icons.CsvFileIcon}
            name={formatMessage("CSV Files")}
          />
        );
      case "file":
        return (
          <FileTemplatesFileItem
            account={account}
            selected={selectedItem != null && selectedItem.__typename === "CsvFile" && selectedItem.uiId === item.file.uiId}
            onClick={() => setSelectedItem(item.file)}
            file={item.file}
          />
        );
      case "sources":
        return (
          <FileTemplatesGroupItem
            expended={isFileTemplatesAreOpen(item.id)}
            onArrowClick={() => toggleFileTemplatesOpen(item.id)}
            Icon={Icon.Icons.CsvSourceIcon}
            name={formatMessage("CSV Sources")}
          />
        );
      case "source":
        return (
          <FileTemplatesSourceItem
            selected={selectedItem != null && selectedItem.__typename === "CsvSource" && selectedItem.uiId === item.source.uiId}
            onClick={() => setSelectedItem(item.source)}
            source={item.source}
          />
        );
    }
  };
  const handleNoRowsRenderer = () => {
    return (<NoResultMessage message={
      query !== ""
        ? formatMessage("Your search returned no results")
        : formatMessage("This account has no file templates")
    }/>);
  };
  const [selectedItem, setSelectedItem] = useAccountPersistedState<SelectedItem>(`fileTemplateSelectedItem`, null);
  const scrollToIndex = useOpenFileTemplate(fileTemplates, selectedItem, setSelectedItem);
  const {listRef} = VirtualizedList.Hooks.useVirtualizedListScroll(`FileTemplatesList-${account.id}`);

  useEffect(() => {
    listRef.current.scrollToIndex(scrollToIndex);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scrollToIndex]);

  return (
    <div className={listContainerCss}>
      <VirtualizedList.VirtualizedList className={listCss} listRef={listRef} noRowsRenderer={handleNoRowsRenderer} items={fileTemplatesTree} estimateSize={52} keyExtractor={(i) => i.id} renderItem={renderItem}/>
      {getViewItemDetail(selectedItem)}
    </div>
  );
};


export default FileTemplatesList;
