import {StudioCSS} from "../../../../../../../styles/types";

export const usersStyle: StudioCSS = (theme, utilities) => ({
  label: "users",
  borderTop: `1px solid ${utilities.colors("athensGray").string()}`,
  "[class*=user-item]:last-child": {
    ":after": {
      height: 0
    }
  }
});

export const userItemStyle: StudioCSS = (theme, utilities) => ({
  label: "user-item",
  display: "grid",
  gap: utilities.space("s"),
  gridTemplateColumns: "24px 1fr 1fr 215px",
  padding: `${utilities.space("s")} ${utilities.space("n")}`,
  ":after": {
    content: `""`,
    backgroundColor: utilities.colors("athensGray").string(),
    position: "absolute",
    height: 1,
    left: 45,
    bottom: 0,
    right: 45
  },
  ":hover": {
    backgroundColor: utilities.colors("aquaHazeLight").string(),
    cursor: "pointer"
  }
});

export const userItemGravatarContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "user-item-gravatar-container",
  gridColumn: 2,
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  gap: utilities.space("s")
});

export const userItemGravatarStyle: StudioCSS = (theme, utilities) => ({
  label: "user-item-gravatar",
  width: 18,
  height: 18
});

export const userItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "user-item-title",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "regular"
  })
});

export const userItemLastSeenStyle: StudioCSS = (theme, utilities) => ({
  label: "user-item-title",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "small",
    color: "scorpion",
    weight: "l"
  })
});
