import {Client, DTGraphTypes} from "@dashthis/common";
import {Services} from "@dashthis/ui";
import {useCallback, useState} from "react";
import {updateDashboardMutation} from "../queries/mutation/dashboard/updateDashboard.mutation";
import formatMessage from "format-message";

export const useUpdateDashboard = (id: string): [(input: DTGraphTypes.DashboardInput) => Promise<DTGraphTypes.Dashboard>, boolean] => {
  const [mutation] = Client.Hooks.useMutation<DTGraphTypes.Dashboard, DTGraphTypes.MutationDashboardUpdateArgs>(updateDashboardMutation);
  const [processing, setProcessing] = useState<boolean>(false);
  const updateDashboard = useCallback(async (input: DTGraphTypes.DashboardInput): Promise<DTGraphTypes.Dashboard> => {
    setProcessing(true);

    try {
      const response = await mutation({
        variables: {
          dashboard: input,
          id
        }
      });

      setProcessing(false);

      return response.data!;
    } catch (e) {
      Services.clientService.Error.displayError(e, formatMessage("Update dashboard error!"));
      setProcessing(false);

      return e as Client.Errors.ApplicationServerError;
    }

  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mutation, setProcessing]);

  return [updateDashboard, processing];
};