import gql from "graphql-tag";
import {AccountSearchParts} from "../fragments/account/accountSearchParts";
import {DocumentNode} from "graphql";

export const filterAccountQuery: DocumentNode = gql`
    query($filter:FilterInput!,$limit:Int,$page:Int){
        accounts: accountsFilter(page:$page,limit:$limit,filter:$filter){
            count
            pages
            page
            accounts{
                ...AccountSearchParts
            }
        }
    }
    ${AccountSearchParts}
`;