import {createContext} from "react";
import {IAppSettingService} from "../appSettings/appSettingService";
import {EmulateSettings} from "../appSettings/types";


export const AppSettingsServiceContext = createContext<IAppSettingService>({
  getEmulateSettings(): EmulateSettings {
    return {
      password: "",
      email: ""
    };
  },
  setEmulateSettings(setting: EmulateSettings): EmulateSettings {
    return {
      password: "",
      email: ""
    };
  }

});
