import React, {HTMLAttributes} from "react";
import {Icon} from "../../../../../../components";
import {Styles} from "@dashthis/ui";
import {CsvTemplateModel} from "../../../../../../models/CsvTemplate";
import {fileTemplateItemIconStyle, fileTemplateItemStyle, fileTemplateItemTitleStyle} from "./styles/fileTemplateItem.style";

interface Props extends HTMLAttributes<HTMLDivElement> {
  /**
   * The file template model.
   */
  fileTemplate: CsvTemplateModel;
}

export const FileTemplateItem = (props: Props) => {
  const {fileTemplate, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, fileTemplateItemStyle);
  const iconCss = Styles.Hooks.useClassName(fileTemplateItemIconStyle);
  const titleCss = Styles.Hooks.useClassName(fileTemplateItemTitleStyle);

  return (
    <div {...rest} className={css}>
      <Icon.Icon icon={Icon.Enums.Icons.CsvFile} className={iconCss}/>
      <span className={titleCss}>{fileTemplate.name}</span>
    </div>
  );
};


export default FileTemplateItem;
