import React, {useMemo} from "react";
import {QueryProcessor, Select as DefaultSelect} from "@dashthis/ui";
import {Models} from "@dashthis/common";
import {Select} from "../../components";
import {sort} from "fast-sort";
import {useGetPlans} from "../../hooks/useGetPlans";

interface IAccountManagerSelectProps {
  /**
   * Callback call when item are selected
   */
  onChange?: (e: DefaultSelect.Types.SelectEventTarget<string>) => void;
  /**
   * The id of plan.
   */
  value?: string;
  /**
   * The name for input.
   */
  name?: string;
  placeholder?: string;
}

export const PlansSelect = (props: IAccountManagerSelectProps) => {
  const {onChange, value, name, placeholder} = props;
  const [plans, loading, error] = useGetPlans();
  const handleChange = (e: DefaultSelect.Types.SelectEventTarget<string>) => {
    const plan = plans.find((a) => a.id === e.target.value);

    if (onChange !== undefined && plan !== undefined) {
      const event: DefaultSelect.Types.SelectEventTarget<string> = {
        ...e,
        target: {
          ...e.target,
          value: plan.id!
        }
      };

      onChange(event);
    }
  };
  const getPlanNameFormId = (id: string | undefined): string | undefined => {
    if (id === undefined || loading || error !== undefined) {
      return undefined;
    }
    const plan = plans.find((a) => a.id === id);

    return plan !== undefined ? plan.name : undefined;
  };
  const filterPlans = (query: string, item: Models.Plan.PlanModel): boolean => item.matchQuery(query);
  const plansSort = useMemo(() => sort(plans).asc((p) => p.name.toLowerCase()), [plans]);

  return (
    <QueryProcessor.QueryProcessor loading={loading ? <Select.InputLoading/> : false} error={error}>
      <Select.Select<string> placeholder={placeholder} value={value !== undefined ? value : undefined} label={getPlanNameFormId(value)} name={name} onChange={handleChange}>
        <DefaultSelect.BodyVirtualizedSearch
          keyExtractor={(p) => p.id!}
          estimateSize={30}
          renderItem={(p) => <DefaultSelect.Item key={p.id} value={p.id!} label={p.name}/>}
          items={plansSort}
          filter={filterPlans}/>
      </Select.Select>
    </QueryProcessor.QueryProcessor>
  );
};


export default PlansSelect;
