import {DatePicker as DefaultDatePicker, Icon, Styles} from "@dashthis/ui";
import {DatePicker} from "../../../../../../../components";
import formatMessage from "format-message";
import React from "react";
import {AccountFilterCriterias, SetCriteriaValue} from "../../hooks/useAccountFilter";
import {criteriasListItemDeleteIconStyle, criteriasListItemStyle} from "../../styles/criteriasList.style";

interface IProps {
  /**
   * The default date selected.
   */
  value?: Date;
  /**
   * Callback when delete button is clicked.
   */
  onDeleteClick: (criteriaType: AccountFilterCriterias) => void;
  /**
   * Callback to set the value for Criteria.
   */
  setCriteriaValue: SetCriteriaValue;
}

export const CreationDateCriteria = (props: IProps) => {
  const {value, setCriteriaValue, onDeleteClick} = props;
  const handleDeleteClick = () => {
    onDeleteClick("creationDate");
  };
  const handleChange = (e: DefaultDatePicker.Types.DatePickerEventTarget) => {
    const date = e.target.value;

    setCriteriaValue("creationDate", date);
  };
  const css = Styles.Hooks.useClassName(criteriasListItemStyle);
  const deleteIconCss = Styles.Hooks.useClassName(criteriasListItemDeleteIconStyle);

  return (
    <div className={css}>
      <span>{formatMessage("Creation date is after")}</span>
      <div>
        <DatePicker.InputDate maxDate={new Date()} onChange={handleChange} value={value}/>
      </div>
      <Icon.Icon onClick={handleDeleteClick} className={deleteIconCss} icon={Icon.Enums.Icons.Clear}/>
    </div>
  );
};


export default CreationDateCriteria;