import React, {HTMLAttributes} from "react";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {WebView} from "../../../../../../../components";
import {Styles} from "@dashthis/ui";
import {accountDashboardViewStyle} from "./styles/accountDashboardView.style";
import {Types} from "@dashthis/studio-common";
import {useDashboardActions} from "../hooks/useDashboardActions";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The dashboard model.
   */
  dashboard: DashboardModel;
}


export const AccountDashboardView = (props: IProps) => {
  const {dashboard, ...rest} = props;
  const {viewDashboard, viewPath, exportToPdf} = useDashboardActions();
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, accountDashboardViewStyle);
  const openInWindow = () => viewDashboard(dashboard);
  const onDomReady = async (view: Types.ElectronTypes.WebviewTag) => {
    if (dashboard.isProtected) {
      await view.executeJavaScript(`
        const input = document.getElementsByName("pin")[0];
        if(input != null){
            input.value="${dashboard.pin}";
            document.getElementsByTagName("form")[0].submit();
        }
    `);
    }
  };
  const generatePdf = () => exportToPdf(dashboard);

  return (
    <div {...rest} className={css}>
      <WebView.WebView
        onDomReady={onDomReady}
        canDownloadPDF
        generatePdf={generatePdf}
        onOpenInWindow={openInWindow}
        url={viewPath(dashboard)}
        partition={"view-dashboard"}
      />
    </div>
  );
};

export default AccountDashboardView;
