import React from "react";
import {HeaderItem} from "../HeaderItem";
import formatMessage from "format-message";
import AccountItem from "./AccountItem";
import {AccountModel} from "../../../../../../models/Account";
import {OpenAccounts} from "../../../../../../states";
import {Styles} from "@dashthis/ui";
import {accountsStyle} from "./styles/accountItem.style";

interface IProps {
  /**
   * The list of account to display.
   */
  accounts: AccountModel[];
  /**
   * Callback to call to open an account.
   */
  openAccounts: OpenAccounts;
  /**
   * number of total account found
   */
  count: number;
  /**
   * Number of account found
   */
  total: number;
}

export const Accounts = (props: IProps) => {
  const {accounts, openAccounts, count, total} = props;
  const handleDoubleClick = (account: AccountModel, e: React.MouseEvent) => {
    openAccounts(new Set([account.id!]));
  };
  const css = Styles.Hooks.useClassName(accountsStyle);

  return (
    <div className={css}>
      <HeaderItem total={total} count={count} title={formatMessage("Accounts")}/>
      {accounts.map((account) => <AccountItem onDoubleClick={handleDoubleClick} account={account} key={account.id!}/>)}
    </div>
  );
};


export default Accounts;
