import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const accountDashboardQuery: DocumentNode = gql`
    query($id:ID!, $dashboardId:ID!){
        account(id:$id){
            id
            dashboard(id: $dashboardId) {
                id
                title
                shortId
                creationDate
                dateLastAccessed
                dateDeleted
                isDeleted
                cultureCode
                customCSS,
                pin
                healths {
                    viewed {
                        date
                        view
                    }
                }
                userWhoCreated {
                    id
                    email
                }
                userWhoCreated {
                    id
                    email
                }
                type {
                    id
                    name
                }
                widgets {
                    id
                    title
                    positionX
                    positionY
                    sizeX
                    sizeY
                    isStatic
                    dateAdded
                    isBrokerFull
                    isMerged
                    isRefreshable
                    formatter {
                        id
                        name
                    }
                    sources {
                        id
                        name
                        providerKey
                        status
                        error {
                            humanReadableMessage
                            internalMessage
                        }
                        authorization {
                            id
                            name
                            providerKey
                            token1
                            token2
                            creationDate
                            error {
                                humanReadableMessage
                                internalMessage
                            }
                            integration {
                                id
                                typeId
                                name
                            }
                        }
                    }
                }
            }
        }
    }
`;