import React from "react";
import {Icon} from "../../../../../../components";
import {AccountStatusHistoryModel} from "../../../../../../models/AccountStatusHistory";
import {Styles} from "@dashthis/ui";
import {accountStatusHistoryItemContentInvertStyle, accountStatusHistoryItemContentStyle, accountStatusHistoryItemDayStyle, accountStatusHistoryItemStatusInvertStyle, accountStatusHistoryItemStatusStyle, accountStatusHistoryItemStyle, accountStatusHistoryItemTimeStyle, accountStatusHistoryItemPathStyle} from "./styles/AccountStatusHistoryItemStyle";
import {Conditional} from "@dashthis/common";

interface IProps {
  /**
   * The account status history model.
   */
  statusHistory: AccountStatusHistoryModel;
  /**
   * Indicate if need to invert content.
   * If true, Status go to Left and date go to right.
   */
  invert: boolean;
  /**
   * Indicate if item are last.
   * If true, change path to gray dot path.
   */
  last: boolean;
}


export const AccountStatusHistoryItem = (props: IProps) => {
  const {statusHistory, invert, last} = props;
  const css = Styles.Hooks.useClassName(accountStatusHistoryItemStyle);
  const pathCss = Styles.Hooks.useClassName(accountStatusHistoryItemPathStyle);
  const contentCss = Styles.Hooks.useClassName(
    accountStatusHistoryItemContentStyle,
    Conditional.is(invert, accountStatusHistoryItemContentInvertStyle)
  );
  const dayCss = Styles.Hooks.useClassName(accountStatusHistoryItemDayStyle);
  const timeCss = Styles.Hooks.useClassName(accountStatusHistoryItemTimeStyle);
  const statusCss = Styles.Hooks.useClassName(
    accountStatusHistoryItemStatusStyle,
    Conditional.is(invert, accountStatusHistoryItemStatusInvertStyle)
  );
  const getContent = () => (
    <div className={contentCss}>
      <p className={dayCss}>{statusHistory.dayActivity}</p>
      <p className={timeCss}>{statusHistory.timeActivity}</p>
    </div>
  );
  const getStatus = () => (
    <div className={statusCss}>
      {statusHistory.toString()}
    </div>
  );

  return (
    <div className={css}>
      {invert ? getStatus() : getContent()}
      <Icon.Icon className={pathCss} icon={last ? Icon.Enums.Icons.TimeLineEndPath : Icon.Enums.Icons.TimeLinePath}/>
      {invert ? getContent() : getStatus()}
    </div>
  );
};


export default AccountStatusHistoryItem;
