import {StudioCSS} from "../../../styles/types";

export const navigationBarItemStyle: StudioCSS = (theme, utilities) => ({
  label: "navigation-bar-item",
  width: 50,
  height: 50,
  display: "flex",
  justifyContent: "center",
  position: "relative",
  alignItems: "center",
  background: utilities.colors("aquaHazeLight").string(),
  "&:hover": {
    cursor: "pointer"
  }
});

export const navigationBarItemIconStyle: StudioCSS = (theme, utilities) => ({
  label: "navigation-bar-item-icon",
  width: 22,
  height: 22
});

export const navigationBarItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "navigation-bar-item-selected",
  background: utilities.colors("white").string(),
  pointerEvents: "none"
});
