import {IFileSystemService} from "./types";
import {readAsync, writeAsync} from "fs-jetpack";
import {dialog} from "@electron/remote";

export const electronFileSystemService: IFileSystemService = {
  async showSaveDialog(options): Promise<string | undefined> {
    const result = await dialog.showSaveDialog({
      ...options
    });

    if (!result.canceled) {
      return Promise.resolve(result.filePath);
    }

    return Promise.resolve(undefined);
  },
  read<T>(path: string, returnAs: "utf8" | "buffer" | "json" | "jsonWithDates"): Promise<T> {
    return readAsync(path, returnAs as any) as any;
  },
  write(path: string, data: string | Buffer | object | any[]): Promise<void> {
    return writeAsync(path, data);
  }

};