import {StudioCSS} from "../../../../../../../../styles/types";

export const accountDashboardWidgetsAuthorizationItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-authorization-item",
  display: "grid",
  gridTemplateColumns: "auto 1fr auto auto",
  padding: `${utilities.space.small} 0`,
  paddingLeft: 40,
  alignItems: "center",
  gap: utilities.space("s"),
  borderBottom: `1px solid ${utilities.colors("aquaHaze").string()}`,
  userSelect: "none",
  "&:hover": {
    cursor: "pointer"
  }
});

export const accountDashboardWidgetsAuthorizationItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-authorization-item-selected",
  background: utilities.colors("chambray").alpha(.4).string()
});

export const accountDashboardWidgetsAuthorizationItemTitleContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-authorization-item-container-title",
  ...utilities.ellipsis()
});

export const accountDashboardWidgetsAuthorizationItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-authorization-item-title",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "regular"
  })
});

export const accountDashboardWidgetsAuthorizationItemIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-authorization-item-icon",
  width: 20,
  height: 20
});

export const accountDashboardWidgetsAuthorizationItemArrowIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-authorization-item-arrow-icon",
  transition: "transform .3s",
  fill: utilities.colors("scorpion").string(),
  width: 15,
  height: 15
});

export const accountDashboardWidgetsAuthorizationItemArrowDownIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-authorization-item-arrow-down-icon",
  transform: "rotate(90deg)"
});
