import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import {useCallback, useEffect} from "react";
import {Enums} from "@dashthis/studio-common";
import {Client, Hooks} from "@dashthis/common";

export const useOnRefreshCaches = () => {
  const eventService = useEventServiceContext();
  const client = Client.Hooks.useClient();
  const forceUpdate = Hooks.useForceUpdate();
  const refreshCachesHandler = useCallback(async () => {
    await client.resetStore();
    forceUpdate();
  }, [client, forceUpdate]);

  useEffect(() => {
    eventService.on(Enums.IPCChannelEnum.RefreshCaches, refreshCachesHandler);

    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.RefreshCaches, refreshCachesHandler);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService]);
};