import {StudioCSS} from "../../../styles/types";

export const accountManagerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager",
  height: "100vh",
  width: "100vw",
  overflow: "hidden",
  display: "grid",
  gridTemplateColumns: "80px 250px 1fr",
  gridTemplateRows: "43px minmax(0, 1fr)",
  borderTop: `1px solid ${utilities.colors("athensGray")}`
});

export const accountManagerMainBarStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-main-bar",
  position:"relative",
  gridColumn: "1",
  gridRow: "1/3",
  zIndex: 5,
  background: utilities.colors("primary").string(),
  borderRight: `1px solid ${utilities.colors("athensGray").string()}`
});

export const accountManagerTaskBarStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-task-bar",
  position:"relative",
  gridColumn: "2",
  gridRow: "2",
  zIndex: 4
});

export const accountManagerSwitchStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-switch",
  position:"relative",
  gridColumn: "3",
  gridRow: "2",
  display: "contents"
});

export const accountManagerSearchBarStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-search-bar",
  position:"relative",
  gridColumn: "2 / 4",
  gridRow: "1"
});
