import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const dashboardsReportQuery: DocumentNode = gql`
    query($id:ID!){
        account(id:$id){
            id
            dashboardsErrorReport {
                dashboard {
                    id
                    title
                    shortId
                    dateLastAccessed
                    type {
                        id
                        name
                    }
                }
                source {
                    id
                    name
                    status
                    providerKey
                    authorization {
                        id
                        name
                        status
                        integration {
                            id
                            name
                            typeId
                        }
                    }
                    error {
                        internalMessage
                        humanReadableMessage
                    }
                }
                authorization {
                    id
                    name
                    tokenExpiration
                    status
                    providerKey
                    integration {
                        id
                        name
                    }
                    error {
                        internalMessage
                        humanReadableMessage
                    }
                }
            }
        }
    }
`;