import React, {Fragment} from "react";
import ViewEditFileTemplateWindowSubHeader from "./ViewEditFileTemplateWindowSubHeader";
import formatMessage from "format-message";
import ViewEditFileTemplateWindowText from "./ViewEditFileTemplateWindowText";
import {Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowDimensionSectionStyle} from "./styles/fileTemplatesViewEditWindow.style";
import ViewEditFileTemplateWindowHeader from "./ViewEditFileTemplateWindowHeader";
import {CsvTemplateModel} from "../../../../../../../../models/CsvTemplate";

interface IProps {
  /**
   * The csv template model.
   */
  csvTemplate: CsvTemplateModel;

}

export const ViewEditFileTemplateWindowDimensionSection = (props: IProps) => {
  const {csvTemplate} = props;
  const dimensionSectionCss = Styles.Hooks.useClassName(fileTemplatesViewEditWindowDimensionSectionStyle);
  const dimensionFields = csvTemplate.getDimensionFields();

  return (
    <Fragment>
      <ViewEditFileTemplateWindowHeader>{formatMessage("Dimensions")}</ViewEditFileTemplateWindowHeader>
      <div className={dimensionSectionCss}>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("Name")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("No Column")}</ViewEditFileTemplateWindowSubHeader>
        {dimensionFields.map((d, k) => (
          <Fragment key={k}>
            <ViewEditFileTemplateWindowText>{d.name}</ViewEditFileTemplateWindowText>
            <ViewEditFileTemplateWindowText>{d.columnIndex}</ViewEditFileTemplateWindowText>
          </Fragment>
        ))}
      </div>
    </Fragment>
  );
};


export default ViewEditFileTemplateWindowDimensionSection;
