import React, {Fragment, HTMLAttributes, useMemo} from "react";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {Field, Formik} from "formik";
import {DashboardSchema} from "../../../../../shemas/dashboard";
import {Dialog, Form, Notification, Services, Styles, Window} from "@dashthis/ui";
import formatMessage from "format-message";
import {Button, Input, Label} from "../../../../../../../components";
import cleanDeep from "clean-deep";
import {accountDashboardPropertiesFooterStyle, accountDashboardPropertiesFormContainerStyle, accountDashboardPropertiesStyle} from "../styles/accountDashboardProperties.style";
import {diff} from "deep-diff";
import {DTGraphTypes} from "@dashthis/common";
import {useUpdateDashboard} from "../../../../../../../hooks/useUpdateDashboard";


interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  dashboard: DashboardModel;
}

const cleanOption = {
  emptyStrings: false
};

export interface IDashboardInput extends DTGraphTypes.DashboardInput {
}

const canSubmit = (initialValues: IDashboardInput, changeValues: IDashboardInput, isValid: boolean): boolean => {
  const changes = diff(initialValues, cleanDeep(changeValues, cleanOption));

  return !!changes && isValid;
};

export const AccountDashboardProperties = (props: IProps) => {
  const {dashboard, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, accountDashboardPropertiesStyle);
  const [updateDashboard, processing] = useUpdateDashboard(dashboard.id!);
  const formContainerCss = Styles.Hooks.useClassName(accountDashboardPropertiesFormContainerStyle);
  const footerCss = Styles.Hooks.useClassName(accountDashboardPropertiesFooterStyle);
  const initialValues = useMemo<IDashboardInput>(() => cleanDeep({
    pin: dashboard.pin ?? "",
    customCSS: dashboard.customCSS ?? undefined,
    title: dashboard.title ?? ""
  }, cleanOption), [dashboard]);
  const handleRestoreClick = async () => {
    try {
      await updateDashboard({
        restore: true
      });
      Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("Dashboard restored")}</Notification.SuccessNotification>);
    } catch (e) {
      Dialog.ApplicationDialogs.message({
        title: formatMessage("Error"),
        message: formatMessage("Error when trying to restore dashboard."),
        ui: Window.Enums.WindowStyleEnum.Error
      });
    }
  };

  const convertFormToDashboardInput = (values: any) => (
    {
      pin: values.pin,
      customization: values.customCSS !== null && values.customCSS !== "" ? {whiteLabel: {whiteLabelName: values.customCSS}} : null,
      title: values.title
    }
  );

  return (
    <div {...rest} className={css}>
      <Formik validateOnMount={true} validationSchema={DashboardSchema} initialValues={initialValues} onSubmit={async (values) => {
        try {
          await updateDashboard(convertFormToDashboardInput(values));
        } catch (e) {
          Dialog.ApplicationDialogs.message({
            title: formatMessage("Error"),
            message: formatMessage("Error when trying to save dashboard information."),
            ui: Window.Enums.WindowStyleEnum.Error
          });
        }
      }}>
        {({isValid, submitForm, values}) => {
          return (
            <Fragment>
              <div className={formContainerCss}>
                <Form.Item>
                  <Label.Label>{formatMessage("Title")}</Label.Label>
                  <Field name="title" as={Input.Input}/>
                </Form.Item>
                <Form.Item>
                  <Label.Label>{formatMessage("Pin")}</Label.Label>
                  <Field name="pin" as={Input.Input}/>
                </Form.Item>
                <Form.Item>
                  <Label.Label>{formatMessage("White Label")}</Label.Label>
                  <Field name="customCSS" as={Input.Input}/>
                </Form.Item>
              </div>
              <div className={footerCss}>
                {dashboard.isDeleted
                  ? <Button.Button loading={processing} onClick={handleRestoreClick}>{formatMessage("Restore")}</Button.Button>
                  : null
                }
                <Button.Button loading={processing} onClick={submitForm} disabled={!canSubmit(initialValues, values, isValid)} type="submit">{formatMessage("Save")}</Button.Button>
              </div>
            </Fragment>
          );
        }}
      </Formik>
    </div>
  );
};


export default AccountDashboardProperties;
