import React, {HTMLAttributes, useEffect, useState} from "react";
import formatMessage from "format-message";
import {RadialProgress, Stack, Styles} from "@dashthis/ui";
import {dependenciesContentInfoStyle, dependenciesContentLeftStyle, dependenciesContentStyle, dependenciesContentSubTitleStyle, dependenciesContentTextStyle, dependenciesContentTitleContainerStyle, dependenciesContentTitleStyle} from "./styles/dependenciesContent.style";
import {Enums} from "@dashthis/studio-common";
import {useEventServiceContext} from "../../services/hooks/useEventServiceContext";

interface IProps extends HTMLAttributes<HTMLDivElement> {
}

export const DependenciesContent = (props: IProps) => {
  const {...rest} = props;
  const css = Styles.Hooks.useClassName(dependenciesContentStyle);
  const leftCss = Styles.Hooks.useClassName(dependenciesContentLeftStyle);
  const updateTextCss = Styles.Hooks.useClassName(dependenciesContentTextStyle);
  const updateTitleCss = Styles.Hooks.useClassName(dependenciesContentTitleStyle);
  const updateSubTitleCss = Styles.Hooks.useClassName(dependenciesContentSubTitleStyle);
  const updateInfoCss = Styles.Hooks.useClassName(dependenciesContentInfoStyle);
  const updateTitleContainerCss = Styles.Hooks.useClassName(dependenciesContentTitleContainerStyle);
  const eventService = useEventServiceContext();
  const [progressState, setProgressState] = useState({
    progress: 0,
    message: ""
  });
  const onInstallDependenciesProgress = (e: any, message: string, progress: number) => {
    setProgressState({
      progress,
      message
    });
  };

  useEffect(() => {
    eventService.on(Enums.IPCChannelEnum.InstallDependenciesProgress, onInstallDependenciesProgress);

    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.InstallDependenciesProgress, onInstallDependenciesProgress);
    };
  });

  return (
    <div className={css} {...rest}>
      <div className={leftCss}/>
      <div className={updateTextCss}>
        <Stack.HStack className={updateTitleContainerCss} gap={8} alignItems={Stack.Enums.AlignItemsEnum.Center}>
          <Stack.StackItem itemSize="auto" as="div">
            <RadialProgress.RadialProgress radius={20} stroke={5} progress={progressState.progress}/>
          </Stack.StackItem>
          <Stack.StackItem className={updateTitleCss} itemSize="1fr" as="p">
            {formatMessage("Installing dependencies")}
            <span>{progressState.message}</span>
          </Stack.StackItem>
        </Stack.HStack>
        <p className={updateSubTitleCss}>{formatMessage("Studio needs to install some dependencies to work properly.")}</p>
        <p className={updateInfoCss}>{formatMessage("This window will close after installation is completed.")}</p>
      </div>
    </div>
  );
};

export default DependenciesContent;
