import React, {useEffect, useMemo} from "react";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import formatMessage from "format-message";
import {Icon, SortHeader} from "../../../../../../../components";
import AccountDashboardsItem from "./AccountDashboardsItem";
import {Styles, VirtualizedList} from "@dashthis/ui";
import {accountDashboardListContainerStyle, accountDashboardListFooterStyle, accountDashboardListFooterTrashActivateIconStyle, accountDashboardListFooterTrashIconStyle, accountDashboardListSortContainerStyle} from "../styles/accountDashboardList.style";
import NoResultMessage from "../../../../SearchBar/components/NoResultMessage";
import {Conditional} from "@dashthis/common";
import {useSelectOpenedDashboard} from "../hooks/useSelectOpenedDashboard";
import {AccountModel} from "../../../../../../../models/Account";

interface IProps {
  /**
   * The list of dashboards in account.
   */
  dashboards: DashboardModel[];
  /**
   *
   */
  setDashboardSelected: (dashboard: DashboardModel | null) => void;
  /**
   *
   */
  dashboardSelected: DashboardModel | null,
  /**
   * Callback tp show or hide dashboard.
   */
  setShowDeletedDashboard: (value: boolean) => void,
  /**
   * Indicate if delete dashboard are show
   */
  showDeletedDashboard: boolean,
  /**
   * The number of dashboard Deleted.
   */
  deletedDashboardsCount: number,
  /**
   * The current search query
   */
  query: string,
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountDashboardsList = (props: IProps) => {
  const {dashboards, setDashboardSelected, account, dashboardSelected, showDeletedDashboard, setShowDeletedDashboard, deletedDashboardsCount, query} = props;
  const handlerItemClick = (dashboard: DashboardModel) => () => {
    setDashboardSelected(dashboard);
  };
  const noResultCss = Styles.Hooks.useClassName({
    textAlign: "left"
  });
  const handleNoRowsRenderer = () => {
    return (<NoResultMessage className={noResultCss} message={
      query !== ""
        ? formatMessage("Your search returned no results")
        : formatMessage("This account has no dashboards")
    }/>);
  };
  const containerCss = Styles.Hooks.useClassName(accountDashboardListContainerStyle);
  const sortContainerCss = Styles.Hooks.useClassName(accountDashboardListSortContainerStyle);
  const footerCss = Styles.Hooks.useClassName(accountDashboardListFooterStyle);
  const footerTrashIconCss = Styles.Hooks.useClassName(
    accountDashboardListFooterTrashIconStyle,
    Conditional.is(showDeletedDashboard, accountDashboardListFooterTrashActivateIconStyle)
  );
  const {listRef} = VirtualizedList.Hooks.useVirtualizedListScroll(`accountDashboardsList-${account.id}`);
  const handleTrashClick = () => {
    setShowDeletedDashboard(!showDeletedDashboard);
  };
  const sortFields = useMemo(() => {
    const fields = [
      {field: "title", display: formatMessage("Title")},
      {field: "creationDate", display: formatMessage("Creation Date")},
      {field: "dateLastAccessed", display: formatMessage("Last Accessed")}
    ];

    if (showDeletedDashboard) {
      fields.push({field: "dateDeleted", display: formatMessage("Deleted Date")});
    }

    return fields;
  }, [showDeletedDashboard]);
  const {onSortChange, sortedItems, selectedField} = SortHeader.Hooks.useSortHeader<DashboardModel>({field: "title", direction: "asc"}, dashboards, sortFields);
  const renderItem = (item: DashboardModel, index: number) => {
    const dashboard = sortedItems[index];

    return (
      <AccountDashboardsItem
        onClick={handlerItemClick(dashboard)}
        selected={dashboard.areSame(dashboardSelected!)}
        dashboard={dashboard}
        isOdd={index % 2 === 0}
      />
    );
  };
  const scrollToIndex = useSelectOpenedDashboard(sortedItems, dashboardSelected, setDashboardSelected);

  useEffect(() => {
    listRef.current.scrollToIndex(scrollToIndex);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scrollToIndex]);

  return (
    <div className={containerCss}>
      <div className={sortContainerCss}>
        <SortHeader.SortHeader selectedField={selectedField} onSortChange={onSortChange} fields={sortFields}/>
      </div>
      <VirtualizedList.VirtualizedList<DashboardModel> listRef={listRef} noRowsRenderer={handleNoRowsRenderer} items={sortedItems} estimateSize={50} keyExtractor={(d) => d.id!} renderItem={renderItem}/>
      <div className={footerCss}>
        <span><strong>{deletedDashboardsCount}</strong> {formatMessage("Deleted")}</span>
        <Icon.Icon className={footerTrashIconCss} onClick={handleTrashClick} icon={Icon.Enums.Icons.Trash}/>
      </div>
    </div>
  );
};


export default AccountDashboardsList;
