import {Styles} from "@dashthis/ui";

export const sortHeaderStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "sort-header",
  "span:nth-of-type(1)": {
    ...utilities.fontStyle({
      weight: "b",
      size: "small"
    })
  }
});

export const sortHeaderDirectionButtonStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "sort-header-direction-button",
  "&:hover": {
    cursor: "pointer"
  },
  padding: "2px 5px",
  ...utilities.fontStyle({
    weight: "n",
    color: "primary",
    size: "small"
  })
});
export const sortHeaderDirectionButtonSeparatorStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "sort-header-direction-button-separator",
  width:1,
  height:"100%",
  background: utilities.colors("grayChateau").alpha(.5).toString()
});
export const sortHeaderDirectionButtonSelectStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "sort-header-direction-button",
  background: utilities.colors("white").toString(),
  pointerEvents: "none"
});
export const sortHeaderChevronStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "sort-header-chevron",
  width: 6,
  height: 9,
  fill: utilities.colors("primary").toString()
});
export const sortHeaderFieldPickerStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "sort-header-field-picker",
  padding: "2px 5px",
  "&:hover": {
    cursor: "pointer",
    background: utilities.colors("white").toString()
  },
  "span:nth-of-type(1)": {
    ...utilities.ellipsis(),
    ...utilities.fontStyle({
      weight: "n",
      size: "small"
    })
  }
});
export const sortHeaderFieldPickerActivateStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "sort-header-field-picker-activate",
  background: utilities.colors("white").toString()
});
