import React, {HTMLAttributes, MouseEventHandler} from "react";
import {CsvFileModel} from "../../../../../../../models/CsvFile";
import {Icon} from "../../../../../../../components";
import {Styles, Tooltip} from "@dashthis/ui";
import {fileTemplatesFileItemDownloadIconStyle, fileTemplatesFileItemStyle, fileTemplatesItemSelectedStyle} from "./styles/fileTemplatesFileItem.style";
import {Conditional} from "@dashthis/common";
import {AccountModel} from "../../../../../../../models/Account";
import formatMessage from "format-message";
import {useDownloadCsvFile} from "../hooks/useDownloadCsvFile";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The file model.
   */
  file: CsvFileModel;
  /**
   * Indicate if the file are selected
   */
  selected: boolean;
  /**
   * The account model.
   */
  account: AccountModel;
}

export const FileTemplatesFileItem = (props: IProps) => {
  const {file, selected, account, ...rest} = props;
  const download = useDownloadCsvFile(file, account);
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    fileTemplatesFileItemStyle,
    Conditional.is(selected, fileTemplatesItemSelectedStyle)
  );
  const buttonCss = Styles.Hooks.useClassName(fileTemplatesFileItemDownloadIconStyle);
  const handleDownloadClick: MouseEventHandler = async (e) => {
    e.stopPropagation();

    await download();
  };

  return (
    <div {...rest} className={css}>
      <span>{file.name}</span>
      <Tooltip.Tooltip config={{offset: [0, 0]}} mode={Tooltip.Enums.TooltipShowModeEnum.OnMouseOver} Reference={<Icon.Icon className={buttonCss} onClick={handleDownloadClick} icon={Icon.Enums.Icons.ArrowDown}/>}>
        {formatMessage("Download csv file")}
      </Tooltip.Tooltip>
    </div>
  );
};


export default FileTemplatesFileItem;
