import {StudioCSS} from "../../../../../../styles/types";

export const listHeaderStyle: StudioCSS = (theme, utilities) => ({
  label: "list-header",
  display: "grid",
  padding: `0 ${utilities.space("n")}`,
  gridTemplateColumns: "auto 1fr",
  gap: utilities.space("s"),
  height: 55,
  alignItems: "center",
  borderBottom: `1px solid ${utilities.colors("athensGray").string()}`
});

export const listHeaderTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "list-header-title",
  ...utilities.fontStyle({
    size: "bigger",
    weight: "m"
  })
});

export const listHeaderCountStyle: StudioCSS = (theme, utilities) => ({
  label: "list-header-count",
  ...utilities.fontStyle({
    size: "regular",
    weight: "l"
  })
});
