import {StudioCSS} from "../../../../../../../../styles/types";

export const accountDashboardWidgetsSourceItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-source-item",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  padding: `${utilities.space("s")} ${utilities.space("s")}`,
  paddingLeft: 70,
  alignItems: "center",
  gap: utilities.space("s"),
  borderBottom: `1px solid ${utilities.colors("aquaHaze").string()}`,
  userSelect: "none",
  "&:hover": {
    cursor: "pointer"
  }
});

export const accountDashboardWidgetsSourceItemTitleContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-source-item-title-container",
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  alignItems: "center",
  gap: utilities.space("t"),
  ...utilities.ellipsis()
});

export const accountDashboardWidgetsSourceItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-source-item-title-selected",
  background: utilities.colors("chambray").alpha(.4).string()
});


export const accountDashboardWidgetsSourceItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-source-item-title",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "small"
  })
});

export const accountDashboardWidgetsSourceItemIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-source-item-icon",
  fill: utilities.colors("primary").string(),
  width: 14,
  height: 14
});
