import gql from "graphql-tag";
import {PlanParts} from "../plan/planParts";
import {UserParts} from "../user/userParts";
import {InvoicePart} from "../invoice/invoicePart";
import {AccountManagerPart} from "../accountManager/accountManagerPart";
import {FeaturePart} from "../feature/featurePart";
import {DocumentNode} from "graphql";

export const AccountParts: DocumentNode = gql`
    fragment AccountParts on Account {
        id
        companyName
        address1
        address2
        city
        region
        countryCode
        creationDate
        lastActivityDate
        nextPlanDate
        postalCode
        dashboardsUsed
        nextPaymentFrequency
        billingCustomerId
        accountManager {
            ...AccountManagerPart
        }
        lowTierManager {
            ...AccountManagerPart
        }
        saleManager {
            ...AccountManagerPart
        }
        ownerManager {
            ...AccountManagerPart
        }
        billingInfo {
            isYearlyBilling
            paymentFrequency
            nextPaymentDate
            lastPaymentDate
            canBeProcessedAutomatically
            hasSkippedPayment
            isPendingFrequencyDowngrade
        }
        plan {
            ...PlanParts
        }
        nextPlan {
            ...PlanParts
        }
        status {
            status
            expireDate
            startDate
        }
        creator {
            ...UserParts
        }
        users {
            ...UserParts
        }
        statusHistory {
            appliedDateTime
            id
            status
        }
        dashboardSettings {
            maxMonthImport
            maxSources
            maxWidgets
        }
        customSettings {
            poweredBy
            customURL
            customCss
        }
        lastUpdatedItems {
            ... on Invoice {
                ...InvoicePart
            }
        }
        lastCreatedItems {
            ... on Invoice {
                ...InvoicePart
            }
        }
        features {
            ...FeaturePart
        }
        usageLimits {
            __typename
            ... on UnlimitedUsageLimit {
                type
            }
            ... on LimitedUsageLimit {
                type
                current
                limit
            }
        }
        customizations {
            urlCustomization {
                ... on WhiteLabelUrlCustomization {
                    customDomainName
                }
            }
        }
        perks {
            customDomainPerk {
                hasAccessTo
                usesIt
            }
            customThemePerk {
                hasAccessTo
                usesIt
            }
        }
    }
    ${PlanParts}
    ${UserParts}
    ${InvoicePart}
    ${AccountManagerPart}
    ${FeaturePart}
`;