import React, {HTMLAttributes} from "react";
import {Styles} from "@dashthis/ui";
import {noResultMessageStyle} from "./styles/noResultMessage.style";
import formatMessage from "format-message";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Message to display.
   */
  message?: string;
}

interface IDefaultProps {
  message: string;
}

const defaultProps: IDefaultProps = {
  message: formatMessage("Your search returned no results")
};


export const NoResultMessage = (props: IProps) => {
  const {message, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, noResultMessageStyle);

  return (
    <div {...rest} className={css}>{message}</div>
  );
};


NoResultMessage.defaultProps = defaultProps;

export default NoResultMessage;