import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {useMemo} from "react";
import {accountUsageQuery} from "../queries/account/accountUsage.query";
import {Account} from "../models/Account";
import {AccountHealthModel, AccountHealth} from "../models/AccountHealth";

type useLoadAccountUsageResponseMatcher<R> = {
  onLoadAccountUsageError: (e: Client.Errors.ApplicationServerError) => R,
  onLoadAccountUsageLoading: () => R,
  onLoadAccountUsageLoaded: (accountHealth: AccountHealthModel) => R,
}

type Response = {
  account: DTGraphTypes.Account
};
type QueryArgs = {
  id: string,
  start?: Date
};

type LoadAccountUsage = {
  matcher: <R>(matcher: useLoadAccountUsageResponseMatcher<R>) => R
}

const matchResponse = <R>(accountHealth: AccountHealthModel, error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, loading: boolean, matcher: useLoadAccountUsageResponseMatcher<R>) => {
  if (error != null) {
    return matcher.onLoadAccountUsageError(error);
  }

  return !loading ? matcher.onLoadAccountUsageLoaded(accountHealth) : matcher.onLoadAccountUsageLoading();
};

const emptyResult: AccountHealthModel = AccountHealth({
  dashboardsUsage: [],
  integrationsUsage: [],
  mostUsedIntegrations: [],
  mostViewedDashboards: [],
  sourcesUsage: []
});

export const useLoadAccountUsage = (id: string, start?: Date): LoadAccountUsage => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<QueryArgs, Response>(accountUsageQuery, {
    variables: {
      id,
      start
    }
  });
  const accountHealth = useMemo(() => loading || error != null ? emptyResult : Account(data.account).Healths!, [data, error, loading]);

  return useMemo(() => ({
    matcher: (matcher) => matchResponse(accountHealth, error, loading, matcher)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [data, error, loading]);
};