import React from "react";
import formatMessage from "format-message";
import {CsvFileModel} from "../../../../../../../models/CsvFile";
import {Styles} from "@dashthis/ui";
import {fileTemplatesItemDetailStyle, fileTemplatesItemDetailStyleLabelStyle} from "./styles/fileTemplatesItemDetail.style";

interface IProps {
  /**
   * The source model.
   */
  file: CsvFileModel;
}

export const FileTemplatesFileDetail = (props: IProps) => {
  const {file} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesItemDetailStyle);
  const labelCss = Styles.Hooks.useClassName(fileTemplatesItemDetailStyleLabelStyle);

  return (
    <div className={css}>
      <label className={labelCss}>{formatMessage("Id")} <span>: {file.id}</span></label>
      <label className={labelCss}>{formatMessage("Name")} <span>: {file.name}</span></label>
      <label className={labelCss}>{formatMessage("Provider Key")} <span>: {file.providerKey}</span></label>
      <label className={labelCss}>{formatMessage("Last Applied")} <span>: {file.dateFormatted("dateLastApplied")}</span></label>
      <label className={labelCss}>{formatMessage("Uploaded At")} <span>: {file.dateFormatted("dateUploaded")}</span></label>
    </div>
  );
};


export default FileTemplatesFileDetail;

