import React from "react";
import {TaskBarSelectedItemAccount} from "../../../../states/types";
import {Styles} from "@dashthis/ui";
import AccountHeader from "./components/Header/AccountHeader";
import {accountStyle} from "./styles/account.style";
import {AccountContext} from "./context/AccountContext";
import AccountNavigation from "./AccountNavigation";
import {useLoadAccountDetails} from "../../../../hooks/useLoadAccountDetails";
import {AccountLoading} from "./AccountLoading";
import {ApplicationError} from "../../../ApplicationError";


interface IProps {
  /**
   * The current account selected.
   */
  accountSelected: TaskBarSelectedItemAccount;
}

export const Account = (props: IProps) => {
  const {accountSelected} = props;
  const {matcher} = useLoadAccountDetails(accountSelected.id);
  const css = Styles.Hooks.useClassName(accountStyle);

  return matcher({
    onAccountDetailsLoaded: (account) => (
      <AccountContext.Provider value={account}>
        <div className={css}>
          <AccountHeader account={account}/>
          <AccountNavigation account={account}/>
        </div>
      </AccountContext.Provider>
    ),
    onAccountDetailsLoading: () => (
      <AccountLoading/>
    ),
    onLoadAccountDetailsError: (e) => <ApplicationError error={e}/>
  });
};

export default Account;
