import {Styles} from "@dashthis/ui";
import {StudioCSS} from "../../../styles/types";

export const dependenciesContentStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "dependencies-content",
  display: "grid",
  gridTemplateColumns: "30px 1fr"
});

export const dependenciesContentLeftStyle: StudioCSS = (theme, utilities) => ({
  label: "dependencies-content-left",
  background: utilities.colors("primary").string(),
  display: "flex",
  justifyContent: "center",
  alignItems: "flex-start",
  borderTopLeftRadius: 3,
  borderBottomLeftRadius: 3,
  paddingTop: utilities.space("xl")
});

export const dependenciesContentTextStyle: StudioCSS = (theme, utilities) => ({
  label: "dependencies-content-text",
  background: utilities.colors("white").string(),
  padding: utilities.space("l"),
  p: {
    paddingBottom: utilities.space("n"),
    "&:last-child": {
      paddingBottom: 0
    }
  }
});

export const dependenciesContentTitleContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "dependencies-content-title-container",
  paddingBottom: utilities.space.normal
});

export const dependenciesContentTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "dependencies-content-title",
  ...utilities.fontStyle({
    weight: "m",
    size: "huge"
  }),
  span: {
    display: "block",
    ...utilities.fontStyle({
      weight: "n",
      size: "mini"
    })
  }
});

export const dependenciesContentSubTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "dependencies-content-sub-title",
  ...utilities.fontStyle({
    weight: "n",
    size: "regular"
  })
});

export const dependenciesContentInfoStyle: StudioCSS = (theme, utilities) => ({
  label: "dependencies-content-info",
  ...utilities.fontStyle({
    weight: "n",
    size: "small"
  })
});
