import {StudioCSS} from "../../../../../styles/types";

export const taskbarStyle: StudioCSS = (theme, utilities) => ({
  label: "taskbar",
  ...utilities.fontStyle({
    size: "regular"
  }),
  height: "100%",
  backgroundColor: utilities.colors("aquaHaze").string(),
  ...utilities.boxShadow({
    offsetX: 2,
    offsetY: 2,
    blurRadius: 5
  }),
  "[class*=taskbar-category-action]": {
    ...utilities.fontStyle({
      size: "small"
    })
  }
});
