import {useEndpointsServiceContext} from "../../services/hooks/useEndpointsServiceContext";

export const getEmulateUri = (email : string) => {
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const endPoints = useEndpointsServiceContext();

  return generateEmulateUri(endPoints.emulateEndpoints, email);
};

export const generateEmulateUri = (endpoint : string, email : string) => {
  return `${endpoint}?email=${encodeURIComponent(email)}`;
};
