import React from "react";
import {Input, Styles} from "@dashthis/ui";
import {searchFieldContainerStyle, searchFieldStyle} from "./styles/searchField.style";

interface IProps extends Input.Types.ISearchProps {
}

export const SearchField = (props: IProps) => {
  const {...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, searchFieldStyle);
  const containerCss = Styles.Hooks.useClassName(searchFieldContainerStyle);

  return (
    <div className={containerCss}>
      <Input.Search {...rest} className={css}/>
    </div>
  );
};


export default SearchField;
