import React from "react";
import {Styles} from "@dashthis/ui";
import {accountDashboardSwitchSectionStyle} from "./styles/accountDashboardSwitchSection.style";
import {DashboardNavigationBarItemsEnum} from "../enums/DashboardNavigationBarItemsEnum";
import {AccountDashboardHealth} from "../Health/AccountDashboardHealth";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {AccountDashboardWidgets} from "../Widgets/AccountDashboardWidgets";
import {AccountDashboardProperties} from "../Properties/AccountDashboardProperties";
import {AccountDashboardView} from "../View/AccountDashboardView";

interface IProps {
  /**
   * The dashboard mode.
   */
  dashboard: DashboardModel;
  /**
   * The current section selected.
   */
  sectionSelected: DashboardNavigationBarItemsEnum;
}

export const AccountDashboardSwitchSection = (props: IProps) => {
  const {sectionSelected, dashboard} = props;
  const css = Styles.Hooks.useClassName(accountDashboardSwitchSectionStyle);

  switch (sectionSelected) {
    case DashboardNavigationBarItemsEnum.Health:
      return (<AccountDashboardHealth className={css} dashboard={dashboard}/>);
    case DashboardNavigationBarItemsEnum.Widgets:
      return (<AccountDashboardWidgets className={css} dashboard={dashboard}/>);
    case DashboardNavigationBarItemsEnum.Properties:
      return (<AccountDashboardProperties key={dashboard.id!} className={css} dashboard={dashboard}/>);
    case DashboardNavigationBarItemsEnum.View:
      return (<AccountDashboardView className={css} dashboard={dashboard}/>);
  }
};

export default AccountDashboardSwitchSection;
