import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import React, {useCallback} from "react";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";

type UseDownloadFormUrl = (url: string) => Promise<string>;

export const useDownloadFormUrl = (): UseDownloadFormUrl => {
  const eventService = useEventServiceContext();

  return useCallback((url: string) => {
    return new Promise<string>((resolve, reject) => {
      const hideNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Downloading csv file...")}</Notification.LoadingNotification>);

      const stopDownloadFromUrlFailListener = eventService.onDownloadFromUrlFail((message) => {
        hideNotification();
        stopDownloadFromUrlCompleteListener();
        reject(message);
        Services.toastNotificationService.display(<Notification.ErrorNotification>{formatMessage("Failed to download csv file")}</Notification.ErrorNotification>);
      });

      const stopDownloadFromUrlCompleteListener = eventService.onDownloadFromUrlComplete((file) => {
        hideNotification();
        stopDownloadFromUrlFailListener();
        resolve(file);
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The csv file has been downloaded successful")}</Notification.SuccessNotification>);
      });

      eventService.sendDownloadFromUrl(url);
    });
  }, [eventService]);

};