import {StudioCSS} from "../../../../../../styles/types";

export const searchBarStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar",
  backgroundColor: utilities.colors("white").string(),
  display: "flex",
  alignItems: "center",
  padding: `${utilities.space("t")} 0`,
  position: "relative",
  ...utilities.boxShadow({
    offsetY: 0,
    offsetX: 5,
    blurRadius: 5
  }),
  "[class*=input]": {
    background: "transparent",
    border: 0,
    padding: `${utilities.space("t")} ${utilities.space("t")}`,
    ...utilities.fontStyle({
      size: "huge"
    })
  },
  zIndex: 10
});

export const searchBarFocusedStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-focused",
  zIndex: 100
});

export const searchBarClearStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-clear",
  transition: "color .1s",
  padding: `0 ${utilities.space("s")}`,
  ...utilities.fontStyle({
    size: "regular",
    weight: "m",
    color: "grayChateau"
  }),
  borderRight: `1px solid ${utilities.colors("grayChateau").string()}`,
  flex: "0 0 auto",
  "&:hover": {
    cursor: "pointer",
    ...utilities.fontStyle({
      color: "scorpion"
    })
  }
});

export const searchBarViewAllStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-clear",
  padding: `0 ${utilities.space("s")}`,
  transition: "color .1s",
  ...utilities.fontStyle({
    size: "regular",
    weight: "m",
    color: "grayChateau"
  }),
  borderRight: `1px solid ${utilities.colors("grayChateau").string()}`,
  flex: "0 0 auto",
  "&:hover": {
    cursor: "pointer",
    ...utilities.fontStyle({
      color: "scorpion"
    })
  }
});

export const searchBarMagnifierIconStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-magnifier-icon",
  width: "28px",
  height: "28px",
  opacity: ".5",
  fill: utilities.colors("grayChateau").string(),
  marginLeft: utilities.space("t"),
  flex: "0 0 auto"
});

export const searchBarClearIconStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-clear-icon",
  width: "22px",
  height: "22px",
  transition: "fill .1s",
  fill: utilities.colors("grayChateau").string(),
  marginRight: utilities.space("s"),
  marginLeft: utilities.space("s"),
  "&:hover": {
    cursor: "pointer",
    fill: utilities.colors("scorpion").string()
  }
});
