import {useEndpointsServiceContext} from "../../../../../../../services/hooks/useEndpointsServiceContext";
import {useOpenUrlServiceContext} from "../../../../../../../services/hooks/useOpenUrlServiceContext";
import React, {useCallback, useRef} from "react";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {Dialog, Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {Account} from "../../../../../../../models/Account";
import {accountUsersQuery} from "../../../../../../../queries/account/accountUsers.query";
import {generateEmulateUri} from "../../../../../helpers";
import {useEventServiceContext} from "../../../../../../../services/hooks/useEventServiceContext";
import {Client, DTGraphTypes} from "@dashthis/common";
import {useAccountContext} from "../../../hooks/useAccountContext";
import {useGenerateDashboardPdf} from "../../../../../hooks/useGenerateDashboardPdf";
import {useFileSystemServiceContext} from "../../../../../../../services/hooks/useFileSystemServiceContext";
import toBuffer from "typedarray-to-buffer";

type AccountUsersQueryVariables = {
  id: string
}
type AccountUsersQueryResponse = {
  account: DTGraphTypes.Account
}
type DashboardActions = {
  viewDashboard: (dashboard: DashboardModel) => void,
  viewDashboardInBrowser: (dashboard: DashboardModel) => void,
  editDashboard: (dashboard: DashboardModel) => void,
  editDashboardInBrowser: (dashboard: DashboardModel) => void,
  viewPath: (dashboard: DashboardModel) => string,
  editPath: (dashboard: DashboardModel) => string,
  exportToPdf: (dashboard: DashboardModel) => Promise<void>
}

const checkIfDashboardContainShortId = (dashboard: DashboardModel): boolean => {
  if (dashboard.shortId == null) {
    Dialog.ApplicationDialogs.error({
      title: formatMessage("View Dashboard Error"),
      message: formatMessage("The shortId prop are not defined in dashboard. See console log.")
    });

    // eslint-disable-next-line no-console
    console.error(new Error("The shortId prop are not defined in dashboard"), dashboard);

    return false;
  }

  return true;
};

export const useDashboardActions = (): DashboardActions => {
  const eventService = useEventServiceContext();
  const endpoints = useEndpointsServiceContext();
  const client = Client.Hooks.useClient();
  const redirectIndexRef = useRef(0);
  const {exportToPdf} = useGenerateDashboardPdf();
  const fileSystemService = useFileSystemServiceContext();
  const openUrlService = useOpenUrlServiceContext();
  const endpoint = useEndpointsServiceContext();
  const account = useAccountContext();
  const viewDashboardInBrowser = useCallback((dashboard: DashboardModel) => {
    if (checkIfDashboardContainShortId(dashboard)) {
      openUrlService.openUrl(`${endpoints.paths.dashboardBaseUrl}/view/dashboard-${dashboard.shortId}`);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const viewDashboard = useCallback(async (dashboard: DashboardModel) => {
    if (checkIfDashboardContainShortId(dashboard)) {
      const hideNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("View dashboard...")}</Notification.LoadingNotification>);

      try {
        const response = await client.query<AccountUsersQueryResponse, AccountUsersQueryVariables>({
          query: accountUsersQuery,
          variables: {
            id: account.id!
          }
        });

        redirectIndexRef.current = redirectIndexRef.current + 1;

        const accountUsers = Account(response.data!.account).Users;
        const userToEmulate = accountUsers[0];
        const url = generateEmulateUri(endpoint.emulateEndpoints, userToEmulate.email);
        const viewUrl = `${endpoint.paths.dashboardBaseUrl}/view/dashboard-${dashboard.shortId}?r=${redirectIndexRef.current}`;

        eventService.sendRequestEmulateWindow(url, userToEmulate.email, userToEmulate.email, endpoint.for, viewUrl);
        hideNotification();

      } catch (e) {
        hideNotification();
        Services.clientService.Error.displayError(e, formatMessage("Error on viewing dashboard."));
      }
    }

  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService, redirectIndexRef]);
  const editDashboard = useCallback(async (dashboard: DashboardModel) => {
    if (checkIfDashboardContainShortId(dashboard)) {
      const hideNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Edit dashboard...")}</Notification.LoadingNotification>);

      try {
        const response = await client.query<AccountUsersQueryResponse, AccountUsersQueryVariables>({
          query: accountUsersQuery,
          variables: {
            id: account.id!
          }
        });

        redirectIndexRef.current = redirectIndexRef.current + 1;

        const accountUsers = Account(response.data!.account).Users;
        const userToEmulate = accountUsers[0];
        const url = generateEmulateUri(endpoint.emulateEndpoints, userToEmulate.email);
        const editUrl = `${endpoint.paths.dashboardBaseUrl}/edit/dashboard-${dashboard.shortId}?r=${redirectIndexRef.current}`;

        eventService.sendRequestEmulateWindow(url, userToEmulate.email, userToEmulate.email, endpoint.for, editUrl);
        hideNotification();

      } catch (e) {
        hideNotification();
        Services.clientService.Error.displayError(e, formatMessage("Error on editing dashboard."));
      }
    }

  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService]);
  const editDashboardInBrowser = useCallback((dashboard: DashboardModel) => {
    if (checkIfDashboardContainShortId(dashboard)) {
      openUrlService.openUrl(`${endpoints.paths.dashboardBaseUrl}/edit/dashboard-${dashboard.shortId}`);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const viewPath = useCallback((dashboard: DashboardModel): string => {
    return `${endpoints.paths.dashboardBaseUrl}/view/dashboard-${dashboard.shortId}`;
  }, [endpoints]);
  const editPath = useCallback((dashboard: DashboardModel): string => {
    return `${endpoints.paths.dashboardBaseUrl}/edit/dashboard-${dashboard.shortId}`;
  }, [endpoints]);
  const generatePdf = useCallback(async (dashboard: DashboardModel): Promise<void> => {
    const pdfData = await exportToPdf(dashboard, viewPath(dashboard));
    const path = await fileSystemService.showSaveDialog({
      defaultPath: formatMessage("untitled.pdf")
    });

    if (path != null) {
      await fileSystemService.write(path, toBuffer(pdfData));
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [exportToPdf, viewPath]);

  return {
    viewDashboardInBrowser,
    exportToPdf: generatePdf,
    viewDashboard,
    editDashboard,
    editDashboardInBrowser,
    viewPath,
    editPath
  };
};