import React, {useState} from "react";
import {Icon, Menu, Stack, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {sortHeaderChevronStyle, sortHeaderDirectionButtonSelectStyle, sortHeaderDirectionButtonSeparatorStyle, sortHeaderDirectionButtonStyle, sortHeaderFieldPickerActivateStyle, sortHeaderFieldPickerStyle, sortHeaderStyle} from "./styles/SortHeader.style";
import {Conditional} from "@dashthis/common";

export type SortHeaderInitialField = Field & Direction;

type Field = {
  field: string,
  display: string
}

type Direction = {
  direction: "asc" | "desc",
}

interface IProps {
  fields: Field[];
  onSortChange: (field: string, direction: "asc" | "desc") => void;
  selectedField: Field & Direction;
}


export const SortHeader = (props: IProps) => {
  const {fields, onSortChange, selectedField} = props;
  const [menuOpen, setMenuOpen] = useState(false);
  const css = Styles.Hooks.useClassName(sortHeaderStyle);
  const cssChevron = Styles.Hooks.useClassName(sortHeaderChevronStyle);
  const cssFieldPicker = Styles.Hooks.useClassName(
    sortHeaderFieldPickerStyle,
    Conditional.is(menuOpen, sortHeaderFieldPickerActivateStyle)
  );
  const cssDirectionButton = Styles.Hooks.useClassName(sortHeaderDirectionButtonStyle);
  const cssDirectionButtonSeparator = Styles.Hooks.useClassName(sortHeaderDirectionButtonSeparatorStyle);
  const cssDirectionSelectedButton = Styles.Hooks.useClassName(sortHeaderDirectionButtonStyle, sortHeaderDirectionButtonSelectStyle);
  const handleDirectionClick = (direction: "asc" | "desc") => {
    onSortChange(selectedField.field, direction);
  };
  const handleMenuClick = (field: Field, hideMenu: () => void) => {
    onSortChange(field.field, selectedField.direction);
    hideMenu();
  };

  return (
    <Stack.HStack alignItems={Stack.Enums.AlignItemsEnum.Center} gap={5} className={css}>
      <Stack.StackItem as="span" itemSize="auto">{formatMessage("Sort by:")}</Stack.StackItem>
      <Menu.MenuPopper onMenuShow={() => setMenuOpen(true)} onMenuHide={() => setMenuOpen(false)} placement={Menu.Enums.MenuPlacementEnum.Bottom} reference={<Stack.HStack className={cssFieldPicker} alignItems={Stack.Enums.AlignItemsEnum.Center} gap={5} as="div">
        <Stack.StackItem as="span" itemSize="auto">{selectedField.display}</Stack.StackItem>
        <Stack.StackItem className={cssChevron} as={Icon.Icons.ArrowDownIcon} itemSize="auto"/>
      </Stack.HStack>}>
        {({hideMenu}) => (
          <Menu.Menu>
            {fields.map((i, index) => <Menu.MenuItem onClick={() => handleMenuClick(i, hideMenu)} disabled={i.field === selectedField.field} key={index}>{i.display}</Menu.MenuItem>)}
          </Menu.Menu>
        )}
      </Menu.MenuPopper>
      <Stack.StackItem  as="div" itemSize="1fr"/>
      <Stack.StackItem className={selectedField.direction === "asc" ? cssDirectionSelectedButton : cssDirectionButton} onClick={() => handleDirectionClick("asc")} as="div" itemSize="auto">asc</Stack.StackItem>
      <Stack.StackItem className={cssDirectionButtonSeparator}  as="div" itemSize="auto"/>
      <Stack.StackItem className={selectedField.direction === "desc" ? cssDirectionSelectedButton : cssDirectionButton} as="div" onClick={() => handleDirectionClick("desc")} itemSize="auto">desc</Stack.StackItem>
    </Stack.HStack>
  );
};

export default SortHeader;
