import {useEventServiceContext} from "../../services/hooks/useEventServiceContext";
import {useCallback, useEffect} from "react";
import {Enums} from "@dashthis/studio-common";
import {AppSectionEnum} from "../enums/AppSectionEnum";
import {enabledOsMenuItemBaseOnSection} from "../../utilities/enabledOsMenuItemBaseOnSection";

export const useActivateMenuItemOnWindowFocus = (section: AppSectionEnum) => {
  const eventService = useEventServiceContext();
  const handleOnWindowFocus = useCallback(() => {
    enabledOsMenuItemBaseOnSection(section, eventService);
  }, [eventService, section]);

  eventService.on(Enums.IPCChannelEnum.OnWindowFocus, handleOnWindowFocus);
  useEffect(() => {
    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.OnWindowFocus, handleOnWindowFocus);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService]);
};
