import React from "react";
import {Dialog, Styles, Window} from "@dashthis/ui";
import {Types} from "@dashthis/common";
import {aboutWindowStyle} from "./styles/aboutWindow.style";
import {useEventServiceContext} from "../../services/hooks/useEventServiceContext";
import {Enums} from "@dashthis/studio-common";
import {AboutContent} from "./AboutContent";

interface IProps {
}

export const AboutWindow = (props: IProps) => {
  const {ModalComponent, manager, showModal, closeModal} = Dialog.Hooks.useModal();
  const eventService = useEventServiceContext();
  const size: Types.Geometry.Size = {
    width: 490,
    height: 0
  };
  const frameCss = Styles.Hooks.useClassName(aboutWindowStyle);

  eventService.on(Enums.IPCChannelEnum.ViewAbout, showModal);

  return (
    <ModalComponent manager={manager}>
      <Window.Frame className={frameCss} size={size}>
        <AboutContent onClose={closeModal}/>
      </Window.Frame>
    </ModalComponent>
  );
};

export default AboutWindow;
