import {useEventServiceContext} from "../../services/hooks/useEventServiceContext";
import {useEffect} from "react";
import {AppSectionEnum} from "../enums/AppSectionEnum";
import {enabledOsMenuItemBaseOnSection} from "../../utilities/enabledOsMenuItemBaseOnSection";

export const useActivateMenuItemSection = (section: AppSectionEnum) => {
  const eventService = useEventServiceContext();

  useEffect(() => {
    enabledOsMenuItemBaseOnSection(section, eventService);
  }, [eventService, section]);
};
