import React, {HTMLAttributes} from "react";
import Gravatar from "../../../Accounts/List/Gravatar";
import {UserModel} from "../../../../../../models/User";
import {Styles} from "@dashthis/ui";
import {userItemGravatarContainerStyle, userItemGravatarStyle, userItemLastSeenStyle, userItemStyle, userItemTitleStyle} from "./styles/userItem.Style";

interface Props extends HTMLAttributes<HTMLDivElement> {
  /**
   * The user model.
   */
  user: UserModel;
}

export const UserItem = (props: Props) => {
  const {user, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, userItemStyle);
  const gravatarCss = Styles.Hooks.useClassName(userItemGravatarStyle);
  const gravatarContainerCss = Styles.Hooks.useClassName(userItemGravatarContainerStyle);
  const titleCss = Styles.Hooks.useClassName(userItemTitleStyle);
  const lastSeenCss = Styles.Hooks.useClassName(userItemLastSeenStyle);

  return (
    <div {...rest} className={css}>
      <div className={gravatarContainerCss}>
        <Gravatar className={gravatarCss} user={user}/>
        <span className={titleCss}>{user.email}</span>
      </div>
      <span className={lastSeenCss}>{user.lastSeen}</span>
    </div>
  );
};


export default UserItem;
