import React from "react";
import {Bar} from "react-chartjs-2";
import {Styles} from "@dashthis/ui";
import {healthGraphStyle, healthGraphTitleStyle} from "../Dashboards/Health/styles/healthGraph.style";
import formatMessage from "format-message";
import {MostUsedIntegrationsModel} from "../../../../../../models/MostUsedIntegrations";
import {sort} from "fast-sort";

interface IProps {
  /**
   * Array contains usage stats.
   */
  stats: MostUsedIntegrationsModel[];
}

const formatData = (stats: MostUsedIntegrationsModel[]) => {
  const sortStats = sort(stats).by([
    {desc: s => s.count}
  ]);

  const labels = sortStats.map((s) => s.Integration!.name);
  const counts = sortStats.map((s) => s.count);

  return {
    labels,
    datasets: [{
      label: formatMessage("Connected authorizations"),
      data: counts,
      precision: 0
    }]
  };
};
const graphOptions = {
  maintainAspectRatio: true,
  scales: {
    xAxes: [{
      display: true,
      ticks: {
        callback: (dataLabel: string, index: number) => {
          return index % 2 === 0 ? dataLabel : "";
        }
      }
    }],
    yAxes: [{
      ticks: {
        stepSize: 2
      }
    }]
  }
};

export const MostUsedIntegrations = React.memo<IProps>((props) => {
  const {stats} = props;
  const css = Styles.Hooks.useClassName(healthGraphStyle);
  const titleCss = Styles.Hooks.useClassName(healthGraphTitleStyle);

  return (
    <div className={css}>
      <span className={titleCss}>{formatMessage("Most usage integrations")}</span>
      <Bar
        height={100}
        data={formatData(stats)}
        options={graphOptions}
      />
    </div>
  );
});


export default MostUsedIntegrations;
