import {Styles, Taskbar} from "@dashthis/ui";
import React from "react";
import {TaskBarSelectedItem, TaskBarSelectedItemSearch} from "../../../../../../states/types";
import {taskbarItemStyle} from "../../styles/taskbarItem.style";
import {useGetCountAccounts} from "../../../../../../hooks/useGetCountAccounts";
import {TaskBarItemTypeEnum} from "../../../../../../enums/TaskBarItemTypeEnum";
import formatMessage from "format-message";

interface IProps {
  /**
   * Indicate which item are select in taskbar.
   */
  selected: TaskBarSelectedItemSearch,
  /**
   * Callback when item are clicked.
   */
  onItemClick: (item: TaskBarSelectedItem) => void,
  /**
   * The current search  query
   */
  searchQuery: string
}

export const SearchTaskbarItem = (props: IProps) => {
  const {selected, onItemClick, searchQuery} = props;
  const {matcher} = useGetCountAccounts(searchQuery);
  const taskbarItemCss = Styles.Hooks.useClassName(taskbarItemStyle);
  const handleListClick = () => {
    onItemClick({
      type: TaskBarItemTypeEnum.Searching
    });
  };

  return matcher({
    onGetCountAccountsError: (error) => <Taskbar.TaskbarItemError error={error}/>,
    onGetCountAccountsLoading: () => <Taskbar.TaskbarItemLoading/>,
    onGetCountAccountsLoaded: (count) => <Taskbar.TaskbarItem
      className={taskbarItemCss}
      text={formatMessage("Searching...")}
      count={count}
      otherText={searchQuery}
      onClick={handleListClick}
      selected={selected.type === TaskBarItemTypeEnum.Searching}
    />
  });
};


export default SearchTaskbarItem;
