import {StudioCSS} from "../../../../../../../../styles/types";

export const accountDashboardHeaderStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-header",
  display: "grid",
  gridTemplateColumns: "1fr",
  borderBottom: `1px solid ${utilities.colors("aquaHaze").string()}`,
  gridColumn: "1/3"
});

export const accountDashboardHeaderBlockStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboardd-header-block",
  background: utilities.colors("athensGray").string()
});

export const accountDashboardHeaderLabelStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-header-label",
  ...utilities.fontStyle({
    weight: "b",
    size: "regular"
  }),
  span: {
    ...utilities.fontStyle({weight: "n"})
  }
});

export const accountDashboardHeaderInfoContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-header-info-container",
  padding: `${utilities.space("n")} ${utilities.space("n")}`,
  display: "grid",
  gridTemplateColumns: "minmax(400px, 50%) minmax(400px, 50%)"
});

export const accountDashboardHeaderInfoTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-header-info-title",
  gridColumn: "1/3",
  ...utilities.ellipsis()
});

export const accountDashboardHeaderInfoIdStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-header-info-id",
  paddingBottom: utilities.space("s"),
  gridColumn: "1/3"
});

export const accountDashboardHeaderInfoColOneStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-header-info-col-one",
  gridColumn: "1"
});

export const accountDashboardHeaderInfoColTwoStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-header-info-col-two",
  gridColumn: "2"
});
