import {StudioCSS} from "../../../../../../../../styles/types";

export const fileTemplatesFileItemStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-file-item",
  display: "grid",
  gridTemplateColumns: "10px 1fr auto",
  ...utilities.fontStyle({
    size: "regular",
    weight: "n"
  }),
  alignItems: "center",
  padding: `0 20px 0 30px`,
  minHeight: 40,
  "&:before": {
    content: `""`,
    borderLeft: `solid 1px ${utilities.colors("athensGray")}`,
    height: "100%"
  },
  span: {
    ...utilities.ellipsis()
  },
  "&:hover": {
    cursor: "pointer"
  }
});

export const fileTemplatesFileItemDownloadIconStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-file-item-download-icon",
  width: 15,
  height: 15,
  background: utilities.colors("aquaHazeLight").string(),
  fill: utilities.colors("scorpion").string(),
  padding: utilities.space("t"),
  boxSizing: "content-box",
  borderRadius: 2,
  marginLeft: utilities.space("s"),
  ":hover": {
    cursor: "pointer",
    background: utilities.colors("aquaHazeLight").darken(.1).string()
  }
});

export const fileTemplatesItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-item-selected",
  backgroundColor: utilities.colors("chambray").alpha(.4).string(),
  "&:hover": {
    cursor: "default"
  },
  "&:before": {
    borderLeft: 0
  }
});