import React, {HTMLAttributes} from "react";
import LogoIcon from "../../medias/svg/about_logo.inline.svg";
import formatMessage from "format-message";
import {Stack, Styles} from "@dashthis/ui";
import {Button} from "../../components";
import {aboutContentIconStyle, aboutContentLeftStyle, aboutContentStyle, aboutContentTextStyle} from "./styles/aboutContent.style";
import {app} from "@electron/remote";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Callback to close window
   */
  onClose: () => void;
}

export const AboutContent = (props: IProps) => {
  const {onClose, ...rest} = props;
  const css = Styles.Hooks.useClassName(aboutContentStyle);
  const leftCss = Styles.Hooks.useClassName(aboutContentLeftStyle);
  const updateIconCss = Styles.Hooks.useClassName(aboutContentIconStyle);
  const updateTextCss = Styles.Hooks.useClassName(aboutContentTextStyle);

  return (
    <div className={css} {...rest}>
      <div className={leftCss}>
        <LogoIcon className={updateIconCss}/>
      </div>
      <div className={updateTextCss}>
        <p>{formatMessage("About Studio 3")}</p>
        <p><strong>{formatMessage("Version")}</strong> {app.getVersion()}</p>
        <p>{formatMessage("DashThis is a brand owned by Moment Zero inc © 2011-2022 DashThis.com")}</p>
        <Stack.HStack justifyContent={Stack.Enums.JustifyContentEnum.End}>
          <Button.Button onClick={onClose}>{formatMessage("OK")}</Button.Button>
        </Stack.HStack>
      </div>
    </div>
  );
};

export default AboutContent;
