import React from "react";
import {Geography, Styles} from "@dashthis/ui";
import {countyPickerStyle} from "./styles/countyPicker.style";

interface IProps extends Geography.Types.ICountryPickerProps {
}

export const CountryPicker = (props: IProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, countyPickerStyle);

  return (
    <Geography.CountryPicker {...props} className={css}/>
  );
};


export default CountryPicker;
