import {useAccountManagerStateSelector} from "../../../../../states/hooks";
import {useEffect} from "react";
import {useAccountPersistedState} from "./useAccountPersistedState";
import {AccountNavigationBarItemsEnum} from "../enums/AccountNavigationBarItemsEnum";
import {OpenedDashboard, OpenedFileTemplate, OpenedUser} from "../../../../../states/reducers/accountManager";
import {AccountModel} from "../../../../../models/Account";
import {useAccountContext} from "./useAccountContext";

type AccountNavigation = {
  navigationBarSection: AccountNavigationBarItemsEnum,
  setNavigationBarSection: (item: AccountNavigationBarItemsEnum) => void
}

const getDefaultNavigationSelected = (openedFileTemplate: OpenedFileTemplate, openedDashboard: OpenedDashboard, openedUser: OpenedUser, account: AccountModel): AccountNavigationBarItemsEnum => {
  if (openedFileTemplate != null && openedFileTemplate.account === account.id) {
    return AccountNavigationBarItemsEnum.FileTemplates;
  } else if (openedDashboard != null && openedDashboard.account === account.id) {
    return AccountNavigationBarItemsEnum.Dashboards;
  } else if (openedUser != null && openedUser.account === account.id) {
    return AccountNavigationBarItemsEnum.Users;
  } else {
    return AccountNavigationBarItemsEnum.Health;
  }
};

export const useAccountNavigation = (): AccountNavigation => {
  const openedDashboard = useAccountManagerStateSelector("openedDashboard");
  const openedUser = useAccountManagerStateSelector("openedUser");
  const openedFileTemplate = useAccountManagerStateSelector("openedFileTemplate");
  const account = useAccountContext();
  const [navigationBarSection, setNavigationBarSection] = useAccountPersistedState<AccountNavigationBarItemsEnum>("navigationBarSelected", getDefaultNavigationSelected(openedFileTemplate, openedDashboard, openedUser, account));

  useEffect(() => {
    if (openedDashboard != null) {
      setNavigationBarSection(AccountNavigationBarItemsEnum.Dashboards);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openedDashboard]);

  useEffect(() => {
    if (openedUser != null) {
      setNavigationBarSection(AccountNavigationBarItemsEnum.Users);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openedUser]);

  useEffect(() => {
    if (openedFileTemplate != null) {
      setNavigationBarSection(AccountNavigationBarItemsEnum.FileTemplates);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openedFileTemplate]);

  return {
    navigationBarSection,
    setNavigationBarSection
  };
};