export const radialProgressStyle = (theme, utilities) => ({
    label: "radial-progress",
    transform: "rotate(-90deg)",
    fill: "none"
});
export const radialProgressValueStyle = (theme, utilities) => ({
    label: "radial-progress-value",
    stroke: utilities.colors("primary").string(),
    strokeLinecap: "round"
});
