import React from "react";
import {Account} from "@dashthis/common";
import {Dialog, Notification, Services, Window} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseDeleteAccount = [() => Promise<boolean>, boolean];

const displayDialogToConfirmDeleteAccount = (account: AccountModel): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    const name = account.companyName || account.Creator!.email;

    Dialog.ApplicationDialogs.message({
      title: formatMessage("Delete account?"),
      message: formatMessage("Are you sure you want to delete this account: {name}?", {
        name
      }),
      okText: formatMessage("Delete Account"),
      cancelText: formatMessage("Do Not Delete"),
      ui: Window.Enums.WindowStyleEnum.Error,
      okClick: () => {
        resolve(true);
      },
      cancelClick: () => {
        resolve(false);
      }
    });
  });
};

export const useDeleteAccount = (account: AccountModel): UseDeleteAccount => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);

  const suspendAccount = async (): Promise<boolean> => {
    const confirm = await displayDialogToConfirmDeleteAccount(account);

    if (confirm) {
      const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Deleting account...")}</Notification.LoadingNotification>);

      try {
        await updateAccount({
          deleteAccount: true
        });
        hideLoadingNotification();
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The account has been successfully deleted.")}</Notification.SuccessNotification>);

        return true;
      } catch (e) {
        hideLoadingNotification();
        Services.clientService.Error.displayError(e, formatMessage("Deleting account error!"));

        return false;
      }
    }

    return false;
  };

  return [suspendAccount, loading];
};