import React, {HTMLAttributes} from "react";
import {Styles, Tooltip} from "@dashthis/ui";
import {Icon} from "../../../../../../components";
import {accountHeaderToolsButtonIconStyle, accountHeaderToolsButtonStyle} from "./styles/accountHeaderToolsButton.style";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The Icon for button.
   */
  icon: Icon.Enums.Icons;
  /**
   * The tooltips for button
   */
  tooltip?: string;
}

export const AccountHeaderToolsButton = (props: IProps) => {
  const {icon, tooltip, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, accountHeaderToolsButtonStyle);
  const iconCss = Styles.Hooks.useClassName(accountHeaderToolsButtonIconStyle);
  const button = (
    <div {...rest} className={css}>
      <Icon.Icon className={iconCss} icon={icon}/>
    </div>
  );

  if (tooltip != null) {
    return (
      <Tooltip.Tooltip mode={Tooltip.Enums.TooltipShowModeEnum.OnMouseOver} config={{offset: [-5, 10]}} Reference={button}>
        {tooltip}
      </Tooltip.Tooltip>
    );
  }

  return button;
};


export default AccountHeaderToolsButton;
