import {Spinner, Styles} from "@dashthis/ui";
import {Conditional, Enums} from "@dashthis/common";
import * as React from "react";
import {HTMLAttributes} from "react";
import {usePingUrl} from "../hooks/usePingUrl";
import {connectToDrawerItemContainerDisabledStyle, connectToDrawerItemContainerLoadingStyle, connectToDrawerItemContainerSelectedStyle, connectToDrawerItemContainerStyle, connectToDrawerItemIndicatorDownStyle, connectToDrawerItemIndicatorStyle, connectToDrawerItemIndicatorUpStyle, connectToDrawerItemStyle} from "../styles/connectToItem.style";
import {useValidConnectionForEnv} from "../hooks/useValidConnectionForEnv";
import {useRouterContext} from "../../../router";
import {Typo} from "../../../components/Typo/Typo";
import {Icon} from "../../../components";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The title for this item.
   */
  title: string;
  /**
   * The url to display under title.
   */
  url: string;
  /**
   * The config key for this item.
   */
  env: Enums.EnvsEnum;
  /**
   * Indicate if item are selected.
   */
  selected: boolean;
  /**
   * Callback to select a item in list of connection.
   */
  setSelected: (value: Enums.EnvsEnum | null) => void,
  /**
   * Indicate if item are disabled.
   */
  disabled: boolean,
  /**
   *
   */
  setLoading: (value: boolean) => void
}

const formatUrl = (url: string): string => {
  const uri = new URL(url);

  return uri.hostname;
};

export const Item = (props: IProps) => {
  const {url, title, env, selected, setSelected, disabled, setLoading, ...rest} = props;
  const {navigate} = useRouterContext();
  const [processing, validConnectionForEnv] = useValidConnectionForEnv(env);
  const isUp = usePingUrl(url);
  const itemCss = Styles.Hooks.useClassName(connectToDrawerItemStyle);
  const itemContainerCss = Styles.Hooks.useClassName(
    connectToDrawerItemContainerStyle,
    Conditional.is(selected, connectToDrawerItemContainerSelectedStyle),
    Conditional.is(processing, connectToDrawerItemContainerLoadingStyle),
    Conditional.is(disabled, connectToDrawerItemContainerDisabledStyle)
  );
  const itemIndicatorCss = Styles.Hooks.useClassName(
    connectToDrawerItemIndicatorStyle,
    Conditional.is(isUp, connectToDrawerItemIndicatorUpStyle),
    Conditional.isNot(isUp, connectToDrawerItemIndicatorDownStyle)
  );
  const handleClick = async () => {
    setLoading(true);

    const result = await validConnectionForEnv();

    setLoading(false);
    if (!result) {
      setSelected(env);
    } else {
      await navigate(`/accountManager/${env}`);
    }
  };

  return (
    <div onClick={handleClick} className={itemContainerCss} {...rest}>
      {processing
        ? <Spinner.Spinner size={Spinner.Enums.SpinnerSizeEnum.Small} delayed={false} ui={Spinner.Enums.SpinnerStyleEnum.Invert}/>
        : null
      }
      <div className={itemIndicatorCss}/>
      <div className={itemCss}>
        <Icon.Icon icon={Icon.Enums.Icons.Cloud}/>
        <div>
          <Typo element="span" fontColor="white" fontWeight="m" fontSize="regular">DashThis</Typo>
          <Typo element="span" fontColor="white" fontWeight="m" fontSize="regular"> | </Typo>
          <Typo element="span" fontColor="white" fontWeight="l" fontSize="small">{title}</Typo>
        </div>
        <Typo element="span" fontColor="white" fontWeight="l" fontSize="tiny">{formatUrl(url)}</Typo>
      </div>
    </div>
  );
};


export default Item;
