import {DTGraphTypes, Models} from "@dashthis/common";
import {Widgets} from "@dashthis/ui";

export interface IFormatter extends DTGraphTypes.Formatter {
  icon: Widgets.Types.WidgetIcon;
}

export type FormatterModel = Models.Types.Model<IFormatter>;

export const Formatter: Models.Types.ModelCtr<DTGraphTypes.Formatter, IFormatter> = (data) => ({
  ...data,
  get icon() {
    switch (data.name) {
      case "Rolling Widget":
        return Widgets.Icons.RollingListWidgetIcon;
      case "Historic":
        return Widgets.Icons.HistoricWidgetIcon;
      case "Header":
        return Widgets.Icons.HeaderWidgetIcon;
      case "Comments":
        return Widgets.Icons.CommentsWidgetIcon;
      case "Multi-Column List":
        return Widgets.Icons.MultiColumnWidgetIcon;
      case "Simple Number":
        return Widgets.Icons.SimpleNumberWidgetIcon;
      case "List":
        return Widgets.Icons.ListWidgetIcon;
      case "Gauge":
        return Widgets.Icons.GaugeWidgetIcon;
      case "Trend":
        return Widgets.Icons.TrendWidgetIcon;
      case "Stacked Columns":
        return Widgets.Icons.StackedColumnsWidgetIcon;
      case "CSV":
        return Widgets.Icons.CsvWidgetIcon;
      case "Editable Number":
        return Widgets.Icons.EditableNumberWidgetIcon;
      case "Rolling List":
        return Widgets.Icons.RollingListWidgetIcon;
      default:
        return Widgets.Icons.DefaultWidgetIcon;
    }
  }
});