import React from "react";
import {QueryProcessor, Styles} from "@dashthis/ui";
import {Models} from "@dashthis/common";
import {accountPlanSelectorStyle} from "./styles/AccountPlanSelector.style";
import AccountPlanList from "./AccountPlanList";
import {useGetPlans} from "../../../../../../hooks/useGetPlans";
import {useAccountPersistedState} from "../../hooks/useAccountPersistedState";
import AccountPlanActions from "./AccountPlanActions";
import AccountPlanActionSelectPlan from "./AccountPlanActionSelectPlan";
import {AccountModel} from "../../../../../../models/Account";

interface IProps {
  /**
   * Component children.
   */
  account: AccountModel;
}

export const AccountPlanSelector = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(accountPlanSelectorStyle);
  const [plans, loading, error] = useGetPlans();
  const [planSelected, setPlanSelected] = useAccountPersistedState<Models.Plan.PlanModel | null>(`planSelected`, null);

  return (
    <div className={css}>
      <QueryProcessor.QueryProcessor loading={loading} error={error}>
        <AccountPlanList setPlanSelected={setPlanSelected} planSelected={planSelected} plans={plans}/>
      </QueryProcessor.QueryProcessor>
      {
        planSelected != null
          ? <AccountPlanActions account={account} plan={planSelected}/>
          : <AccountPlanActionSelectPlan/>
      }
    </div>
  );
};


export default AccountPlanSelector;
