import {StudioCSS} from "../../../../../../styles/types";


export const searchBarFooterStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-footer",
  ...utilities.fontStyle({
    size: "tiny"
  }),
  display: "flex",
  alignItems: "center",
  padding: utilities.space("s"),
  paddingLeft: 0,
  borderTop: `${utilities.colors("geyser")} solid 1px`,
  background: utilities.colors("porcelain").string()
});

export const searchBarFooterEnterKeyStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-footer-enter-key",
  padding: `.1rem .3rem`,
  border: `1px solid ${utilities.colors("geyser")}`,
  background: utilities.colors("white").string(),
  borderRadius: "3px",
  ...utilities.boxShadow({
    offsetY: 0,
    offsetX: 0,
    blurRadius: 1
  })
});

export const searchBarFooterKeysStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-footer-keys",
  padding: `0 ${utilities.space("s")}`
});

export const searchBarFooterSpinnerStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-footer-spinner",
  position: "absolute",
  right: utilities.space("s"),
  fontSize: 20
});
