import React from "react";
import {List} from "../List/List";
import {useAccountManagerStateActions} from "../../../../../states/hooks";
import {AccountModel} from "../../../../../models/Account";
import {DocumentNode} from "graphql";
import {Styles} from "@dashthis/ui";
import {listStyle} from "../List/styles/list.style";
import {Header} from "../ListHeader/Header";
import {ListAccountsBaseVariables, useListAccounts} from "../../../hooks/useListAccounts";
import ListLoading from "../List/ListLoading";

interface IProps<T extends ListAccountsBaseVariables> {
  /**
   * The title for the list.
   */
  title: string;
  /**
   * The query for this list of accounts
   */
  query: DocumentNode;
  /**
   * The variables for query.
   */
  variables: T;
}

export const AccountsList = <T extends ListAccountsBaseVariables>(props: IProps<T>) => {
  const {variables, query, title} = props;
  const {openAccounts} = useAccountManagerStateActions();
  const css = Styles.Hooks.useClassName(listStyle);
  const accountListing = useListAccounts(variables, query);
  const handleDoubleClick = (account: AccountModel, e: React.MouseEvent) => {
    openAccounts(new Set([account.id!]));
  };

  return (
    <div className={css}>
      <Header title={title} count={accountListing.loading ? -1 : accountListing.total}/>
      {accountListing.loading
        ? <ListLoading/>
        : <List
          keyList={accountListing.id}
          loading={accountListing.loading}
          accounts={accountListing.accounts}
          onDoubleClick={handleDoubleClick}
          loadMore={accountListing.fetchMore}
        />
      }
    </div>
  );
};

export default AccountsList;
