import {StudioCSS} from "../../../../../../../styles/types";

export const dashboardReportItemStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-report-item",
  padding: utilities.space("s")
});

export const dashboardReportItemContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-report-item-container",
  paddingBottom: utilities.space("s"),
  borderBottom: `1px solid ${utilities.colors("athensGray").toString()}`
});

export const dashboardReportItemTitleContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-report-item-title-container",
  ...utilities.ellipsis()
});

export const dashboardReportItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-report-item-title",
  display: "block",
  ...utilities.fontStyle({
    size: "small",
    weight: "m"
  }),
  ...utilities.ellipsis()
});

export const dashboardReportItemDateStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-date",
  display: "block",
  ...utilities.fontStyle({
    size: "tiny",
    weight: "l"
  }),
  ...utilities.ellipsis()
});

export const dashboardReportItemLetterStyle: StudioCSS = (theme, utilities) => ({
  label: "dashboard-report-item-letter",
  alignSelf: "center",
  position: "relative",
  paddingRight: utilities.space("s"),
  ...utilities.fontStyle({
    size: "massive",
    weight: "b"
  }),
  "&:after": {
    content: `""`,
    width: 1,
    height: "100%",
    right: 5,
    top: 0,
    position: "absolute",
    background: utilities.colors("scorpion").string()
  }
});
