import {DTGraphTypes, Enums, Models} from "@dashthis/common";

interface IDashboardType extends DTGraphTypes.DashboardType {
  color: string;
  isCampaign: boolean;
  isPeriodic: boolean;
  isRolling: boolean;
  dashboardTypeLetter: string;
}

export type DashboardTypeModel = Models.Types.Model<IDashboardType>;

export const DashboardType: Models.Types.ModelCtr<DTGraphTypes.DashboardType, IDashboardType> = (data) => ({
  ...data,
  get dashboardTypeLetter() {
    if (this.isCampaign) {
      return "C";
    } else if (this.isPeriodic) {
      return "P";
    } else {
      return "R";
    }
  },
  get isCampaign() {
    return this.id === Enums.DashboardTypeEnum.Campaign;
  },
  get isPeriodic() {
    return this.id === Enums.DashboardTypeEnum.Periodic;
  },
  get isRolling() {
    return this.id === Enums.DashboardTypeEnum.Rolling;
  },
  get color() {
    switch (this.id) {
      case Enums.DashboardTypeEnum.Campaign:
        return "#e3604e";
      case Enums.DashboardTypeEnum.Periodic:
        return "#3cb89f";
      case Enums.DashboardTypeEnum.Rolling:
        return "#eec03f";
      default :
        return "#3cb89f";
    }
  }
});