import React, {HTMLAttributes, ReactNode} from "react";
import {Portal, Styles} from "@dashthis/ui";
import Footer from "./Footer";
import {searchBarBodyStyle, searchBarBodyOverlayStyle} from "./styles/searchBarBody.style";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  children?: ReactNode,
  /**
   * Set to true to display the spinner in footer.
   */
  loading: boolean
}

export const Body = React.memo<IProps>((props: IProps) => {
  const {children, loading, ...rest} = props;
  const bodyCss = Styles.Hooks.useClassName(searchBarBodyStyle);
  const bodyOverlayCss = Styles.Hooks.useClassName(searchBarBodyOverlayStyle);

  return (
    <Portal.Portal className="portal-search-body" id="portal-search-body">
      <div className={bodyOverlayCss}/>
      <div className={bodyCss}>
        <div {...rest}>
          {children}
        </div>
        <Footer loading={loading}/>
      </div>
    </Portal.Portal>
  );
});


export default Body;
