import {AccountDashboardErrorReportModel} from "../../../../../../../models/AccountDashboardErrorReport";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {AuthorizationModel} from "../../../../../../../models/Authorization";
import {SourceModel} from "../../../../../../../models/Source";
import {useCallback, useMemo} from "react";
import {sort} from "fast-sort";
import {useAccountPersistedState} from "../../../hooks/useAccountPersistedState";

export type DashboardsGroupReport = {
  dashboard: DashboardModel,
  authorizations: AuthorizationModel[],
  sources: SourceModel[]
}
type RegroupByDashboard = {
  query: string,
  onClearClick: () => void,
  onSearchChange: (value: string) => void,
  dashboards: DashboardsGroupReport[]
}
export const useRegroupByDashboard = (dashboardsReport: AccountDashboardErrorReportModel[]): RegroupByDashboard => {
  const [query, setQuery] = useAccountPersistedState<string>(`dashboardsReportSearch`, "");
  const onClearClick = useCallback(() => {
    setQuery("");
  }, [setQuery]);
  const onSearchChange = useCallback((value: string) => {
    setQuery(value);
  }, [setQuery]);
  const dashboards = useMemo(() => {
    const groups: DashboardsGroupReport[] = [];
    const filteredDashboard = query !== "" ? dashboardsReport.filter((i) => {
      const searchResult = [i.Dashboard()?.matchQuery(query), i.Source()?.matchQuery(query), i.Authorization()?.matchQuery(query)];

      return searchResult.some((v) => v);
    }) : dashboardsReport;

    filteredDashboard.forEach((r) => {
      const index = groups.findIndex((i) => i.dashboard.id === r.Dashboard()?.id);

      let item: DashboardsGroupReport = {
        dashboard: r.Dashboard()!,
        authorizations: [],
        sources: []
      };

      if (index !== -1) {
        item = groups[index];
      }

      if (r.Authorization() != null && r.Authorization()?.hasError && item.authorizations.findIndex((a) => a.id === r.Authorization()?.id) === -1) {
        item.authorizations.push(r.Authorization()!);
      }

      if (r.Source() != null && r.Source()?.hasError && item.sources.findIndex((s) => s.id === r.Source()?.id) === -1) {
        item.sources.push(r.Source()!);
      }

      if (index === -1) {
        groups.push(item);
      }

    });

    return sort(groups).asc((i) => i.dashboard.title);

  }, [dashboardsReport, query]);

  return {
    dashboards,
    onClearClick,
    onSearchChange,
    query
  };
};