import {StudioCSS} from "../../../../../../../styles/types";

export const planStyle: StudioCSS = (theme, utilities) => ({
  label: "plan",
  display: "grid",
  gridTemplateColumns: "auto auto auto",
  gap: utilities.space("t"),
  alignItems: "center",
  justifyContent: "flex-start",
  "span:first-child": {
    ...utilities.fontStyle({
      size: "regular"
    })
  },
  "span:last-child": {
    ...utilities.fontStyle({
      size: "small",
      color: "scorpion",
      weight: "l"
    })
  }
});
