import {Badge, HamburgerMenu, Hidable, Stack, Styles} from "@dashthis/ui";
import {UserModel} from "../../../../../../models/User";
import React, {HTMLAttributes} from "react";
import {Conditional} from "@dashthis/common";
import {accountUsersItemButtonGroupStyle, accountUsersItemEmailStyle, accountUsersItemGravatarContainerStyle, accountUsersItemGravatarStyle, accountUsersItemNameStyle, accountUsersItemSelectedStyle, accountUsersItemStyle} from "./styles/accountUsersItemStyle";
import Gravatar from "../../../Accounts/List/Gravatar";
import {isEmpty} from "lodash";
import {AccountUserActionMenu} from "./AccountUserActionMenu";
import {useForceUserPassword} from "../../../../../../hooks/useForceUserPassword";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The user model.
   */
  user: UserModel,
  /**
   * Indicate if the item are selected.
   */
  selected: boolean,
  /**
   *
   */
  emulateUser: (user: UserModel) => void
}

export const AccountUsersItem = (props: IProps) => {
  const {selected, user, emulateUser, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountUsersItemStyle,
    Conditional.is(selected, accountUsersItemSelectedStyle)
  );
  const gravatarContainerCss = Styles.Hooks.useClassName(accountUsersItemGravatarContainerStyle);
  const gravatarCss = Styles.Hooks.useClassName(accountUsersItemGravatarStyle);
  const emailCss = Styles.Hooks.useClassName(accountUsersItemEmailStyle);
  const nameCss = Styles.Hooks.useClassName(accountUsersItemNameStyle);
  const buttonGroupCss = Styles.Hooks.useClassName(accountUsersItemButtonGroupStyle);
  const {forcePassword} = useForceUserPassword();

  return (
    <div {...rest} className={css}>
      <Stack.HStack alignItems={Stack.Enums.AlignItemsEnum.Center}>
        <Stack.StackItem as="div" itemSize="1fr" className={gravatarContainerCss}>
          <Gravatar className={gravatarCss} user={user}/>
          <span className={emailCss}>{user.email}</span>
          <Hidable.Hidable visible={!isEmpty(user.name)}>
            <span className={nameCss}>{user.name}</span>
          </Hidable.Hidable>
        </Stack.StackItem>
        {user.isHubSpotMainContact && <Stack.StackItem type={Badge.Enums.BadgeTypeEnum.Neutral} itemSize="auto" as={Badge.Badge} text="Main contact"/>}
        {user.isHubSpotMainContact === null && user.hubSpotUri != null && <Stack.StackItem type={Badge.Enums.BadgeTypeEnum.Warning} itemSize="auto" as={Badge.Badge} text="Unable to resolve HubSpot main contact"/>}
      </Stack.HStack>
      <div className={buttonGroupCss}>
        <HamburgerMenu.HamburgerMenu menu={({hideMenu}) => <AccountUserActionMenu forcePassword={(password) => {
          forcePassword(password, user.id!).then();
        }} hideMenu={hideMenu} emulateUser={emulateUser} user={user}/>}/>
      </div>
    </div>
  );
};

export default AccountUsersItem;
