import {Enums} from "@dashthis/studio-common";
import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import {useCallback, useEffect, useRef} from "react";
import {AccountModel} from "../../../models/Account";
import {useEmulateAccount} from "./useEmulateAccount";

export const useEnabledEmulateAccountMenu = (account: AccountModel | null) => {
  const eventService = useEventServiceContext();
  const accountSelected = useRef<AccountModel | null>(null);
  const sendEventBaseOnAccountSelected = () => {
    eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.EmulateAccount, accountSelected.current != null);
  };
  const handleOnWindowFocus = useCallback(() => {
    sendEventBaseOnAccountSelected();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService]);
  const {emulateAccount} = useEmulateAccount();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const handleEmulateAccount = useCallback(() => emulateAccount(accountSelected.current!), [accountSelected]);

  useEffect(() => {
    eventService.on(Enums.IPCChannelEnum.OnWindowFocus, handleOnWindowFocus);
    eventService.on(Enums.IPCChannelEnum.EmulateAccount, handleEmulateAccount);

    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.OnWindowFocus, handleOnWindowFocus);
      eventService.removeListener(Enums.IPCChannelEnum.EmulateAccount, handleEmulateAccount);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService]);

  useEffect(() => {
    accountSelected.current = account;
    sendEventBaseOnAccountSelected();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [account]);

};