import React, {Fragment} from "react";
import {AccountModel} from "../../../../../../models/Account";
import {Styles} from "@dashthis/ui";
import DashboardsUsage from "./DashboardsUsage";
import IntegrationsUsage from "./IntegrationsUsage";
import SourcesUsage from "./SourcesUsage";
import {accountHealthBoxContainerStyle, accountHealthStyle} from "./styles/accountHealth.style";
import MostUsedIntegrations from "./MostUsedIntegrations";
import MostViewedDashboards from "./MostViewedDashboards";
import PlanUsage from "./PlanUsage";
import UsersUsage from "./UsersUsage";
import {useLoadAccountUsage} from "../../../../../../hooks/useLoadAccountUsage";
import AccountHealthLoading from "./AccountHealthLoading";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountHealth = (props: IProps) => {
  const {account} = props;
  const {matcher} = useLoadAccountUsage(account.id!);
  const css = Styles.Hooks.useClassName(accountHealthStyle);
  const boxCss = Styles.Hooks.useClassName(accountHealthBoxContainerStyle);

  return (
    <div className={css}>
      {matcher({
        onLoadAccountUsageLoading: () => <AccountHealthLoading/>,
        onLoadAccountUsageError: () => null,
        onLoadAccountUsageLoaded: (accountHealth) => (
          <Fragment>
            <div className={boxCss}>
              <PlanUsage account={account}/>
              <UsersUsage account={account}/>
            </div>
            <DashboardsUsage stats={accountHealth.DashboardsUsage}/>
            <IntegrationsUsage stats={accountHealth.IntegrationsUsage}/>
            <SourcesUsage stats={accountHealth.SourcesUsage}/>
            <MostUsedIntegrations stats={accountHealth.MostUsedIntegrations}/>
            <MostViewedDashboards stats={accountHealth.MostViewedDashboards}/>
          </Fragment>
        )
      })}
    </div>
  );
};


export default AccountHealth;
