import React, {HTMLAttributes} from "react";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import AccountDashboardViewed from "./AccountDashboardViewed";
import {Styles} from "@dashthis/ui";
import {accountDashboardHealthStyle} from "./styles/accountDashboardHealth.style";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The dashboard model
   */
  dashboard: DashboardModel;
}

export const AccountDashboardHealth = (props: IProps) => {
  const {dashboard, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, accountDashboardHealthStyle);

  return (
    <div {...rest} className={css}>
      <AccountDashboardViewed stats={dashboard.Healths!.Viewed}/>
    </div>
  );
};

export default AccountDashboardHealth;
