import {Client, DTGraphTypes, Models} from "@dashthis/common";
import {plansQuery} from "../queries/plan/plans.query";
import {useMemo} from "react";

type Response = {
  plans: DTGraphTypes.Plan[]
};

type QueryArgs = {
  id: string,
};

export const useGetPlans = (): [Models.Plan.PlanModel[], boolean, Client.Errors.ApplicationServerError] => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<QueryArgs, Response>(plansQuery);

  return useMemo(() => ([
    loading || error != null ? [] : data.plans.map((p) => Models.Plan.Plan(p)),
    loading,
    error
  ]), [data, error, loading]);
};