import {StudioCSS} from "../../../../../../styles/types";

export const headerItemStyle: StudioCSS = (theme, utilities) => ({
  label: "header-item",
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  gap: utilities.space("s"),
  backgroundColor: utilities.colors("athensGray").string(),
  height: 45,
  padding: utilities.space("n"),
  alignItems: "baseline"
});

export const headerItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "header-item-title",
  ...utilities.fontStyle({
    size: "regular",
    weight: "m"
  })
});

export const headerItemCountStyle: StudioCSS = (theme, utilities) => ({
  label: "header-item-count",
  ...utilities.fontStyle({
    size: "small",
    weight: "l",
    color: "scorpion"
  })
});
