import React, {ReactNode} from "react";
import {Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowHeaderStyle} from "./styles/fileTemplatesViewEditWindowHeader.style";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
}


export const ViewEditFileTemplateWindowHeader = (props: IProps) => {
  const {children} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesViewEditWindowHeaderStyle);

  return (
    <div className={css}>
      {children}
    </div>
  );
};


export default ViewEditFileTemplateWindowHeader;
