import React, {ReactNode} from "react";
import {Select as DefaultSelect, Styles} from "@dashthis/ui";
import {inputLoadingStyle} from "./styles/inputLoading.style";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
}

export const InputLoading = (props: IProps) => {
  const css = Styles.Hooks.useClassName(inputLoadingStyle);

  return (<DefaultSelect.InputLoading className={css}/>);
};


export default InputLoading;
