import React, {HTMLAttributes} from "react";
import {Styles} from "@dashthis/ui";
import {fileTemplatesItemSelectedStyle} from "./styles/fileTemplatesFileItem.style";
import {CsvSourceModel} from "../../../../../../../models/CsvSource";
import {fileTemplatesSourceItemStyle} from "./styles/fileTemplatesSourceItem.style";
import {Conditional} from "@dashthis/common";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The file model.
   */
  source: CsvSourceModel;
  /**
   * Indicate if the file are selected
   */
  selected: boolean;
}

export const FileTemplatesSourceItem = (props: IProps) => {
  const {source, selected, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    fileTemplatesSourceItemStyle,
    Conditional.is(selected, fileTemplatesItemSelectedStyle)
  );

  return (
    <div {...rest} className={css}>
      <span>{source.name}</span>
    </div>
  );
};


export default FileTemplatesSourceItem;
