import React, {Fragment} from "react";
import {HeaderItem} from "../HeaderItem";
import formatMessage from "format-message";
import AccountItem from "../Accounts/AccountItem";
import {AccountModel} from "../../../../../../models/Account";
import {OpenAccounts, OpenFileTemplate} from "../../../../../../states";
import {Styles} from "@dashthis/ui";
import {fileTemplateStyle} from "./styles/fileTemplateItem.style";
import FileTemplateItem from "./FileTemplateItem";
import {CsvTemplateModel} from "../../../../../../models/CsvTemplate";

interface IProps {
  /**
   * The list of account to display.
   */
  accounts: AccountModel[];
  /**
   * Callback to call to open an account.
   */
  openAccounts: OpenAccounts;
  /**
   * Count of account found
   */
  count: number;
  /**
   * Number of total account found
   */
  total: number;
  /**
   *
   */
  openFileTemplate: OpenFileTemplate;
}

export const FileTemplates = (props: IProps) => {
  const {accounts, openAccounts, count, total, openFileTemplate} = props;
  const handleDoubleClick = (account: AccountModel, e: React.MouseEvent) => {
    openAccounts(new Set([account.id!]));
    e.stopPropagation();
  };
  const handleFileTemplateDoubleClick = (account: AccountModel, fileTemplate: CsvTemplateModel) => (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    openFileTemplate(account.id!, fileTemplate.id!);

  };
  const css = Styles.Hooks.useClassName(fileTemplateStyle);

  return (
    <Fragment>
      <HeaderItem total={total} count={count} title={formatMessage("File Templates")}/>
      {accounts.map((account) => (
        <AccountItem className={css} onDoubleClick={handleDoubleClick} account={account} key={account.id!}>
          {account.CsvTemplates.map((fileTemplate) => (
            <FileTemplateItem onDoubleClick={handleFileTemplateDoubleClick(account, fileTemplate)} key={fileTemplate.id!} fileTemplate={fileTemplate}/>
          ))}
        </AccountItem>
      ))}
    </Fragment>
  );
};


export default FileTemplates;
