import React, {ReactNode} from "react";
import SelectDashboard from "../../../../../../../medias/svg/selectDashboard.inline.svg";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {accountDashboardsSelectDashboardDescriptionStyle, accountDashboardsSelectDashboardPlaceholderStyle, accountDashboardsSelectDashboardStyle, accountDashboardsSelectDashboardTitleStyle} from "../styles/accountDashboardsSelectDashboard.style";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
}

export const AccountDashboardsSelectDashboard = (props: IProps) => {
  const css = Styles.Hooks.useClassName(accountDashboardsSelectDashboardStyle);
  const titleCss = Styles.Hooks.useClassName(accountDashboardsSelectDashboardTitleStyle);
  const descriptionCss = Styles.Hooks.useClassName(accountDashboardsSelectDashboardDescriptionStyle);
  const placeholderCss = Styles.Hooks.useClassName(accountDashboardsSelectDashboardPlaceholderStyle);

  return (
    <div className={css}>
      <p className={titleCss}>{formatMessage("Select a dashboard")}</p>
      <SelectDashboard className={placeholderCss}/>
      <p className={descriptionCss}>{formatMessage("To view or edit these properties")}</p>
    </div>
  );
};


export default AccountDashboardsSelectDashboard;
