import React from "react";
import {Stack, Styles} from "@dashthis/ui";
import PlaceholderLoading from "react-placeholder-loading";
import {dashboardReportLoadingStyle} from "./styles/dashboardReportLoading.style";
import {Button, SearchField} from "../../../../../../components";
import formatMessage from "format-message";
import {dashboardsReportListFooterStyle} from "./styles/dashboardsReportList.style";

interface IProps {
}

const colorStart = "#EDF1F5";
const colorEnd = "#F4F6F9";

const ItemPlaceHolder = () => {
  const css = Styles.Hooks.useClassName(dashboardReportLoadingStyle);

  return (
    <Stack.HStack gap={5} className={css} alignItems={Stack.Enums.AlignItemsEnum.Center}>
      <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} width={22} height={22} shape="rect"/>
      <Stack.StackItem itemSize="1fr" as={Stack.VStack} gap={5}>
        <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} width={234} height={12} shape="rect"/>
        <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} width={124} height={12} shape="rect"/>
      </Stack.StackItem>
    </Stack.HStack>
  );
};

export const DashboardReportLoading = (props: IProps) => {
  const items: number[] = new Array(50).fill(1);
  const footerCss = Styles.Hooks.useClassName(dashboardsReportListFooterStyle);

  return (
    <Stack.VStack>
      <Stack.StackItem disabled as={SearchField.SearchField} placeholder={formatMessage("Search for dashboards, source or authorization...")}/>
      <Stack.StackItem itemSize="minmax(0,1fr)">
        <div>
          {items.map((i, k) => <ItemPlaceHolder key={k}/>)}
        </div>
      </Stack.StackItem>
      <Stack.StackItem className={footerCss} as="div">
        <Button.Button disabled>{formatMessage("Export as CSV")}</Button.Button>
      </Stack.StackItem>
    </Stack.VStack>
  );
};

export default DashboardReportLoading;
