import gql from "graphql-tag";
import {AccountSearchParts} from "../fragments/account/accountSearchParts";

export const searchFileTemplatesQuery = gql`
    query($query:String!,$limit:Int,$page:Int){
        fileTemplates: searchCsvTemplate(limit: $limit, page: $page, query: $query){
            count
            pages
            page
            items {
                id
                name
                account {
                    ...AccountSearchParts
                }

            }
        }
    }
    ${AccountSearchParts}
`;