import {DTGraphTypes, Models, Search} from "@dashthis/common";
import {Source, SourceModel} from "./Source";
import {Formatter, FormatterModel} from "./Formatter";
import dayjs from "dayjs";
import {isEmpty, isNil} from "lodash";

export interface IWidget extends DTGraphTypes.Widget, Search.Interfaces.IMatchableQuery {
  Sources: SourceModel[],
  Formatter: FormatterModel | undefined,
  dateAdded: string,
  hasNote: boolean
}

export type WidgetModel = Models.Types.Model<Omit<IWidget, "sources" | "formatter">>;

export const Widget: Models.Types.ModelCtr<DTGraphTypes.Widget, IWidget> = (data) => ({
  ...data,
  get hasNote() {
    return !isNil(data.note) || !isEmpty(data.note);
  },
  get dateAdded() {
    const lastAccessed = dayjs(data.dateAdded);

    return lastAccessed.calendar(undefined, {
      sameDay: "[Today at] H:mm a",
      nextDay: "[Tomorrow]",
      nextWeek: "dddd",
      lastDay: "[Yesterday]",
      lastWeek: "[Last] dddd",
      sameElse: "MMMM D, YYYY H:mm a"
    });
  },
  get Sources() {
    return Models.createModels<DTGraphTypes.Source, SourceModel>(data.sources, Source);
  },
  get Formatter() {
    return Models.createModel<DTGraphTypes.Formatter, FormatterModel>(data.formatter, Formatter);
  },
  matchQuery(query) {
    const searchableStrings = new Search.SearchableStrings(query);

    searchableStrings.add(data.title);
    searchableStrings.add(data.id);

    return searchableStrings.matchQuery();
  }
});