import React, {HTMLAttributes} from "react";
import {Icon as IconUI, Styles} from "@dashthis/ui";
import {fileTemplatesTemplateItemArrowDownIconStyle, fileTemplatesTemplateItemArrowIconStyle} from "./styles/fileTemplatesTemplateItem.style";
import {Conditional} from "@dashthis/common";
import {fileTemplatesGroupItemIconStyle, fileTemplatesGroupItemStyle} from "./styles/fileTemplatesGroupItem.style";


interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The name of group.
   */
  name: string;
  /**
   * The icon to display.
   */
  Icon: IconUI.Types.IconComponent;
  /**
   * Callback to call when use click on arrow.
   */
  onArrowClick: () => void,
  /**
   * Indicate if the group are expended
   */
  expended: boolean
}

export const FileTemplatesGroupItem = (props: IProps) => {
  const {name, Icon, onArrowClick, expended, ...rest} = props;
  const iconCss = Styles.Hooks.useClassName(fileTemplatesGroupItemIconStyle);
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, fileTemplatesGroupItemStyle);
  const arrowIconCss = Styles.Hooks.useClassName(
    fileTemplatesTemplateItemArrowIconStyle,
    Conditional.is(expended, fileTemplatesTemplateItemArrowDownIconStyle)
  );

  return (
    <div {...rest} className={css} onClick={onArrowClick}>
      <Icon className={iconCss}/>
      <span>
        {name}
      </span>
      <IconUI.Icons.ArrowRightIcon className={arrowIconCss}/>
    </div>
  );
};


export default FileTemplatesGroupItem;
