import {Icon, Styles, Taskbar} from "@dashthis/ui";
import formatMessage from "format-message";
import React from "react";
import {taskbarItemStyle} from "../../styles/taskbarItem.style";

interface IProps {
  /**
   * Callback to perform a search.
   */
  setSearchQuery: (searchQuery: string) => void;
  /**
   * Callback to remove a item in reach history
   */
  deleteSearchHistory: (searchQuery: string) => void;
  /**
   * The list of all search made by the user.
   */
  searchHistory: string[];
  /**
   * Callback to clear all items in search history.
   */
  clearSearchHistory: () => void;
}

export const SearchHistoryTaskbarCategory = (props: IProps) => {
  const {searchHistory, clearSearchHistory, deleteSearchHistory, setSearchQuery} = props;
  const taskbarItemCss = Styles.Hooks.useClassName(taskbarItemStyle);

  if (searchHistory.length === 0) {
    return null;
  }

  const clearHistoryAction = (<Taskbar.TaskbarCategoryAction onClick={clearSearchHistory} title={formatMessage("Clear")}/>);
  const handleDeleteHistoryClick = (query: string) => () => {
    deleteSearchHistory(query);
  };
  const handleSearchHistoryClick = (query: string) => () => {
    setSearchQuery(query);
  };

  return (
    <Taskbar.TaskbarCategory title={formatMessage("Search History")} action={clearHistoryAction}>
      {searchHistory.slice(0, 10).map((history, key) => (
        <Taskbar.TaskbarItem
          className={taskbarItemCss}
          action={<Taskbar.TaskbarItemAction icon={Icon.Enums.Icons.Clear} onClick={handleDeleteHistoryClick(history)}/>}
          key={key}
          text={history}
          onClick={handleSearchHistoryClick(history)}
        />
      ))}
    </Taskbar.TaskbarCategory>
  );
};


export default SearchHistoryTaskbarCategory;