import React, {HTMLAttributes} from "react";
import {AccountModel} from "../../../../../models/Account";
import {Styles} from "@dashthis/ui";
import {itemRowEvenStyle, itemRowOddStyle, itemRowSelectedStyle, itemRowStyle} from "./styles/itemRowStyle";
import {Conditional} from "@dashthis/common";
import ItemContent from "./ItemContent";

interface IProps extends Omit<HTMLAttributes<HTMLDivElement>, "onClick" | "onDoubleClick"> {
  /**
   * The account model.
   */
  account: AccountModel;
  /**
   * Callback to call when item are select by user.
   */
  onClick: (account: AccountModel, event: React.MouseEvent) => void;
  /**
   * Callback to call when item are double clicked by user.
   */
  onDoubleClick: (account: AccountModel, event: React.MouseEvent) => void;
  /**
   * Indicate if the item is selected.
   */
  selected: boolean;
  /**
   * Indicate if row are odd and if true
   * draw white background
   */
  isOdd: boolean;
}

export const Item = (props: IProps) => {
  const {account, selected, onClick, onDoubleClick, isOdd, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    itemRowStyle,
    Conditional.is(isOdd, itemRowOddStyle),
    Conditional.isNot(isOdd, itemRowEvenStyle),
    Conditional.is(selected, itemRowSelectedStyle)
  );
  const handlerDoubleClick = (e: React.MouseEvent) => {
    onDoubleClick(account, e);
  };
  const handlerClick = (e: React.MouseEvent) => {
    onClick(account, e);
  };

  return (
    <div {...rest} className={css} onDoubleClick={handlerDoubleClick} onClick={handlerClick}>
      <ItemContent account={account}/>
    </div>
  );
};


export default Item;
