import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import {useEndpointsServiceContext} from "../../../services/hooks/useEndpointsServiceContext";
import {UserModel} from "../../../models/User";
import React, {useCallback} from "react";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {accountUsersQuery} from "../../../queries/account/accountUsers.query";
import {Account, AccountModel} from "../../../models/Account";
import {generateEmulateUri} from "../helpers";
import {Client, DTGraphTypes} from "@dashthis/common";
import {useOpenUrlServiceContext} from "../../../services/hooks/useOpenUrlServiceContext";

type AccountUsersQueryVariables = {
  id: string
}

type AccountUsersQueryResponse = {
  account: DTGraphTypes.Account
}

export type UseEmulateAccountInWindow = {
  emulateUser: (user: UserModel, url?: string) => void,
  emulateUserInBrowserWindow: (user: UserModel) => void,
  emulateAccount: (account: AccountModel) => void,
  emulateAccountInBrowserWindow: (account: AccountModel) => void,
  emulateUrl: (user: UserModel) => string
}
export const useEmulateAccount = (): UseEmulateAccountInWindow => {
  const eventService = useEventServiceContext();
  const openUrlService = useOpenUrlServiceContext();
  const client = Client.Hooks.useClient();
  const endpoint = useEndpointsServiceContext();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const emulateUrl = useCallback((user: UserModel) => (`${endpoint.emulateEndpoints}?email=${encodeURIComponent(user.email)}`), []);
  const emulateUser = useCallback((user: UserModel, url?: string) => {
    eventService.sendRequestEmulateWindow(url != null ? url : `${endpoint.emulateEndpoints}?email=${encodeURIComponent(user.email)}`, user.email, user.email, endpoint.for);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService, emulateUrl]);
  const emulateUserInBrowserWindow = useCallback((user: UserModel) => {
    openUrlService.openUrl(`${endpoint.emulateEndpoints}?email=${encodeURIComponent(user.email)}`);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService, emulateUrl]);
  const emulateAccount = useCallback(async (account: AccountModel) => {
    const hideNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Emulate account...")}</Notification.LoadingNotification>);

    try {
      const response = await client.query<AccountUsersQueryResponse, AccountUsersQueryVariables>({
        query: accountUsersQuery,
        variables: {
          id: account.id!
        }
      });
      const accountUsers = Account(response.data!.account).Users;
      const userToEmulate = accountUsers[0];
      const url = generateEmulateUri(endpoint.emulateEndpoints, userToEmulate.email);

      eventService.sendRequestEmulateWindow(url, userToEmulate.email, userToEmulate.email, endpoint.for);
      hideNotification();

    } catch (e) {
      hideNotification();
      Services.clientService.Error.displayError(e, formatMessage("Error on emulate account"));
    }

  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService]);
  const emulateAccountInBrowserWindow = useCallback(async (account: AccountModel) => {
    const hideNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Emulate account...")}</Notification.LoadingNotification>);

    try {
      const response = await client.query<AccountUsersQueryResponse, AccountUsersQueryVariables>({
        query: accountUsersQuery,
        variables: {
          id: account.id!
        }
      });
      const accountUsers = Account(response.data!.account).Users;
      const userToEmulate = accountUsers[0];
      const url = generateEmulateUri(endpoint.emulateEndpoints, userToEmulate.email);

      openUrlService.openUrl(url);
      hideNotification();

    } catch (e) {
      hideNotification();
      Services.clientService.Error.displayError(e, formatMessage("Error on emulate account"));
    }

  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventService]);

  return {
    emulateUser,
    emulateUserInBrowserWindow,
    emulateAccount,
    emulateAccountInBrowserWindow,
    emulateUrl
  };
};