import React, {Fragment, useEffect, useState} from "react";
import {Item} from "./Item";
import {DTGraphTypes, Hooks} from "@dashthis/common";
import {VirtualizedList} from "@dashthis/ui";
import {memoize} from "lodash";
import {Account, AccountModel} from "../../../../../models/Account";
import NoResultMessage from "../../SearchBar/components/NoResultMessage";
import {useEnabledEmulateAccountMenu} from "../../../hooks/useEnabledEmulateAccountMenu";
import Loading from "./Loading";


interface IProps {
  /**
   * List of all accounts.
   */
  accounts?: DTGraphTypes.Account[];
  /**
   * Callback to call when item are double clicked by user.
   */
  onDoubleClick: (account: AccountModel, event: React.MouseEvent) => void;
  /**
   * Callback to load more data in list.
   */
  loadMore?: () => Promise<any>;
  loading?: boolean;
  keyList: string;

}

const getAccountModel = memoize((account: DTGraphTypes.Account) => Account(account));

export const List = (props: IProps) => {
  const {accounts = [], onDoubleClick, loadMore, keyList} = props;
  const [accountSelected, setAccountSelected] = Hooks.usePersistedState<AccountModel | null>(keyList, null);
  const handleClick = (account: AccountModel, e: React.MouseEvent) => setAccountSelected(account);
  const handleNoRowsRenderer = () => {
    return (<NoResultMessage/>);
  };
  const {listRef, onScroll, restoreScrollPosition} = VirtualizedList.Hooks.useVirtualizedListScroll(keyList, {
    thresholdEndOfScroll: 1500,
    onAlmostReachEndOfScroll: async () => {
      if (loadMore != null) {
        setLoadingMore(true);
        try {
          await loadMore();
        } finally {
          setLoadingMore(false);
        }
      }
    }
  });
  const renderItem = (item: DTGraphTypes.Account, index: number) => {
    const account = getAccountModel(item);

    return (
      <Item
        isOdd={index % 2 === 0}
        account={account}
        onClick={handleClick}
        selected={account.areSame(accountSelected!)}
        onDoubleClick={onDoubleClick}
      />
    );
  };
  const [loadingMore, setLoadingMore] = useState(false);

  useEffect(() => {
    restoreScrollPosition();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEnabledEmulateAccountMenu(accountSelected);

  return (
    <Fragment>
      {loadingMore && <Loading/>}
      <VirtualizedList.VirtualizedList<DTGraphTypes.Account>
        listRef={listRef}
        onScroll={onScroll}
        noRowsRenderer={handleNoRowsRenderer}
        items={accounts}
        estimateSize={60} keyExtractor={(i) => i.id!}
        renderItem={renderItem}
      />
    </Fragment>
  );
};

export default List;
