import {StudioCSS} from "../../../../../../../styles/types";

export const accountDashboardsItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item",
  padding: utilities.space("s"),
  "&:hover": {
    cursor: "pointer"
  }
});

export const accountDashboardsItemOddStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-odd",
  backgroundColor: utilities.colors("white").string()
});

export const accountDashboardsItemEvenStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-even",
  backgroundColor: utilities.colors("aquaHaze").string()
});

export const accountDashboardsItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-title",
  display: "block",
  ...utilities.fontStyle({
    size: "small",
    weight: "m"
  }),
  ...utilities.ellipsis()
});

export const accountDashboardsItemTitleContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-title-container",
  ...utilities.ellipsis()
});

export const accountDashboardsItemDateStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-date",
  display: "block",
  ...utilities.fontStyle({
    size: "tiny",
    weight: "l"
  }),
  ...utilities.ellipsis()
});

export const accountDashboardsItemThemeIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-theme-icon",
  width: 18,
  height: 18,
  fill: utilities.colors("primary").toString()
});

export const accountDashboardsItemLetterStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-letter",
  alignSelf: "center",
  position: "relative",
  paddingRight: utilities.space("s"),
  ...utilities.fontStyle({
    size: "massive",
    weight: "b"
  }),
  "&:after": {
    content: `""`,
    width: 1,
    height: "100%",
    right: 5,
    top: 0,
    position: "absolute",
    background: utilities.colors("scorpion").string()
  }
});

export const accountDashboardsItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-item-selected",
  backgroundColor: utilities.colors("chambray").alpha(.4).string(),
  "&:hover": {
    cursor: "default"
  }
});
