import {DTGraphTypes, Models} from "@dashthis/common";
import {DashboardViewed, DashboardViewedModel} from "./DashboardViewed";

export interface IDashboardHealth extends DTGraphTypes.DashboardHealth {
  Viewed: DashboardViewedModel[];
}

export type DashboardHealthModel = Models.Types.Model<Omit<IDashboardHealth, "viewed">>;

export const DashboardHealth: Models.Types.ModelCtr<DTGraphTypes.DashboardHealth, IDashboardHealth> = (data) => ({
  ...data,
  get Viewed() {
    return Models.createModels<DTGraphTypes.DashboardViewed, DashboardViewedModel>(data.viewed, DashboardViewed);
  }
});