import React, {ReactNode} from "react";
import {Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowTextStyle} from "./styles/fileTemplatesViewEditWindowText.style";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
}


export const ViewEditFileTemplateWindowText = (props: IProps) => {
  const {children} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesViewEditWindowTextStyle);

  return (
    <div className={css}>
      {children}
    </div>
  );
};


export default ViewEditFileTemplateWindowText;
