import {StudioCSS} from "../../../../../../../styles/types";

export const accountFeatureStyle: StudioCSS = (theme, utilities) => ({
  label: "account-feature",
  display: "grid",
  gridTemplateColumns: "1fr",
  gridTemplateRows: "auto auto minmax(0, 1fr)"
});

export const accountFeatureMessageStyle: StudioCSS = (theme, utilities) => ({
  padding: utilities.space.custom(3),
  borderBottom: `1px solid ${utilities.colors("aquaHaze").string()}`
});

export const accountFeatureItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-feature-item",
  borderBottom: `1px solid ${utilities.colors("aquaHaze").string()}`,
  padding: `${utilities.space("s")} ${utilities.space("n")}`,
  position: "relative",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  alignItems: "center"
});

export const accountFeatureItemOddStyle: StudioCSS = (theme, utilities) => ({
  label: "account-feature-item-odd",
  backgroundColor: utilities.colors("white").string()
});

export const accountFeatureItemEvenStyle: StudioCSS = (theme, utilities) => ({
  label: "account-feature-item-even",
  backgroundColor: utilities.colors("aquaHaze").string()
});

export const accountFeatureItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-feature-item-title",
  ...utilities.fontStyle({
    size: "regular",
    weight: "m"
  })
});

export const accountFeatureItemDescriptionStyle: StudioCSS = (theme, utilities) => ({
  display: "inline",
  label: "account-feature-item-description",
  ...utilities.fontStyle({
    size: "small",
    weight: "n"
  })
});

export const accountFeatureItemToggleStyle: StudioCSS = (theme, utilities) => ({
  float: "right"
});
