import React, {HTMLAttributes} from "react";
import {Spinner, Styles} from "@dashthis/ui";
import {accountActionsItemActiveStyle, accountActionsItemDescriptionStyle, accountActionsItemDisabledStyle, accountActionsItemProcessingStyle, accountActionsItemStyle, accountActionsItemTitleStyle} from "./styles/accountActionsItem.style";
import {Conditional} from "@dashthis/common";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The title of item
   */
  title: string,
  /**
   * The description of item
   */
  description: string,
  /**
   * Indicate if item in processing
   */
  processing: boolean,
  /**
   * Indicate if item are disabled
   */
  disabled: boolean
}

export const AccountActionItem = (props: IProps) => {
  const {title, description, disabled, processing, onClick, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountActionsItemStyle,
    Conditional.is(disabled, accountActionsItemDisabledStyle),
    Conditional.is(processing, accountActionsItemProcessingStyle),
    Conditional.is(!disabled && !processing, accountActionsItemActiveStyle)
  );
  const titleCss = Styles.Hooks.useClassName(accountActionsItemTitleStyle);
  const descriptionCss = Styles.Hooks.useClassName(accountActionsItemDescriptionStyle);

  return (
    <div {...rest} onClick={processing || disabled ? undefined : onClick} className={css}>
      <div>
        <p className={titleCss}>{title}</p>
        <p className={descriptionCss}>{description}</p>
      </div>
      {processing
        ? <Spinner.Wheel size={Spinner.Enums.SpinnerSizeEnum.Small}/>
        : null
      }
    </div>
  );
};


export default AccountActionItem;
