export const selectStyle = () => ({
    label: "select-dropdown",
    "&:hover": {
        cursor: "pointer"
    }
});
export const selectDisabledStyle = () => ({
    label: "select-dropdown-disabled",
    opacity: .4,
    pointerEvents: "none"
});
export const selectArrowStyle = () => ({
    label: "select-arrow",
    width: "11px",
    height: "11px",
    transition: "transform .3s ease"
});
export const selectArrowOpenStyle = () => ({
    "label": "select-arrow-open",
    transform: "rotate(180deg)"
});
export const selectArrowDisabledStyle = () => ({
    label: "select-arrow-disabled",
    opacity: .4,
    pointerEvents: "none"
});
