import {AccountModel} from "../../../../../../models/Account";
import AccountFeatureItem from "./AccountFeatureItem";
import formatMessage from "format-message";
import {SearchField} from "../../../../../../components";
import {useAccountPersistedState} from "../../hooks/useAccountPersistedState";
import {Styles, VirtualizedList, Typo} from "@dashthis/ui";
import {accountFeatureStyle, accountFeatureMessageStyle} from "./styles/accountFeatureStyle";
import {FeaturesModel} from "../../../../../../models/Features";
import React, {ChangeEventHandler, useMemo} from "react";
import NoResultMessage from "../../../SearchBar/components/NoResultMessage";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountFeatures = (props: IProps) => {
  const {account} = props;
  const cssAccountFeatures = Styles.Hooks.useClassName(accountFeatureStyle);
  const cssAccountFeaturesMessage = Styles.Hooks.useClassName(accountFeatureMessageStyle);
  const [query, setQuery] = useAccountPersistedState<string>(`accountFeaturesSearch`, "");
  const onSearchChange: ChangeEventHandler<HTMLInputElement> = (event) => {
    setQuery(event.target.value);
  };
  const handleClearOnClick = () => {
    setQuery("");
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const features = useMemo((): FeaturesModel[] => query !== "" ? account.Features.filter(f => f.matchQuery(query)) : account.Features, [query]);
  const renderItem = (feature: FeaturesModel, index: number) => {

    return (
      <AccountFeatureItem
        feature={feature}
        account={account}
        isOdd={index % 2 === 0}
      />
    );
  };
  const handleNoRowsRenderer = () => {
    return (
      <NoResultMessage message={
        query !== ""
          ? formatMessage("Your search returned no results")
          : formatMessage("This account has no features")
      }/>
    );
  };

  return (
    <div className={cssAccountFeatures}>
      <SearchField.SearchField defaultValue={query} onChange={onSearchChange} clearOnClick={handleClearOnClick} placeholder={formatMessage("Search features...")}/>
      <div className={cssAccountFeaturesMessage}>
        <Typo.Strong>{formatMessage("These are overrides, not the actual status of the features for the account.")}</Typo.Strong>
        <div>{formatMessage("When a toggle is ON, the feature will always be ON.")}</div>
        <div>{formatMessage("When a toggle is OFF, the feature will be ON only if the account meets the activation rules (based on the account plan, status, etc).")}</div>
      </div>
      <VirtualizedList.VirtualizedList noRowsRenderer={handleNoRowsRenderer} items={features} estimateSize={58} keyExtractor={(i) => i.id!} renderItem={renderItem}/>
    </div>
  );
};


export default AccountFeatures;
