import React from "react";
import {Button} from "../../../../../../components";
import {Icon, Styles} from "@dashthis/ui";
import {accountPlanActionsItemButtonsStyle, accountPlanActionsItemDescriptionStyle, accountPlanActionsItemErrorIconStyle, accountPlanActionsItemErrorStyle, accountPlanActionsItemStyle, accountPlanActionsItemTitleStyle} from "./styles/accountPlanActionsItem.style";

interface IProps {
  /**
   * The button title.
   */
  buttonTitle: string;
  /**
   * The title of this action.
   */
  title: string;
  /**
   * The description of this action.
   */
  description: string;
  /**
   * The callback to call when user click on button.
   */
  onClick: React.MouseEventHandler;
  /**
   * display error message.
   */
  error?: string;
}


export const AccountPlanActionsItem = (props: IProps) => {
  const {buttonTitle, title, description, onClick, error} = props;
  const css = Styles.Hooks.useClassName(accountPlanActionsItemStyle);
  const titleCss = Styles.Hooks.useClassName(accountPlanActionsItemTitleStyle);
  const descriptionCss = Styles.Hooks.useClassName(accountPlanActionsItemDescriptionStyle);
  const buttonsCss = Styles.Hooks.useClassName(accountPlanActionsItemButtonsStyle);
  const errorCss = Styles.Hooks.useClassName(accountPlanActionsItemErrorStyle, {
    display: error != null ? "grid" : "none"
  });
  const errorIconCss = Styles.Hooks.useClassName(accountPlanActionsItemErrorIconStyle);

  return (
    <div className={css}>
      <p className={titleCss}>{title}</p>
      <p className={descriptionCss}>{description}</p>
      <div className={buttonsCss}>
        <Button.Button disabled={error != null} onClick={onClick}>{buttonTitle}</Button.Button>
        <div className={errorCss}>
          <Icon.Icon className={errorIconCss} icon={Icon.Enums.Icons.AttentionFull}/>
          <span>{error}</span>
        </div>
      </div>
    </div>
  );
};


export default AccountPlanActionsItem;
