import {StudioCSS} from "../../../styles/types";

export const connectToDrawerStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer",
  position: "absolute",
  display: "grid",
  gridTemplateRows: "auto",
  top: 0,
  backgroundColor: utilities.colors("shark").alpha(.85).string(),
  ...utilities.boxShadow({
    offsetX: 0,
    offsetY: 4,
    blurRadius: 9
  })
});

export const connectToDrawerSheetOverlayStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-sheet-overlay",
  backgroundColor: utilities.colors("primary").alpha(.75).string()
});

export const connectToDrawerTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-title",
  paddingBottom: utilities.space("l"),
  textTransform: "uppercase",
  ...utilities.fontStyle({
    size: "small",
    color: "white"
  })
});

